def test_latency_safe_new_tests_budget_is_off_by_default(monkeypatch):
    """Prompt size must not shrink the test budget unless explicitly enabled.

    Prompt size correlates with method complexity, so using it as a test-count
    cap penalised exactly the targets with the most uncovered branches.  Latency
    is handled by round batching instead, so the cap is opt-in.
    """

    monkeypatch.delenv("TATG_LATENCY_SAFE_BUDGET", raising=False)
    monkeypatch.delenv("TATG_LATENCY_SAFE_PROMPT_CHARS", raising=False)
    monkeypatch.delenv("TATG_LATENCY_SAFE_MAX_TESTS", raising=False)

    assert TATGEngineAdapter._latency_safe_new_tests_budget(
        12,
        projected_prompt_chars=20_000,
    ) == 12
    assert TATGEngineAdapter._latency_safe_new_tests_budget(
        12,
        projected_prompt_chars=45_000,
    ) == 12


def test_latency_safe_new_tests_budget_caps_only_large_prompts(monkeypatch):
    monkeypatch.setenv("TATG_LATENCY_SAFE_BUDGET", "1")
    monkeypatch.delenv("TATG_LATENCY_SAFE_PROMPT_CHARS", raising=False)
    monkeypatch.delenv("TATG_LATENCY_SAFE_MAX_TESTS", raising=False)

    assert TATGEngineAdapter._latency_safe_new_tests_budget(
        12,
        projected_prompt_chars=20_000,
    ) == 12
    assert TATGEngineAdapter._latency_safe_new_tests_budget(
        12,
        projected_prompt_chars=45_000,
    ) == 4
    assert TATGEngineAdapter._latency_safe_new_tests_budget(
        12,
        projected_prompt_chars=45_000,
        minimum_useful_tests=8,
    ) == 8
    assert TATGEngineAdapter._latency_safe_new_tests_budget(
        3,
        projected_prompt_chars=45_000,
        minimum_useful_tests=8,
    ) == 3

    monkeypatch.setenv("TATG_LATENCY_SAFE_MAX_TESTS", "3")
    assert TATGEngineAdapter._latency_safe_new_tests_budget(
        12,
        projected_prompt_chars=45_000,
    ) == 3


def test_uncovered_branch_count_reads_measured_gap():
    assert TATGEngineAdapter._uncovered_branch_count(None) == 0
    assert TATGEngineAdapter._uncovered_branch_count({"branch_missed": 43}) == 43
    # Derived from ratio when only the fraction is carried.
    assert TATGEngineAdapter._uncovered_branch_count(
        {"branch_covered": 30, "branch_coverage": 0.5}
    ) == 30
    assert TATGEngineAdapter._uncovered_branch_count({"branch_coverage": 1.0}) == 0


def test_coverage_gap_test_budget_scales_with_uncovered_branches(monkeypatch):
    monkeypatch.delenv("TATG_COVERAGE_GAP_BUDGET", raising=False)
    monkeypatch.delenv("TATG_EXPECTED_BRANCH_YIELD_PER_TEST", raising=False)
    monkeypatch.delenv("TATG_ROUND_MAX_TESTS", raising=False)

    # No gap information leaves the incoming budget untouched.
    assert TATGEngineAdapter._coverage_gap_test_budget(4, None) == 4
    # A large gap raises the round budget; a small one does not lower it.
    assert TATGEngineAdapter._coverage_gap_test_budget(4, {"branch_missed": 37}) == 13
    assert TATGEngineAdapter._coverage_gap_test_budget(6, {"branch_missed": 3}) == 6
    # The ceiling is respected.
    assert TATGEngineAdapter._coverage_gap_test_budget(1, {"branch_missed": 400}) == 16

    monkeypatch.setenv("TATG_COVERAGE_GAP_BUDGET", "0")
    assert TATGEngineAdapter._coverage_gap_test_budget(4, {"branch_missed": 37}) == 4


def test_slice_obligation_ids_splits_disjointly():
    slices = TATGEngineAdapter._slice_obligation_ids(
        {"O1", "O2", "O3", "O4", "O5", "O6", "O7"},
        per_batch=4,
        max_batches=4,
    )
    assert slices == [{"O1", "O2", "O3", "O4"}, {"O5", "O6", "O7"}]
    # Slices never overlap, so no batch re-requests another batch's obligation.
    assert set().union(*slices) == {"O1", "O2", "O3", "O4", "O5", "O6", "O7"}
    assert slices[0] & slices[1] == set()
    assert TATGEngineAdapter._slice_obligation_ids(set(), per_batch=4, max_batches=4) == []
    assert len(
        TATGEngineAdapter._slice_obligation_ids(
            {f"O{i}" for i in range(1, 21)}, per_batch=4, max_batches=2
        )
    ) == 2


def test_merge_round_batch_results_sums_counts_and_unions_maps():
    merged = TATGEngineAdapter._merge_round_batch_results([
        {
            "status": "success",
            "final_code": "class A { void one() {} }",
            "elapsed_seconds": 10,
            "tatg_generation_attempt_count": 1,
            "tatg_generated_test_objective_map": {"t1": "O1"},
            "tatg_required_coverage_obligation_ids": ["O1", "O2"],
            "tatg_partial_required_obligation_acceptance": False,
            "usage": {"total_tokens": 100},
        },
        {
            "status": "success",
            "final_code": "class A { void one() {} void two() {} }",
            "elapsed_seconds": 14,
            "tatg_generation_attempt_count": 2,
            "tatg_generated_test_objective_map": {"t2": "O3"},
            "tatg_required_coverage_obligation_ids": ["O3"],
            "tatg_partial_required_obligation_acceptance": True,
            "usage": {"total_tokens": 140},
        },
    ])
    # The last batch's accumulated file wins; counters and maps combine.
    assert merged["final_code"] == "class A { void one() {} void two() {} }"
    assert merged["elapsed_seconds"] == 24
    assert merged["tatg_generation_attempt_count"] == 3
    assert merged["tatg_generated_test_objective_map"] == {"t1": "O1", "t2": "O3"}
    assert merged["tatg_required_coverage_obligation_ids"] == ["O1", "O2", "O3"]
    assert merged["tatg_partial_required_obligation_acceptance"] is True
    assert merged["usage"] == {"total_tokens": 240}


def test_mutation_feedback_requires_explicit_round_even_above_threshold(monkeypatch):
    monkeypatch.delenv("TATG_MUTATION_FEEDBACK_MIN_LINE_COVERAGE", raising=False)
    assert TATGEngineAdapter._mutation_feedback_min_line_coverage() == pytest.approx(0.80)
    assert not TATGEngineAdapter._mutation_feedback_allowed_for_coverage({"line_coverage": 0.79})
    assert not TATGEngineAdapter._mutation_feedback_allowed_for_coverage({
        "line_coverage": 0.95,
        "surviving_mutants": [{"status": "SURVIVED", "line": 12}],
    })
    assert TATGEngineAdapter._mutation_feedback_allowed_for_coverage({
        "line_coverage": 0.95,
        "mutation_feedback_only": True,
        "surviving_mutants": [{"status": "SURVIVED", "line": 12}],
    })


def test_functional_interface_signature_preserves_lambda_arity_hint():
    method = SimpleNamespace(
        name="setInternalChunkCallback",
        return_type="void",
        params=(("BiConsumer<ToolUseBlock, ToolResultBlock>", "callback"),),
    )

    signature = TATGEngineAdapter._shape_method_signature(method)
    hints = TATGEngineAdapter._functional_interface_hints_for_signature(signature)

    assert signature == "void setInternalChunkCallback(BiConsumer<ToolUseBlock, ToolResultBlock>)"
    assert any("arity=2" in hint for hint in hints)
    assert any("ToolUseBlock, ToolResultBlock" in hint for hint in hints)


