def test_compact_mutation_feedback_preserves_exact_line_retry_receipt():
    compact = TATGEngineAdapter._compact_mutation_feedback_for_repair({
        "mutation_feedback_only": True,
        "mutation_objectives": [{
            "id": "M1",
            "kind": "MutationReachability",
            "facts": {
                "status": "SURVIVED",
                "line": 518,
                "mutator": "boundary-condition",
                "mutation_line_reachability_retry": True,
                "mutation_line_reachability_original_status": "SURVIVED",
                "prior_mutant_line_miss_receipts": [{
                    "test_method": "testBoundary",
                    "mutant_line": 518,
                    "candidate_code_excerpt": "large diagnostic source is not copied",
                    "rejected_setup_fingerprint": "9972d9f78a3b",
                    "rejected_setup_reason": "exact_mutant_line_not_reached",
                    "forbid_exact_candidate_repetition": True,
                }],
            },
        }],
    })

    objective = compact["mutation_objectives"][0]
    assert objective["id"] == "M1"
    assert objective["facts"]["mutation_line_reachability_retry"] is True
    assert objective["facts"]["prior_mutant_line_miss_receipts"] == [{
        "test_method": "testBoundary",
        "mutant_line": 518,
        "rejected_setup_fingerprint": "9972d9f78a3b",
        "rejected_setup_reason": "exact_mutant_line_not_reached",
        "forbid_exact_candidate_repetition": True,
    }]
    assert "candidate_code_excerpt" not in objective["facts"][
        "prior_mutant_line_miss_receipts"
    ][0]


