def test_compact_mutation_feedback_preserves_bounded_state_transition_rows():
    compact = TATGEngineAdapter._compact_mutation_feedback_for_repair({
        "mutation_feedback_only": True,
        "mutation_objectives": [{
            "id": "M2",
            "kind": "MutationReachability",
            "facts": {
                "status": "NO_COVERAGE",
                "line": 80,
                "mutation_reachability_source_evidence": {
                    "qualified_state_protocol": {
                        "required_state_accesses": ["context.ready"],
                        "transition_rows": [{
                            "line": 42,
                            "assignment": "context.ready = true;",
                            "state_root": "context",
                            "state_field": "ready",
                            "control_path": [{
                                "line": 41,
                                "statement": "if (remaining < 0) {",
                                "required_outcome": "true",
                                "unbounded_diagnostic": "must not be copied",
                            }],
                        }],
                    },
                },
            },
        }],
    })

    protocol = compact["mutation_objectives"][0]["facts"][
        "mutation_reachability_source_evidence"
    ]["qualified_state_protocol"]
    assert protocol["required_state_accesses"] == ["context.ready"]
    assert protocol["transition_rows"] == [{
        "line": 42,
        "assignment": "context.ready = true;",
        "state_root": "context",
        "state_field": "ready",
        "control_path": [{
            "line": 41,
            "statement": "if (remaining < 0) {",
            "required_outcome": "true",
        }],
    }]


