def test_class_scoped_method_blocks_keep_original_source_offsets():
    source = """
package sample;

class Before {
    void target() {
        if (false) {
            return;
        }
    }
}

public class Owner {
    void helper() {}

    public void target() {
        if (true) {
            helper();
        }
    }

    static class Nested {
        public void target() {}
    }
}
""".strip()

    blocks = TATGEngineAdapter()._collect_method_blocks(
        source,
        class_name="Owner",
    )
    targets = [block for block in blocks if block["name"] == "target"]
    assert len(targets) == 1
    target = targets[0]

    expected_start = source.index("    public void target()")
    assert target["start"] == expected_start
    assert target["offset_source"] == "class_scoped_block_mapped_to_original"
    assert source[int(target["start"]):int(target["end"])] == target["body"]
    assert "if (true)" in str(target["body"])
    assert "if (false)" not in str(target["body"])


def test_source_visible_constructor_arities_include_record_canonical_constructor(tmp_path: Path):
    source = tmp_path / "com/acme/Config.java"
    source.parent.mkdir(parents=True)
    source.write_text(
        "package com.acme;\n"
        "public record Config(java.time.Duration timeout, Policy policy) {}\n",
        encoding="utf-8",
    )
    policy = tmp_path / "com/acme/Policy.java"
    policy.write_text("package com.acme; public enum Policy { SAVE }\n", encoding="utf-8")

    arities = TATGEngineAdapter._project_source_visible_constructor_arities_for_fqn(
        tmp_path,
        "com.acme.Config",
    )

    assert arities == {2}
    assert not TATGEngineAdapter._source_unavailable_constructors_in_code(
        "Config cfg = new Config(java.time.Duration.ZERO, Policy.SAVE);",
        tmp_path,
        symbol_index={"Config": ["com.acme.Config"], "Policy": ["com.acme.Policy"]},
    )
    details = TATGEngineAdapter._project_source_constructor_details_for_fqn(
        tmp_path,
        "com.acme.Config",
    )
    assert details
    assert details[0]["arity"] == 2
    assert "record-canonical" in details[0]["modifiers"]
    assert "Config()" not in details[0]["signature"]


def test_add_reflect_method_import_for_unqualified_reflection_call():
    code = (
        "package com.acme;\n"
        "import org.junit.jupiter.api.Test;\n"
        "class FooTest {\n"
        "@Test void t() throws Exception { Method m = Foo.class.getDeclaredMethod(\"hidden\"); }\n"
        "}\n"
    )

    rewritten = TATGEngineAdapter._add_reflect_method_import_for_unqualified_calls(code)

    assert "import java.lang.reflect.Method;" in rewritten
    assert "Method m = Foo.class.getDeclaredMethod" in rewritten


