def test_source_backed_baseline_skeleton_renders_between_receipt_and_source():
    receipt = """
[Generation Control Receipt]
- target=Agent.doCall
- required_target_call=doCall or a verified source-visible entry path that reaches it
- source_required_terminal_execution_path:
  - source evidence=model:Model.stream(...); exact visible signatures: Flux<ChatResponse> stream(...); required_action=return Flux.just(response) and consume with block()
- source_exact_collaborator_stub_contracts:
  - model:Model.stream(...) -> Flux<ChatResponse>; use Flux.* factories, not null
""".strip()
    skeletons = TATGEngineAdapter._build_source_backed_baseline_skeletons(
        generation_control_receipt=receipt,
        method_name="doCall",
        method_access="protected",
    )
    skeleton_section = TATGEngineAdapter._render_source_backed_baseline_skeleton_obligation(
        skeletons,
    )
    ordered = TATGEngineAdapter._order_generation_prompt_sections([
        "Source code under test:\nclass Agent {}",
        "[CALLABLE SURFACE — ground truth, only these symbols exist]\n- doCall()",
        receipt,
        "[Required Executable Path Objective]\n- target path",
        skeleton_section,
    ])

    joined = "\n\n---\n\n".join(ordered)
    assert "[Source-Backed Baseline Skeleton Obligation]" in joined
    assert "baseline_skeleton_id=B1" in joined
    assert joined.index("[Required Executable Path Objective]") < joined.index("[Source-Backed Baseline Skeleton Obligation]")
    assert joined.index("[Source-Backed Baseline Skeleton Obligation]") < joined.index("[CALLABLE SURFACE")
    assert joined.index("[Source-Backed Baseline Skeleton Obligation]") < joined.index("Source code under test:")
    assert TATGEngineAdapter._baseline_skeleton_rendered_complete(joined) is True


def test_static_target_baseline_omits_receiver_construction_fact():
    receipt = """
[Generation Control Receipt]
- target=Numbers.parse
- source_exact_receiver_construction_contracts:
  - Numbers: visible constructors: new Numbers()
""".strip()
    receiver_contract = """
[Source-Exact Receiver Construction Contract]
- Numbers: visible constructors: new Numbers()
""".strip()

    static_skeletons = TATGEngineAdapter._build_source_backed_baseline_skeletons(
        generation_control_receipt=receipt,
        receiver_construction_contract=receiver_contract,
        method_name="parse",
        method_access="public",
        target_method_is_static=True,
    )
    instance_skeletons = TATGEngineAdapter._build_source_backed_baseline_skeletons(
        generation_control_receipt=receipt,
        receiver_construction_contract=receiver_contract,
        method_name="parse",
        method_access="public",
        target_method_is_static=False,
    )

    static_facts = static_skeletons[0]["facts"]
    instance_facts = instance_skeletons[0]["facts"]
    assert any(fact["kind"] == "target_call" for fact in static_facts)
    assert not any(fact["kind"] == "receiver_construction" for fact in static_facts)
    assert any(fact["kind"] == "receiver_construction" for fact in instance_facts)


