def test_private_target_entry_argument_projection_requires_cast_runtime_subtype():
    source = """
    class Router {
        void dispatch(Base value) {
            switch (value.kind()) {
            case SPECIAL:
                hidden((Special) value);
                break;
            default:
                break;
            }
        }
        private void hidden(Special value) {}
    }
    class Base {
        Kind kind() { return Kind.BASE; }
    }
    class Special extends Base {
        Kind kind() { return Kind.SPECIAL; }
    }
    enum Kind { BASE, SPECIAL }
    """
    entries = TATGEngineAdapter()._find_public_entry_points(
        "hidden",
        source,
        target_descriptor="(LSpecial;)V",
    )

    assert len(entries) == 1
    constraint = entries[0][
        "entry_argument_runtime_type_constraints"
    ][0]
    assert constraint == {
        "entry_parameter": "value",
        "entry_parameter_position": 0,
        "entry_declared_type": "Base",
        "required_runtime_type": "Special",
        "target_parameter_position": 0,
        "target_parameter_type": "Special",
        "source_evidence": "hidden((Special) value)",
    }
    assert entries[0]["target_call_argument_rows"][0]["arguments"] == [
        "(Special) value"
    ]
    assert entries[0]["direct_forwarder_path"] is False

    skeletons = TATGEngineAdapter._build_source_backed_baseline_skeletons(
        generation_control_receipt=(
            "[Generation Control Receipt]\n- target=Router.hidden"
        ),
        source_call_state_plan="""
[Source-Derived Target State/Call Plan]
source_required_receiver_return_baselines:
- arrange `first.getItems()` as non-null collection because source immediately calls `.stream(...)` on it
- arrange `second.getItems()` as non-null collection because source immediately calls `.iterator(...)` on it
- arrange `third.getItems()` as non-null collection because source immediately calls `.size(...)` on it
- arrange `fourth.getItems()` as non-null collection because source immediately calls `.get(...)` on it
""",
        method_name="hidden",
        method_access="private",
        entry_points=entries,
    )
    rendered = (
        TATGEngineAdapter
        ._render_source_backed_baseline_skeleton_obligation(skeletons)
    )
    schema = (
        TATGEngineAdapter
        ._render_executable_baseline_schema_section(skeletons)
    )

    assert "entry argument 1 `value` must be a `Special` instance" in rendered
    assert "source calls `hidden((Special) value)`" in rendered
    assert "do not replace it with a sibling implementation" in rendered
    assert "entry argument 1 `value` must be a `Special` instance" in schema
    assert "fact[entry_argument_projection]" in schema
    projection_fact = next(
        fact
        for fact in skeletons[0]["facts"]
        if fact["kind"] == "entry_argument_projection"
    )
    assert projection_fact["entry_method"] == "dispatch"
    assert projection_fact["entry_parameter_position"] == 0
    assert (
        projection_fact["projection_status"]
        == "source_verified_direct_call"
    )
    assert schema.index("fact[target_call]") < schema.index(
        "fact[entry_argument_projection]"
    )
    assert schema.index(
        "fact[entry_argument_projection]"
    ) < schema.index("fact[producer_return_contract]")


def test_nonpublic_target_prefers_only_unconditional_direct_forwarder_entry():
    source = """
class Processor {
    public void process(Output out, Format format, Document doc) {
        printDocument(out, new Stack(format), doc);
    }
    protected void printDocument(Output out, Stack stack, Document doc) {}
}
""".strip()
    adapter = TATGEngineAdapter()
    entries = adapter._find_public_entry_points(
        "printDocument",
        source,
        target_descriptor="(LOutput;LStack;LDocument;)V",
        class_name="Processor",
    )

    assert len(entries) == 1
    assert entries[0]["direct_forwarder_path"] is True
    preferred = adapter._preferred_unconditional_entry_contract(entries)
    assert preferred["method"] == "process"
    assert "public void process(Output out, Format format, Document doc)" in str(
        preferred["signature"]
    )

    contracts = adapter._method_overload_contracts(
        source,
        "printDocument",
        class_name="Processor",
    )
    target_ids = adapter._target_overload_ids_from_descriptor(
        contracts,
        "(LOutput;LStack;LDocument;)V",
    )
    bound = adapter._bind_preferred_entry_to_overload_contracts(
        contracts,
        target_overload_ids=target_ids,
        preferred_entry=preferred,
    )
    rendered = adapter._render_overload_contracts_section(bound)
    receipt = adapter._render_generation_control_receipt(
        target_desc="Processor.printDocument",
        method_name="printDocument",
        patch_mode=True,
        suggested_tests=2,
        source_code=source,
        class_name="Processor",
        method_access="protected",
        entry_points=entries,
        preferred_entry_contract=preferred,
        target_descriptor="(LOutput;LStack;LDocument;)V",
    )

    assert "SOURCE_VISIBLE_ENTRY_CALL: public void process" in rendered
    assert "do not call the non-public helper directly" in rendered
    assert "required_target_call=exact source-visible direct-forwarder entry" in receipt
    assert "public void process(Output out, Format format, Document doc)" in receipt
    assert "required_target_call=printDocument" not in receipt

    existing_test = """
@Test
public void testExistingEntry() {
    Processor processor = new Processor();
    processor.process(output, format, document);
}
""".strip()
    scaffold_names = adapter._existing_source_proven_entry_scaffold_test_names(
        existing_test,
        preferred,
    )
    assert scaffold_names == ["testExistingEntry"]
    skeletons = adapter._build_source_backed_baseline_skeletons(
        generation_control_receipt=receipt,
        method_name="printDocument",
        method_access="protected",
        entry_points=entries,
    )
    adapter._mark_existing_entry_scaffold_satisfied(
        skeletons,
        scaffold_names,
    )
    rendered_skeleton = adapter._render_source_backed_baseline_skeleton_obligation(
        skeletons,
    )
    rendered_schema = adapter._render_executable_baseline_schema_section(
        skeletons,
    )
    assert "existing_green_entry_scaffold=testExistingEntry" in rendered_skeleton
    assert "candidate_role=branch_axis" in rendered_skeleton
    assert "candidate_role=valid_baseline or entry_path" not in rendered_skeleton
    assert "required_first_candidate_role=branch_axis" in rendered_schema
    assert "Do not reproduce it" in rendered_schema
    assert "required_first_candidate_role=valid_baseline" not in rendered_schema
    short_retry = adapter._json_patch_short_retry_prompt(
        previous_error="candidate did not compile",
        target_overload_ids=target_ids,
        target_descriptor="(LOutput;LStack;LDocument;)V",
        overload_contracts=bound,
        target_method="printDocument",
        target_class="Processor",
    )
    assert "source-visible direct-forwarder entry after Arrange" in short_retry
    assert "public void process(Output out, Format format, Document doc)" in short_retry
    assert "each @Test must invoke `printDocument(...)`" not in short_retry


