def test_executable_baseline_schema_prioritizes_precondition_producer_over_utility_noise():
    skeletons = [{
        "id": "B1",
        "facts": [
            {"id": "F1", "kind": "entry_call", "text": "call verified instance entry `run(...)`"},
            {
                "id": "F2",
                "kind": "receiver_state_or_return",
                "text": "arrange `session.events()` as non-null collection; source calls `.size(...)` on it",
            },
            {"id": "F3", "kind": "valid_input", "text": "State must be non-null"},
            {
                "id": "F4",
                "kind": "receiver_state_or_return",
                "text": "collaborator return `config.summarizer()` is assigned to local `summarizer` and source passes `summarizer` into `checkArgument(...)`; return a non-null BaseEventSummarizer",
            },
        ],
    }]
