def test_source_backed_baseline_skeleton_uses_structured_return_fact_fields():
    source_plan = """
[Source-Derived Target State/Call Plan]
source_required_receiver_return_baselines:
- arrange `memory.getMessages()` as non-null collection/stream source with the source-required baseline row; use empty only for an explicit no-item/guard objective because source immediately calls `.stream(...)` on it
source_required_collaborator_return_baselines:
- local-result dependency `response.getContent()` is dereferenced with `.stream(...)`; arrange the public path that produces local `response` so this observed return is non-null/usable.
""".strip()

    skeletons = TATGEngineAdapter._build_source_backed_baseline_skeletons(
        generation_control_receipt="[Generation Control Receipt]\n- target=Target.call",
        source_call_state_plan=source_plan,
        method_name="call",
        method_access="public",
    )
    facts = skeletons[0]["facts"]
    receiver_fact = next(fact for fact in facts if fact.get("producer_chain") == "memory.getMessages()")
    collaborator_fact = next(fact for fact in facts if fact.get("producer_chain") == "response.getContent()")

    assert receiver_fact["consumer_operation"] == "stream"
    assert "collection/stream source" in receiver_fact["required_return_shape"]
    assert collaborator_fact["required_return_shape"] == "non-null/usable observable return"

    rendered = TATGEngineAdapter._render_source_backed_baseline_skeleton_obligation(skeletons)
    assert "producer_chain=memory.getMessages()" in rendered
    assert "consumer_operation=stream" in rendered


