def test_prompt_compactor_preserves_complete_baseline_skeleton_items(monkeypatch):
    monkeypatch.setenv("TATG_PROMPT_TARGET_CHARS", "16000")
    long_facts = "\n".join(
        f"  - F{i} [receiver_state_or_return] status=active_unmet; "
        f"source=source_call_state_plan; required=collaborator return `producer{i}.getValue()` "
        f"is assigned to local `value{i}` and source later calls `value{i}.consumerOperation(...)`; "
        "for a valid baseline, return a non-null/live value via a source-visible implementation/factory "
        "or an explicit focused fake/stub, not an unstubbed default mock; "
        f"producer_chain=producer{i}.getValue(); consumer_operation=consumerOperation; "
        "required_return_shape=non-null/live source-visible value"
        for i in range(1, 14)
    )
    prompt = "\n\n---\n\n".join(
        [
            "[Generation Control Receipt]\n- target=Example.target",
            "[Source-Backed Baseline Skeleton Obligation]\n"
            "Use this current-target skeleton before branch/state variants.\n"
            "- B1; status=active_unmet; target=target; access=public\n"
            f"{long_facts}\n"
            "  required_candidate: candidate_role=valid_baseline; baseline_skeleton_id=B1",
            "[CALLABLE SURFACE — ground truth, only these symbols exist]\n" + ("method x();\n" * 2000),
            "Source code under test:\n" + ("class Noise {}\n" * 3000),
            "Requirements:\n1) compile",
        ]
    )

    compacted = TATGEngineAdapter._compact_user_prompt_to_budget(prompt)

    assert "[Source-Backed Baseline Skeleton Obligation]" in compacted
    assert not re.search(r"consumer_oper\s*(?:\n|$)", compacted)
    assert TATGEngineAdapter._baseline_skeleton_rendered_complete(compacted) is True
    assert TATGEngineAdapter._high_priority_mid_field_clip(compacted) is False


