def test_terminal_null_guard_baseline_extracts_source_precondition_calls():
    facts = TATGEngineAdapter._terminal_null_guard_baseline_facts(
        """
        Preconditions.checkArgument(
            config.summarizer() != null && session.events() != null,
            "missing setup");
        Objects.requireNonNull(service);
        Preconditions.checkArgument(optional == null || fallback != null);
        """,
        limit=8,
    )

    by_fact = {row["fact"]: row for row in facts}
    assert by_fact["config.summarizer()"]["required"] == "non_null"
