def test_private_state_target_uses_proven_producer_consumer_sequence():
    source = """
class Registry {
    private final Counter count = new Counter();
    void insert(Key key) { createInternal(key); }
    void erase(Key key) { consumeInternal(key); }
    private void createInternal(Key key) { count.incrementAndGet(); }
    private void consumeInternal(Key key) {
        if (count.get() > 0) {
            hidden(key);
        }
    }
    private void hidden(Key key) { count.decrementAndGet(); }
    boolean isEmpty() { return count.get() == 0; }
}
""".strip()
    adapter = TATGEngineAdapter()
    entry_points = adapter._find_public_entry_points("hidden", source)

    rows = adapter._source_visible_producer_consumer_sequences(
        source,
        method_name="hidden",
        class_name="Registry",
        entry_points=entry_points,
    )
    plan = adapter._initial_target_owned_state_entry_plan(
        source,
        method_name="hidden",
        class_name="Registry",
        entry_points=entry_points,
    )

    assert len(rows) == 1
    assert rows[0]["producer_method"] == "insert"
    assert rows[0]["consumer_method"] == "erase"
    assert rows[0]["shared_parameter_types"] == ["Key"]
    assert rows[0]["shared_state_fields"] == ["count"]
    assert rows[0]["observer_signature"] == "boolean isEmpty()"
    assert rows[0]["proof_status"] == "source_proven"
    assert rows[0]["enforcement"] == "advisory_until_replay"
    setup = "\n".join(str(item) for item in plan["required_setup"])
    assert "source-derived; execution proof pending" in setup
    assert "insert(Key key)" in setup
    assert "erase(Key key)" in setup
    assert "target-first variant" not in setup
    assert "never call or reflect on the private target directly" in plan["target_call"]


