def test_proven_sequence_gate_requires_same_receiver_argument_and_order():
    sequence = {
        "producer_method": "insert",
        "producer_signature": "void insert(Key key)",
        "consumer_method": "erase",
        "consumer_signature": "void erase(Key key)",
        "observer_signature": "boolean isEmpty()",
        "proof_status": "compiler_proven",
    }
    valid = """
@Test
public void testSequence() {
    Registry registry = new Registry();
    Key key = new Key();
    registry.insert(key);
    registry.erase(key);
    assertTrue(registry.isEmpty());
}
"""
    missing_producer = """
@Test
public void testSequence() {
    Registry registry = new Registry();
    Key key = new Key();
    registry.erase(key);
    assertTrue(registry.isEmpty());
}
"""
    wrong_receiver = """
@Test
public void testSequence() {
    Registry first = new Registry();
    Registry second = new Registry();
    Key key = new Key();
    first.insert(key);
    second.erase(key);
    assertTrue(second.isEmpty());
}
"""

    assert (
        TATGEngineAdapter._proven_producer_consumer_sequence_violation(
            valid,
            [sequence],
        )
        == ""
    )
    assert "missing source-proven" in (
        TATGEngineAdapter._proven_producer_consumer_sequence_violation(
            missing_producer,
            [sequence],
        )
    )
    assert "missing source-proven" in (
        TATGEngineAdapter._proven_producer_consumer_sequence_violation(
            wrong_receiver,
            [sequence],
        )
    )


