def test_guarded_removed_call_builder_prepatch_follows_unique_source_dataflow(
    tmp_path: Path,
):
    source_root = tmp_path / "src" / "main" / "java" / "demo"
    source_root.mkdir(parents=True)
    (source_root / "Mode.java").write_text(
        "package demo; public enum Mode { ON, OFF }",
        encoding="utf-8",
    )
    (source_root / "StateOwner.java").write_text(
        """
package demo;
public abstract class StateOwner {
    private final Mode mode;
    protected StateOwner(Mode mode) { this.mode = mode; }
    protected boolean isEnabled() { return mode == Mode.ON; }
}
""",
        encoding="utf-8",
    )
    (source_root / "StateBuilder.java").write_text(
        """
package demo;
public abstract class StateBuilder<B extends StateBuilder<B>> {
    protected Mode mode = Mode.OFF;
    public B configure(Mode value) { this.mode = value; return (B) this; }
}
""",
        encoding="utf-8",
    )
    (source_root / "UnrelatedWrapper.java").write_text(
        """
package demo;
public final class UnrelatedWrapper {
    public boolean isEnabled() { return false; }
}
""",
        encoding="utf-8",
    )
    (source_root / "Codec.java").write_text(
        """
package demo;
public final class Codec extends StateOwner {
    public static final class Builder extends StateBuilder<Builder> {
        public Codec get() { return new Codec(mode); }
    }
    public static Builder builder() { return new Builder(); }
    private Codec(Mode mode) { super(mode); }
    private void validate() {
        if (isEnabled()) { throw new IllegalArgumentException("invalid"); }
    }
    public void decode() { validate(); }
}
""",
        encoding="utf-8",
    )
    feedback = {
        "mutation_objectives": [{
            "id": "M1",
            "facts": {
                "status": "SURVIVED",
                "mutation_line_reachability_retry": True,
                "mutator": "remove-void-call",
                "source_line": "validate();",
            },
        }]
    }
    candidate = """
@Test
void killsRemovedCall() {
    Codec codec = Codec.builder().get();
    assertThrows(IllegalArgumentException.class, codec::decode);
}
"""

    patched, applied = (
        TATGEngineAdapter._rewrite_guarded_removed_call_builder_setup(
            candidate,
            project_root=tmp_path,
            target_fqn="demo.Codec",
            mutation_feedback=feedback,
        )
    )

    assert (
        "Codec.builder().configure(demo.Mode.ON).get()" in patched
    )
    assert applied == [
        "guarded-removed-call-builder-setup:"
        "demo.StateOwner.isEnabled->demo.StateBuilder.configure(demo.Mode.ON)"
    ]


