def test_mutation_semantic_verifier_accepts_deterministic_exact_replay():
    feedback = {
        "mutation_objectives": [
            {
                "id": "M1",
                "kind": "MutationAssertion",
                "facts": {
                    "status": "SURVIVED",
                    "line": 12,
                    "mutator": "boundary-condition",
                    "source_line": "for (int i = 0; i < ROUNDS; i++) {",
                    "source_backed_mutation_constraints": [
                        {
                            "kind": "numeric_predicate_boundary",
                            "source_predicate": "i < ROUNDS",
                            "rows": [
                                {
                                    "constraint": "i = 0",
                                    "predicate_result": True,
                                }
                            ],
                        }
                    ],
                },
                "required_setup": ["generic setup"],
                "oracle": ["generic differential"],
            }
        ]
    }
    source = """
public final class Hash {
    private static final int ROUNDS = 1000;
    public static String hash(byte[] input, String salt) {
        for (int i = 0; i < ROUNDS; i++) { input[0] ^= i; }
        return salt + input[0];
    }
}
"""
    existing = """
@Test
public void exactVector() {
    byte[] input = new byte[] { 1 };
    String actual = Hash.hash(input, "s");
    assertEquals("s9", actual);
}
"""
    payload = {
        "verdicts": [
            {
                "objective_id": "M1",
                "line": 12,
                "status": "verified",
                "runtime_state_kind": "fixed_internal",
                "recommended_test_mode": "exact_replay",
                "controlling_public_input": "input and salt",
                "control_source_evidence": [
                    "public static String hash(byte[] input, String salt)"
                ],
                "setup_recipe": [
                    "byte[] input = new byte[] { 1 };",
                    'String actual = Hash.hash(input, "s");',
                ],
                "setup_evidence": [
                    "byte[] input = new byte[] { 1 };",
                    'String actual = Hash.hash(input, "s");',
                ],
                "oracle_recipe": 'assertEquals("s9", actual);',
                "oracle_provenance": "existing_green_exact",
                "oracle_source_evidence": [
                    'assertEquals("s9", actual);'
                ],
                "generic_different_inputs_only": False,
                "original_observable": 'returns "s9"',
                "mutant_observable": 'returns "s8"',
                "observable_difference": (
                    'assertEquals("s9", actual) fails because the mutant '
                    'returns "s8"'
                ),
                "proof_uncertainty": "none",
                "reasoning": "The loop count is fixed; replay the exact vector.",
                "contradictions": [],
            }
        ],
        "uncertainties": [],
    }

    audit = TATGEngineAdapter._apply_mutation_semantic_verdicts(
        feedback,
        payload,
        source_code=source,
        existing_test=existing,
    )

    facts = feedback["mutation_objectives"][0]["facts"]
    assert audit["accepted_objective_ids"] == ["M1"]
    assert facts["mutation_semantic_verified"] is True
    assert facts["mutation_semantic_test_mode"] == "exact_replay"
    assert feedback["mutation_objectives"][0]["required_setup"] == [
        "byte[] input = new byte[] { 1 };",
        'String actual = Hash.hash(input, "s");',
    ]
    assert feedback["mutation_objectives"][0]["oracle"] == [
        'assertEquals("s9", actual);'
    ]

    section = TATGEngineAdapter._render_mutation_objective_context_section(
        feedback["mutation_objectives"]
    )
    assert "verified_source_visible_setup" in section
    assert "verified_mutant_distinguishing_oracle" in section
    assert "source_backed_boundary_rows" not in section


