def test_no_coverage_loop_termination_proof_allows_one_source_constrained_probe():
    source = "\n".join([
        "class Machine {",
        "  public void addPattern(Range range) { addRange(range); }",
        "  private void addRange(Range range) {",
        "    for (int offset = 0; offset < range.values.length; offset++) {",
        "      consume(range.values[offset]);",
        "    }",
        "  }",
        "}",
    ])
    header = "for (int offset = 0; offset < range.values.length; offset++) {"
    feedback = {
        "mutation_objectives": [{
            "id": "M1",
            "facts": {
                "status": "NO_COVERAGE",
                "line": 4,
                "source_line": header,
                "source_backed_mutation_constraints": [{
                    "kind": "operator_replacement_difference",
                    "loop_control_termination_difference": {
                        "loop_termination_difference_proven": True,
                    },
                }],
            },
        }],
    }

    selected = (
        TATGEngineAdapter
        ._mutation_semantic_source_constrained_sandbox_probe_ids(
            feedback,
            source_code=source,
            existing_test=(
                "@Test void reachesEntry() { machine.addPattern(range); }"
            ),
            target_method="addRange",
            source_visible_entry_candidates=[{
                "method": "addPattern",
                "path": ["addPattern", "addRange"],
                "preferred_for_mutation_execution": True,
                "target_call_source_evidence": "addPattern calls addRange",
            }],
        )
    )

    assert selected == ["M1"]
    facts = feedback["mutation_objectives"][0]["facts"]
    assert facts["mutation_semantic_source_constrained_probe_kind"] == (
        "loop_termination_reachability_replay"
    )
    assert "normal completion" in facts[
        "mutation_semantic_source_constrained_probe_policy"
    ]


