def test_mutation_semantic_response_schema_requires_consistency_fields():
    response_format = TATGEngineAdapter._mutation_semantic_response_format(
        max_objectives=1
    )
    verdict_schema = response_format["json_schema"]["schema"]["properties"][
        "verdicts"
    ]["items"]

    assert {
        "original_observable",
        "mutant_observable",
        "observable_difference",
        "proof_uncertainty",
    }.issubset(verdict_schema["required"])
    properties = verdict_schema["properties"]
    assert properties["reasoning"]["maxLength"] == 1200
    assert (
        properties["oracle_source_evidence"]["items"]["maxLength"]
        == 600
    )
    assert properties["setup_recipe"]["items"]["maxLength"] == 500


