def test_no_coverage_semantic_row_calibrates_mutant_replacement_oracle():
    source = """
public final class Matcher {
    public boolean match(String pattern, String path) {
        return path.endsWith(pattern.substring(1));
    }
}
"""
    feedback = {
        "mutation_objectives": [
            {
                "id": "M1",
                "kind": "MutationReachability",
                "facts": {
                    "status": "NO_COVERAGE",
                    "line": 4,
                    "mutator": "BooleanFalseReturnValsMutator",
                    "source_line": (
                        "return path.endsWith(pattern.substring(1));"
                    ),
                },
            }
        ]
    }
    payload = {
        "verdicts": [
            {
                "objective_id": "M1",
                "status": "verified",
                "runtime_state_kind": "public_input",
                "recommended_test_mode": "reachability",
                "controlling_public_input": 'pattern="*a", path="ba"',
                "control_source_evidence": [
                    "return path.endsWith(pattern.substring(1));"
                ],
                "setup_recipe": [
                    "Matcher matcher = new Matcher();",
                    'boolean actual = matcher.match("*a", "ba");',
                    "assertFalse(actual);",
                ],
                "setup_evidence": [
                    "public boolean match(String pattern, String path)"
                ],
                "input_state_delta": 'pattern="*a", path="ba"',
                "oracle_recipe": "assertFalse(actual);",
                "oracle_provenance": "source_contract",
                "original_observable": "unknown_until_replay",
                "mutant_observable": "false",
                "observable_difference": "unknown_until_replay",
                "proof_uncertainty": "oracle",
                "contradictions": [],
            }
        ]
    }

    TATGEngineAdapter._apply_mutation_semantic_verdicts(
        feedback,
        payload,
        source_code=source,
        existing_test="",
    )

    facts = feedback["mutation_objectives"][0]["facts"]
    conflict = facts[
        "mutation_semantic_mutant_replacement_oracle_conflict"
    ]
    assert conflict["conflict"] is True
    assert facts["mutation_semantic_oracle_requires_calibration"] is True
    assert facts["mutation_semantic_oracle_provenance"] == (
        "deterministic_exact_calibration"
    )
    assert "assertFalse" not in "\n".join(
        facts["mutation_semantic_setup_recipe"]
    )
    assert "__TATG_MUTATION_ORACLE_CALIBRATION__" in facts[
        "mutation_semantic_oracle_recipe"
    ]
    receipt = TATGEngineAdapter._render_mutation_execution_receipt(
        feedback["mutation_objectives"]
    )
    if receipt:
        assert "forbidden_mutant_oracle" in receipt


def test_mutation_semantic_verifier_accepts_source_only_public_reachability():
    feedback = {
        "mutation_objectives": [
            {
                "id": "M1",
                "kind": "MutationReachability",
                "facts": {
                    "status": "NO_COVERAGE",
                    "line": 4,
                    "mutator": "BooleanFalseReturnValsMutator",
                    "source_line": (
                        "return path.endsWith(pattern.substring(1));"
                    ),
                },
            }
        ]
    }
    source = """
public final class Matcher {
    public boolean match(String pattern, String path) {
        if (pattern.startsWith("*")) {
            return path.endsWith(pattern.substring(1));
        }
        return false;
    }
}
"""
    payload = {
        "verdicts": [
            {
                "objective_id": "M1",
                "line": 4,
                "status": "verified",
                "runtime_state_kind": "public_input",
                "recommended_test_mode": "reachability",
                "controlling_public_input": "pattern and path",
                "control_source_evidence": [
                    'if (pattern.startsWith("*"))',
                    "return path.endsWith(pattern.substring(1));",
                ],
                "setup_recipe": [
                    (
                        'boolean actual = new Matcher().match("*a", "ba");'
                    )
                ],
                "setup_evidence": [
                    "public boolean match(String pattern, String path)"
                ],
                "input_state_delta": 'pattern = "*a"; path = "ba"',
                "oracle_recipe": "assertTrue(actual);",
                "oracle_provenance": "source_contract",
                "oracle_source_evidence": [
                    "return path.endsWith(pattern.substring(1));"
                ],
                "generic_different_inputs_only": False,
                "original_observable": "original returns true",
                "mutant_observable": "not_required_for_reachability",
                "observable_difference": "not_required_for_reachability",
                "proof_uncertainty": "none",
                "reasoning": (
                    "The visible arguments select the guarded return and the "
                    "source proves the exact true result."
                ),
                "contradictions": [],
            }
        ],
        "uncertainties": [],
    }

    audit = TATGEngineAdapter._apply_mutation_semantic_verdicts(
        feedback,
        payload,
        source_code=source,
        existing_test="",
    )

    assert audit["accepted_objective_ids"] == ["M1"]
    objective = feedback["mutation_objectives"][0]
    assert objective["facts"]["mutation_semantic_verified"] is True
    assert (
        "Apply exact mutant-distinguishing input/state delta: "
        'pattern = "*a"; path = "ba"'
    ) in objective["required_setup"]
    assert objective["oracle"] == ["assertTrue(actual);"]


def test_mutation_semantic_entry_guard_rejects_literal_argument_early_return():
    source = '''
public final class Matcher {
    private static final char STAR = '*';
    public boolean match(String pattern, String path) {
        if (pattern.isEmpty()) {
            return path.isEmpty();
        }
        if (pattern.charAt(0) == STAR) {
            if (pattern.length() == 1) {
                return path.isEmpty();
            }
            return match(pattern.substring(1), path);
        }
        return false;
    }
}
'''
    objective_line = next(
        index
        for index, line in enumerate(source.splitlines(), start=1)
        if "return match(pattern.substring(1), path);" in line
    )
    verdict = {
        "setup_recipe": [
            "Matcher matcher = new Matcher();",
            'boolean actual = matcher.match("*", "value");',
        ]
    }

    result = TATGEngineAdapter._mutation_semantic_setup_entry_guard_consistency(
        verdict,
        source_code=source,
        objective_line=objective_line,
    )

    assert result["consistent"] is False
    assert (
        "setup_literal_argument_triggers_target_early_exit_guard"
        in result["reasons"]
    )
    assert result["claims"][0]["guard"] == "pattern.length() == 1"


def test_mutation_semantic_entry_guard_keeps_literal_deep_path_and_unknown_input():
    source = '''
public final class Matcher {
    private static final char STAR = '*';
    public boolean match(String pattern, String path) {
        if (pattern.isEmpty()) return path.isEmpty();
        if (pattern.charAt(0) == STAR) {
            if (pattern.length() == 1) return path.isEmpty();
            return match(pattern.substring(1), path);
        }
        return false;
    }
}
'''
    objective_line = next(
        index
        for index, line in enumerate(source.splitlines(), start=1)
        if "return match(pattern.substring(1), path);" in line
    )
    deep = {
        "setup_recipe": [
            "Matcher matcher = new Matcher();",
            'boolean actual = matcher.match("*a", "ba");',
        ]
    }
    unknown = {
        "setup_recipe": [
            "Matcher matcher = new Matcher();",
            "boolean actual = matcher.match(patternFromFixture, path);",
        ]
    }

    assert TATGEngineAdapter._mutation_semantic_setup_entry_guard_consistency(
        deep,
        source_code=source,
        objective_line=objective_line,
    )["consistent"] is True
    assert TATGEngineAdapter._mutation_semantic_setup_entry_guard_consistency(
        unknown,
        source_code=source,
        objective_line=objective_line,
    )["consistent"] is True


