def test_mutation_semantic_apply_blocks_mixed_private_and_entry_return_shapes():
    source = "\n".join([
        "final class Owner {",
        "  public String visibleEntry(String input) {",
        '    return String.join("|", hiddenTarget(input));',
        "  }",
        "  private String[] hiddenTarget(String input) {",
        "    if (input.length() == 1) { return new String[] { input }; }",
        "    return new String[] { input, input };",
        "  }",
        "}",
    ])
    feedback = {
        "mutation_objectives": [{
            "id": "M1",
            "facts": {
                "status": "SURVIVED",
                "line": 6,
                "source_backed_mutation_constraints": [{
                    "mutant_distinguishing_rows": [{
                        "constraint": "input.length() = 1",
                    }],
                }],
            },
        }],
    }
    payload = {
        "verdicts": [{
            "objective_id": "M1",
            "status": "verified",
            "runtime_state_kind": "public_input",
            "recommended_test_mode": "exact_replay",
            "controlling_public_input": 'input = "A"',
            "control_source_evidence": [
                "public String visibleEntry(String input) {",
            ],
            "setup_recipe": [
                "Owner owner = new Owner();",
                'String[] result = owner.visibleEntry("A");',
            ],
            "setup_evidence": [
                "public String visibleEntry(String input) {",
            ],
            "input_state_delta": "input.length() = 1",
            "oracle_recipe": 'assertArrayEquals(new String[] { "A" }, result);',
            "oracle_provenance": "existing_green_exact",
            "oracle_source_evidence": [
                'assertArrayEquals(new String[] { "A" }, result);',
            ],
            "generic_different_inputs_only": False,
            "original_observable": "[A]",
            "mutant_observable": "[A, A]",
            "observable_difference": "one versus two values",
            "proof_uncertainty": "none",
            "contradictions": [],
        }],
    }
    candidates = TATGEngineAdapter._mutation_source_visible_entry_candidates([{
        "method": "visibleEntry",
        "access": "public",
        "path": ["visibleEntry", "hiddenTarget"],
        "signature": "public String visibleEntry(String input) {",
        "target_call_argument_rows": [{
            "source_evidence": "hiddenTarget(input)",
        }],
    }])

    audit = TATGEngineAdapter._apply_mutation_semantic_verdicts(
        feedback,
        payload,
        source_code=source,
        existing_test=(
            'assertArrayEquals(new String[] { "A" }, result);'
        ),
        source_visible_entry_candidates=candidates,
    )

    assert audit["accepted_count"] == 0
    assert audit["replay_required_count"] == 0
    reasons = audit["rejection_reasons_by_objective"]["M1"]
    assert any(
        reason.startswith("entry_return_array_rank_mismatch:")
        for reason in reasons
    )
    consistency = feedback["mutation_objectives"][0]["facts"][
        "mutation_semantic_entry_return_contract_consistency"
    ]
    assert consistency["consistent"] is False


def test_mutation_semantic_prompt_requires_preferred_direct_private_entry():
    source = """
final class Formatter {
    public static String cachedFacade(String pattern) {
        return createCached(pattern);
    }
    static void appendDirect(Builder builder, String pattern) {
        hiddenTarget(builder, pattern);
    }
    private static void hiddenTarget(Builder builder, String pattern) {
        if (pattern.length() >= 4) {
            builder.full();
        }
    }
}
"""
    candidates = [{
        "method": "appendDirect",
        "access": "package-private",
        "signature": (
            "static void appendDirect(Builder builder, String pattern) {"
        ),
        "path": ["appendDirect", "hiddenTarget"],
        "path_length": 2,
        "calls_target_directly": True,
        "preferred_for_mutation_execution": True,
        "target_call_source_evidence": [
            "hiddenTarget(builder, pattern)"
        ],
    }]

    prompt = TATGEngineAdapter._mutation_semantic_prompt(
        class_name="Formatter",
        method_name="hiddenTarget",
        target_descriptor="(LBuilder;Ljava/lang/String;)V",
        source_code=source,
        existing_test=(
            'assertEquals("full", Formatter.cachedFacade("MMMM"));'
        ),
        mutation_objectives=[{
            "id": "M1",
            "facts": {
                "status": "SURVIVED",
                "line": 10,
                "source_line": "if (pattern.length() >= 4) {",
                "mutator": "ConditionalsBoundaryMutator",
            },
        }],
        source_visible_entry_candidates=candidates,
    )

    assert '"preferred_for_mutation_execution":true' in prompt
    assert '"method":"appendDirect"' in prompt
    assert "must invoke one such direct caller" in prompt
    assert "do not retain a longer transitive facade as the ACT" in prompt


def test_mutation_observer_candidates_require_source_transition_and_green_assertion():
    source = """
final class Formatter {
    static void appendDirect(Builder builder, String pattern) {
        hiddenTarget(builder, pattern);
    }
    private static void hiddenTarget(Builder builder, String pattern) {
        if (pattern.length() >= 4) {
            builder.full();
        }
    }
    private static Output create(String pattern) {
        Builder builder = new Builder();
        hiddenTarget(builder, pattern);
        Output output = null;
        output = builder.finish();
        return output;
    }
}
"""
    existing_test = """
@Test
public void formatsOutput() {
    Output output = Formatter.cachedFacade("MMMM");
    String rendered = output.render(fixture);
    assertEquals("October", rendered);
}
"""
    entries = [{
        "method": "appendDirect",
        "access": "package-private",
        "signature": (
            "static void appendDirect(Builder builder, String pattern) {"
        ),
        "path": ["appendDirect", "hiddenTarget"],
        "path_length": 2,
        "calls_target_directly": True,
        "preferred_for_mutation_execution": True,
        "target_call_argument_rows": [{
            "arguments": ["builder", "pattern"],
            "source_evidence": "hiddenTarget(builder, pattern)",
        }],
    }]

    rows = (
        TATGEngineAdapter._mutation_source_visible_observer_candidates(
            source_code=source,
            existing_test=existing_test,
            method_name="hiddenTarget",
            source_visible_entry_candidates=entries,
        )
    )

    observers = rows[0]["post_entry_observer_candidates"]
    assert observers[0]["transition_call"] == "builder.finish()"
    assert observers[0]["terminal_observer_call"] == (
        "output.render(fixture)"
    )
    assert observers[0]["required_oracle_call_methods"] == [
        "finish",
        "render",
    ]
    assert observers[0]["proof_status"] == (
        "source_post_target_and_green_assertion"
    )
    assert observers[0]["existing_test_assertion_evidence"] == (
        'assertEquals("October", rendered);'
    )


def test_mutation_direct_entry_gate_requires_complete_proven_observer_chain():
    candidates = [{
        "method": "appendDirect",
        "preferred_for_mutation_execution": True,
        "post_entry_observer_candidates": [{
            "transition_method": "finish",
            "terminal_observer_method": "render",
            "required_oracle_call_methods": ["finish", "render"],
        }],
    }]

    conceptual = (
        TATGEngineAdapter._mutation_semantic_direct_entry_consistency(
            {
                "setup_recipe": [
                    'Formatter.appendDirect(builder, "MMMM")'
                ],
                "oracle_recipe": (
                    "assertTrue(builder contains FullPrinter)"
                ),
            },
            source_visible_entry_candidates=candidates,
        )
    )
    incomplete = (
        TATGEngineAdapter._mutation_semantic_direct_entry_consistency(
            {
                "setup_recipe": [
                    'Formatter.appendDirect(builder, "MMMM")'
                ],
                "oracle_recipe": (
                    'assertEquals("October", builder.finish())'
                ),
            },
            source_visible_entry_candidates=candidates,
        )
    )
    facade_with_observer = (
        TATGEngineAdapter._mutation_semantic_direct_entry_consistency(
            {
                "setup_recipe": [
                    'Formatter.cachedFacade("MMMM")'
                ],
                "oracle_recipe": (
                    'assertEquals("October", '
                    "builder.finish().render(fixture));"
                ),
            },
            source_visible_entry_candidates=candidates,
        )
    )
    facade_with_terminal_observer = (
        TATGEngineAdapter._mutation_semantic_direct_entry_consistency(
            {
                "setup_recipe": [
                    'Formatter.cachedFacade("MMMM")'
                ],
                "oracle_recipe": (
                    'assertEquals("October", '
                    "formatter.render(fixture));"
                ),
            },
            source_visible_entry_candidates=candidates,
        )
    )
    complete = (
        TATGEngineAdapter._mutation_semantic_direct_entry_consistency(
            {
                "setup_recipe": [
                    'Formatter.appendDirect(builder, "MMMM")'
                ],
                "oracle_recipe": (
                    'assertEquals("October", '
                    "builder.finish().render(fixture));"
                ),
            },
            source_visible_entry_candidates=candidates,
        )
    )

    assert conceptual["consistent"] is False
    assert incomplete["consistent"] is False
    assert facade_with_observer["consistent"] is False
    assert facade_with_observer[
        "rebindable_for_candidate_replay"
    ] is True
    assert facade_with_terminal_observer["consistent"] is False
    assert facade_with_terminal_observer[
        "rebindable_for_candidate_replay"
    ] is True
    assert (
        facade_with_terminal_observer[
            "terminal_matched_observer_candidate_count"
        ]
        == 1
    )
    assert complete["consistent"] is True
    assert complete["grounded_observer_calls"] == ["finish", "render"]
    assert complete["matched_observer_candidate_count"] == 1


