def test_mutation_semantic_verifier_does_not_stop_at_replay_hypothesis(
    monkeypatch,
):
    chat_objective_ids: list[str] = []

    def fake_chat_completion(**kwargs):
        prompt = str(kwargs.get("user_prompt") or "")
        objective_id = "M1" if '"M1"' in prompt else "M2"
        chat_objective_ids.append(objective_id)
        return {
            "content": json.dumps({
                "verdicts": [{"objective_id": objective_id}],
                "uncertainties": [],
            }),
            "usage": {},
        }

    def fake_apply(
        cls,
        coverage_feedback,
        payload,
        **_kwargs,
    ):
        objective_ids = [
            str(row.get("objective_id") or "")
            for row in list(payload.get("verdicts") or [])
            if isinstance(row, dict)
        ]
        accepted = [item for item in objective_ids if item == "M2"]
        replay = [item for item in objective_ids if item == "M1"]
        eligible = [*accepted, *replay]
        return {
            "candidate_count": len(
                list(coverage_feedback.get("mutation_objectives") or [])
            ),
            "verdict_count": len(objective_ids),
            "accepted_count": len(accepted),
            "accepted_objective_ids": accepted,
            "replay_required_count": len(replay),
            "replay_required_objective_ids": replay,
            "eligible_count": len(eligible),
            "eligible_objective_ids": eligible,
            "rejection_reasons_by_objective": {
                item: ["setup_requires_candidate_replay"]
                for item in replay
            },
            "status_counts": {},
            "verdict_summaries": [],
            "uncertainties": [],
        }

    monkeypatch.setattr(
        "tatg.engines.tatg_adapter.chat_completion_with_usage",
        fake_chat_completion,
    )
    monkeypatch.setattr(
        TATGEngineAdapter,
        "_apply_mutation_semantic_verdicts",
        classmethod(fake_apply),
    )
    feedback = {
        "mutation_objectives": [
            {"id": "M1", "facts": {"status": "SURVIVED"}},
            {"id": "M2", "facts": {"status": "SURVIVED"}},
        ],
        "test_objectives": [
            {"id": "M1", "kind": "MutationAssertion"},
            {"id": "M2", "kind": "MutationAssertion"},
        ],
    }
    request = SimpleNamespace(
        api_base="http://127.0.0.1:11435/v1",
        model="local-model",
        llm_timeout_seconds=600,
    )

    filtered, audit = TATGEngineAdapter._verify_mutation_objective_semantics(
        request=request,
        coverage_feedback=feedback,
        class_name="Foo",
        method_name="target",
        target_descriptor="(I)Z",
        source_code=(
            "public class Foo { public boolean target(int value) { "
            "return value == 1; } }"
        ),
        existing_test="",
        api_key_env="OPENAI_API_KEY",
    )

    assert chat_objective_ids == ["M1", "M1", "M2"]
    assert audit["attempted_objective_ids"] == ["M1", "M2"]
    assert audit["generation_objective_ids_before_proof_ranking"] == [
        "M1",
        "M2",
    ]
    assert audit["generation_objective_ids_after_proof_ranking"] == [
        "M2",
        "M1",
    ]
    assert [row["id"] for row in filtered["mutation_objectives"]] == ["M2"]


