def test_mutation_refinement_receives_proposed_setup_dependency_sources(
    monkeypatch,
    tmp_path: Path,
):
    source_root = tmp_path / "src/main/java/com/acme"
    source_root.mkdir(parents=True)
    target_source = "\n".join([
        "package com.acme;",
        "final class Parser {",
        "  boolean target(Format format) { return format != null; }",
        "}",
    ])
    (source_root / "Parser.java").write_text(
        target_source,
        encoding="utf-8",
    )
    (source_root / "Format.java").write_text(
        "\n".join([
            "package com.acme;",
            "final class Format {",
            "  private Format(Builder builder) { validate(builder); }",
            "  private void validate(Builder builder) {",
            "    if (builder.duplicate && builder.mode == DuplicateMode.DISALLOW) {",
            "      throw new IllegalArgumentException(\"duplicate\");",
            "    }",
            "  }",
            "  static final class Builder {",
            "    boolean duplicate; DuplicateMode mode;",
            "    static Builder create() { return new Builder(); }",
            "    Builder duplicate(boolean value) { duplicate = value; return this; }",
            "    Builder mode(DuplicateMode value) { mode = value; return this; }",
            "    Format build() { return new Format(this); }",
            "  }",
            "}",
        ]),
        encoding="utf-8",
    )
    (source_root / "DuplicateMode.java").write_text(
        "package com.acme; enum DuplicateMode { ALLOW, DISALLOW }",
        encoding="utf-8",
    )
    prompts: list[str] = []

    def fake_chat_completion(**kwargs):
        prompt = kwargs["user_prompt"]
        prompts.append(prompt)
        verdict = {
            "objective_id": "M1",
            "line": 3,
            "status": "not_proven",
            "runtime_state_kind": "receiver_state",
            "recommended_test_mode": "exact_replay",
            "controlling_public_input": "Format with duplicate values",
            "control_source_evidence": [
                "return format != null;",
            ],
            "setup_recipe": [
                "Format format = Format.Builder.create()"
                ".duplicate(true).mode(DuplicateMode.DISALLOW).build();"
            ],
            "setup_evidence": ["Format.Builder.build()"],
            "input_state_delta": "duplicate=true, mode=DISALLOW",
            "oracle_recipe": "assertTrue(new Parser().target(format));",
            "oracle_provenance": "source_contract",
            "oracle_source_evidence": ["return format != null;"],
            "generic_different_inputs_only": False,
            "reasoning": "The proposed setup still requires validation.",
            "contradictions": ["Builder preconditions are not yet proven."],
        }
        return {
            "content": json.dumps({
                "verdicts": [verdict],
                "uncertainties": [],
            }),
            "usage": {},
        }

    monkeypatch.setattr(
        "tatg.engines.tatg_adapter.chat_completion_with_usage",
        fake_chat_completion,
    )
    request = SimpleNamespace(
        api_base="http://127.0.0.1:11435/v1",
        model="local-model",
        llm_timeout_seconds=600,
        project_root=tmp_path,
    )
    feedback = {
        "mutation_objectives": [{
            "id": "M1",
            "facts": {
                "status": "NO_COVERAGE",
                "line": 3,
                "source_line": "return format != null;",
            },
        }],
        "test_objectives": [{
            "id": "M1",
            "kind": "MutationReachability",
        }],
    }

    _filtered, audit = TATGEngineAdapter._verify_mutation_objective_semantics(
        request=request,
        coverage_feedback=feedback,
        class_name="Parser",
        method_name="target",
        target_descriptor="(Lcom/acme/Format;)Z",
        source_code=target_source,
        existing_test="",
        api_key_env="OPENAI_API_KEY",
    )

    assert len(prompts) == 2
    refinement_prompt = prompts[1]
    assert "throw new IllegalArgumentException" in refinement_prompt
    assert "enum DuplicateMode" in refinement_prompt
    assert "prior setup recipe is untrusted" in refinement_prompt
    assert audit["proposed_setup_dependency_context_used"] is True
    assert audit["proposed_setup_dependency_method_count"] >= 3
    assert audit["proposed_setup_type_declaration_count"] == 1


def test_mutation_semantic_refinement_does_not_retry_contradictory_guard_setup(
    monkeypatch,
):
    calls: list[str] = []

    def fake_chat_completion(**kwargs):
        prompt = kwargs["user_prompt"]
        if "[Bounded Mutation Reachability Correction]" in prompt:
            phase = "correction"
        elif "[Independent Verdict Refinement]" in prompt:
            phase = "refinement"
        else:
            phase = "analysis"
        calls.append(phase)
        common = {
            "objective_id": "M1",
            "line": 4,
            "runtime_state_kind": "derived_local",
            "recommended_test_mode": "reachability",
            "generic_different_inputs_only": False,
            "mutant_observable": "not_required_for_reachability",
            "observable_difference": "not_required_for_reachability",
            "contradictions": [],
        }
        if phase == "analysis":
            verdict = {
                **common,
                "status": "not_proven",
                "controlling_public_input": "unknown",
                "control_source_evidence": [],
                "setup_recipe": [],
                "setup_evidence": [],
                "input_state_delta": "unknown",
                "oracle_recipe": "unknown",
                "oracle_provenance": "unsupported",
                "oracle_source_evidence": [],
                "original_observable": "unknown",
                "proof_uncertainty": "reachability",
                "reasoning": "Needs a source-order check.",
            }
        elif phase == "refinement":
            verdict = {
                **common,
                "status": "verified",
                "controlling_public_input": "value = 1, context.done = true",
                "control_source_evidence": [
                    "if (value == 1) { return true; }"
                ],
                "setup_recipe": [
                    "Context context = new Context();",
                    "context.done = true;",
                    "boolean actual = new Foo().target(1, context);",
                ],
                "setup_evidence": [
                    "public boolean target(int value, Context context)"
                ],
                "input_state_delta": "value = 1",
                "oracle_recipe": "assertTrue(actual);",
                "oracle_provenance": "source_contract",
                "oracle_source_evidence": ["return true;"],
                "original_observable": "true",
                "proof_uncertainty": "none",
                "reasoning": "Preloads done before the call.",
            }
        else:
            verdict = {
                **common,
                "status": "verified",
                "controlling_public_input": "value = 1",
                "control_source_evidence": [
                    "if (value == 1) { return true; }"
                ],
                "setup_recipe": [
                    "Context context = new Context();",
                    "boolean actual = new Foo().target(1, context);",
                ],
                "setup_evidence": [
                    "public boolean target(int value, Context context)"
                ],
                "input_state_delta": "value = 1",
                "oracle_recipe": "assertTrue(actual);",
                "oracle_provenance": "source_contract",
                "oracle_source_evidence": ["return true;"],
                "original_observable": "true",
                "proof_uncertainty": "none",
                "reasoning": "The default state passes the early guard.",
            }
        return {
            "content": json.dumps({"verdicts": [verdict], "uncertainties": []}),
            "usage": {},
        }

    monkeypatch.setattr(
        "tatg.engines.tatg_adapter.chat_completion_with_usage",
        fake_chat_completion,
    )
    source = "\n".join([
        "public class Foo {",
        "  public boolean target(int value, Context context) {",
        "    if (context.done) { return false; }",
        "    if (value == 1) { return true; }",
        "    return false;",
        "  }",
        "}",
    ])
    feedback = {
        "mutation_objectives": [{
            "id": "M1",
            "facts": {
                "status": "NO_COVERAGE",
                "line": 4,
                "source_line": "if (value == 1) { return true; }",
            },
        }],
        "test_objectives": [{"id": "M1", "kind": "MutationReachability"}],
    }
    request = SimpleNamespace(
        api_base="http://127.0.0.1:11435/v1",
        model="local-model",
        llm_timeout_seconds=600,
    )

    filtered, audit = TATGEngineAdapter._verify_mutation_objective_semantics(
        request=request,
        coverage_feedback=feedback,
        class_name="Foo",
        method_name="target",
        target_descriptor="(ILContext;)Z",
        source_code=source,
        existing_test="",
        api_key_env="OPENAI_API_KEY",
    )

    assert calls == ["analysis", "refinement"]
    assert audit["accepted_objective_ids"] == []
    assert audit["verification_call_count"] == 2
    assert filtered["mutation_objectives"] == []


def test_mutation_semantic_verifier_requires_boundary_distinguishing_delta():
    feedback = {
        "mutation_objectives": [{
            "id": "M1",
            "facts": {
                "status": "SURVIVED",
                "source_backed_mutation_constraints": [{
                    "kind": "numeric_predicate_boundary",
                    "source_predicate": "value < 0",
                    "mutant_distinguishing_rows": [{
                        "constraint": "value = 0",
                    }],
                }],
            },
        }]
    }
    payload = {
        "verdicts": [{
            "objective_id": "M1",
            "line": 10,
            "status": "verified",
            "runtime_state_kind": "public_input",
            "recommended_test_mode": "exact_replay",
            "controlling_public_input": "value",
            "control_source_evidence": ["int target(int value)"],
            "setup_recipe": ["target(-1)"],
            "setup_evidence": ["target(-1)"],
            "input_state_delta": "value = -1",
            "oracle_recipe": "assertEquals(true, result);",
            "oracle_provenance": "existing_green_exact",
            "oracle_source_evidence": ["assertEquals(true, result);"],
            "generic_different_inputs_only": False,
            "reasoning": "The existing test reaches the original branch.",
            "contradictions": [],
        }],
        "uncertainties": [],
    }
    source = "int target(int value) { return value < 0 ? 1 : 0; }"
    existing = (
        "target(-1); int result = 1; "
        "assertEquals(true, result);"
    )

    audit = TATGEngineAdapter._apply_mutation_semantic_verdicts(
        feedback,
        payload,
        source_code=source,
        existing_test=existing,
    )

    assert audit["accepted_count"] == 0
    facts = feedback["mutation_objectives"][0]["facts"]
    assert facts["mutation_semantic_distinguishes_boundary_mutant"] is False


def test_mutation_semantic_setup_consistency_rejects_zero_source_dependency():
    facts = {
        "source_backed_mutation_constraints": [{
            "mutant_distinguishing_rows": [{
                "constraint": "h2 != 0 at line 4",
            }],
        }],
    }
    verdict = {
        "controlling_public_input": "16 input bytes and seed 0",
        "setup_recipe": ["hash128x64(data, 0, 16, 0)"],
        "setup_evidence": ["hash128x64(data, 0, 16, 0)"],
        "control_source_evidence": [
            "hash128x64(byte[] data, int offset, int length, int seed)"
        ],
    }
    source = "\n".join([
        "static long[] target(int seed) {",
        "  long h2 = seed;",
        "  long h1 = 1;",
        "  h1 += h2;",
        "  return new long[] {h1, h2};",
        "}",
    ])

    result = (
        TATGEngineAdapter._mutation_semantic_distinguishing_setup_consistency(
            facts=facts,
            verdict=verdict,
            source_code=source,
        )
    )

    assert result["applicable"] is True
    assert result["consistent"] is False
    assert result["reasons"] == [
        "distinguishing_runtime_dependency_evidence_missing:h2",
        "distinguishing_setup_contradicts_nonzero_constraint:h2<-seed=0",
    ]


