def test_mutation_semantic_equal_immediate_observable_admits_proven_state_sequence():
    source = "\n".join([
        "final class Parser {",
        "  private Token current;",
        "  public Token nextToken() {",
        "    if (current != null) { return current; }",
        "    return current = readNext();",
        "  }",
        "  private Token readNext() { return Token.VALUE; }",
        "}",
    ])
    feedback = {
        "mutation_objectives": [{
            "id": "M1",
            "facts": {
                "status": "SURVIVED",
                "line": 4,
                "source_line": (
                    "if (current != null) { return current; }"
                ),
                "source_backed_mutation_constraints": [{
                    "kind": "null_predicate_partition",
                    "rows": [{"constraint": "current != null"}],
                }],
                "mutation_reachability_source_evidence": {
                    "control_path": [{
                        "line": 4,
                        "kind": "if",
                        "statement": (
                            "if (current != null) { return current; }"
                        ),
                    }],
                },
                "mutation_semantic_status": "verified",
                "mutation_semantic_runtime_state_kind": "receiver_state",
                "mutation_semantic_original_observable": "Token.VALUE",
                "mutation_semantic_mutant_observable": "Token.VALUE",
                "mutation_semantic_rejection_reasons": [
                    "original_and_mutant_observables_equal"
                ],
            },
        }],
    }

    selected = (
        TATGEngineAdapter
        ._mutation_semantic_source_constrained_sandbox_probe_ids(
            feedback,
            source_code=source,
            existing_test=(
                "Parser parser = new Parser(); "
                "assertEquals(Token.VALUE, parser.nextToken()); "
                "assertEquals(Token.VALUE, parser.nextToken());"
            ),
            target_method="nextToken",
            source_visible_entry_candidates=[{
                "method": "nextToken",
                "path": ["nextToken"],
                "preferred_for_mutation_execution": True,
            }],
        )
    )

    assert selected == ["M1"]
    facts = feedback["mutation_objectives"][0]["facts"]
    proof = facts["mutation_semantic_post_transition_replay_proof"]
    assert proof["proven"] is True
    assert proof["state_fields"] == ["current"]
    assert facts[
        "mutation_semantic_source_constrained_probe_kind"
    ] == "state_transition_observation_replay"
    rendered = TATGEngineAdapter._render_mutation_objective_context_section(
        feedback["mutation_objectives"]
    )
    assert "source_proven_persistent_state: current" in rendered
    assert "nextToken -> nextToken" in rendered
    assert "post_transition_oracle_rule" in rendered


