def test_exact_pit_state_update_maps_field_reader_and_one_hop_observer():
    source = "\n".join([
        "final class Parser {",
        "  private int lineNumber;",
        "  private int target(String input) {",
        "    if (!input.isEmpty()) {",
        "      lineNumber++;",
        "    }",
        "    return input.length();",
        "  }",
        "  String location() {",
        "    return \"line \" + (lineNumber + 1);",
        "  }",
        "  @Override public String toString() {",
        "    return \"Parser \" + location();",
        "  }",
        "}",
    ])
    objective = {
        "id": "M1",
        "facts": {
            "status": "SURVIVED",
            "line": 5,
            "source_line": "lineNumber++;",
            "pit_covering_tests": [
                "testInput(com.example.ParserTest)"
            ],
            "pit_covering_tests_source": (
                "candidate_jacoco_exact_descriptor_mutant_line"
            ),
            "pit_covering_tests_proof_status": "replay_proven",
            "source_backed_mutation_constraints": [{
                "kind": "operator_replacement_difference",
                "mutant_distinguishing_rows": [{
                    "state_expression": "lineNumber",
                    "constraint": "original delta=1, mutant delta=-1",
                }],
            }],
        },
    }

    effects = TATGEngineAdapter._mutation_source_visible_observable_effects(
        source_code=source,
        class_name="Parser",
        objective=objective,
    )

    assert len(effects) == 1
    effect = effects[0]
    assert effect["kind"] == "exact_pit_mutated_receiver_state_observer"
    assert effect["receiver_field"] == "lineNumber"
    observers = effect["source_visible_observers"]
    assert [(row["method"], row["dependency"]) for row in observers] == [
        ("location", "direct_field_read"),
        ("toString", "calls_field_reader:location"),
    ]
    objective["facts"]["mutation_source_visible_observable_effects"] = effects
    rendered = TATGEngineAdapter._render_mutation_objective_context_section(
        [objective]
    )
    assert "String location()" in rendered
    assert "public String toString()" in rendered
    assert "Preserve the exact PIT-covering green Arrange/ACT/input" in rendered


