def test_mutation_semantic_proves_negated_null_guard_exception_replay():
    source = """class Parser {
  Object target(Object nextRecord) {
    if (nextRecord != null) {
      return nextRecord.toString();
    }
    return null;
  }
}
"""
    proof = (
        TATGEngineAdapter
        ._mutation_semantic_null_guard_exception_replay_proof(
            facts={
                "line": 3,
                "mutator": (
                    "org.pitest.mutationtest.engine.gregor.mutators."
                    "NegateConditionalsMutator"
                ),
            },
            verdict={
                "controlling_public_input": "reader at EOF",
                "input_state_delta": "nextRecord == null",
                "setup_recipe": [
                    "Object value = parser.target(null);",
                ],
                "oracle_recipe": (
                    "assertEquals("
                    '"__TATG_MUTATION_ORACLE_CALIBRATION__", '
                    "value);"
                ),
            },
            source_code=source,
        )
    )

    assert proof["proven"] is True
    assert proof["guarded_symbol"] == "nextRecord"
    assert proof["reason"] == (
        "negated_non_null_guard_enters_null_dereference"
    )


