def test_mutation_candidate_cannot_bypass_source_proven_state_protocol():
    generated = """
@Test
public void testM1() {
    Context context = new Context();
    context.modulus = 3;
    codec.encode(new byte[0], 0, -1, context);
    assertEquals(8, context.pos);
}
"""
    metadata = {
        "test_objective_map": {"testM1": "M1"},
        "test_candidate_role_map": {
            "testM1": "role:mutation_reachability"
        },
    }

    violation = TATGEngineAdapter._mutation_direct_state_assignment_violation(
        generated,
        metadata,
        {"M1": {"context.modulus"}},
    )

    assert "directly assigned source-derived state `context.modulus`" in violation
    source_visible = generated.replace(
        "context.modulus = 3;",
        "codec.encode(new byte[] {1, 2, 3}, 0, 3, context);",
    )
    assert not TATGEngineAdapter._mutation_direct_state_assignment_violation(
        source_visible,
        metadata,
        {"M1": {"context.modulus"}},
    )


