def test_mutation_semantic_recipe_requires_receiver_transition_before_act():
    facts = {
        "mutation_reachability_source_evidence": {
            "receiver_state_protocol": {
                "target_class": "Cursor",
                "target_method": "next",
                "required_transitions": [{
                    "state_field": "current",
                    "required_condition": "current != null",
                    "initial_value": "null",
                    "establishing_transitions": [{
                        "method": "next",
                        "method_access": "public",
                        "effect": "current = token;",
                        "target_owned_transition": True,
                    }],
                }],
            }
        }
    }
    one_call = {
        "setup_recipe": [
            "Delegate delegate = Mockito.mock(Delegate.class);",
            "Mockito.when(delegate.next()).thenReturn(Token.VALUE);",
            "Cursor cursor = new Cursor(delegate);",
            "Token result = cursor.next();",
        ]
    }
    two_calls = {
        "setup_recipe": [
            "Delegate delegate = Mockito.mock(Delegate.class);",
            "Mockito.when(delegate.next()).thenReturn(Token.VALUE);",
            "Cursor cursor = new Cursor(delegate);",
            "cursor.next();",
            "Token result = cursor.next();",
        ]
    }

    rejected = (
        TATGEngineAdapter
        ._mutation_semantic_receiver_state_protocol_consistency(
            one_call,
            facts,
        )
    )
    accepted = (
        TATGEngineAdapter
        ._mutation_semantic_receiver_state_protocol_consistency(
            two_calls,
            facts,
        )
    )

    assert rejected["consistent"] is False
    assert rejected["reasons"] == [
        "receiver_state_transition_not_established_before_target"
    ]
    assert rejected["missing_transitions"] == [{
        "state_field": "current",
        "establishing_methods": ["next"],
    }]
    assert accepted["consistent"] is True


