def test_mutation_semantic_state_transition_enters_candidate_replay():
    source = "\n".join([
        "final class Decoder {",
        "  void decode(byte[] input, State state) {",
        "    for (byte value : input) {",
        "      state.modulus = (state.modulus + 1) % 2;",
        "      if (state.modulus == 0) {",
        "        state.buffer[state.index++] = value;",
        "      }",
        "    }",
        "  }",
        "}",
    ])
    feedback = {
        "mutation_objectives": [{
            "id": "M1",
            "facts": {
                "status": "NO_COVERAGE",
                "line": 6,
                "mutator": "arithmetic-op",
                "source_line": "state.buffer[state.index++] = value;",
                "source_backed_mutation_constraints": [{
                    "kind": "operator_replacement_difference",
                    "mutant_distinguishing_rows": [{
                        "constraint_origin": "implicit_unary_update",
                        "source_constant_proven": True,
                        "state_transition_proven": True,
                        "state_expression": "state.index",
                        "original_state_delta": 1,
                        "mutant_state_delta": -1,
                    }],
                }],
            },
        }],
    }
    payload = {
        "verdicts": [{
            "objective_id": "M1",
            "status": "verified",
            "runtime_state_kind": "derived_local",
            "recommended_test_mode": "exact_replay",
            "controlling_public_input": "two input bytes",
            "control_source_evidence": [
                "state.modulus = (state.modulus + 1) % 2;",
                "if (state.modulus == 0) {",
            ],
            "setup_recipe": [
                "decoder.decode(new byte[] { 1, 2 }, state);",
                "int observedIndex = state.index;",
            ],
            "setup_evidence": [
                "decoder.decode(new byte[] { 1, 2 }, state);"
            ],
            "input_state_delta": (
                "two bytes make state.modulus == 0"
            ),
            "oracle_recipe": "assertEquals(1, observedIndex)",
            "oracle_provenance": "source_contract",
            "oracle_source_evidence": [
                "state.buffer[state.index++] = value;"
            ],
            "generic_different_inputs_only": False,
            "original_observable": "state.index == 1",
            "mutant_observable": "state.index == -1",
            "observable_difference": "state.index differs by two",
            "proof_uncertainty": "none",
            "reasoning": "Two bytes reach the exact state update.",
            "contradictions": [],
        }],
        "uncertainties": [],
    }

    audit = TATGEngineAdapter._apply_mutation_semantic_verdicts(
        feedback,
        payload,
        source_code=source,
        existing_test=(
            "decoder.decode(new byte[] { 1, 2 }, state); "
            "assertEquals(1, state.index);"
        ),
    )

    assert audit["replay_required_objective_ids"] == ["M1"]
    facts = feedback["mutation_objectives"][0]["facts"]
    assert facts["mutation_semantic_distinguishes_boundary_mutant"] is True
    assert "input_delta_does_not_match_source_constraint" not in facts[
        "mutation_semantic_rejection_reasons"
    ]


