def test_mutation_line_retry_uses_effective_reachability_status_and_receipt():
    objective = {
        "id": "M1",
        "kind": "MutationReachability",
        "mutation_objective_retry_only": True,
        "facts": {
            "status": "SURVIVED",
            "line": 42,
            "mutator": "MathMutator",
            "source_line": "return left + right;",
            "mutation_line_reachability_retry": True,
            "mutation_line_reachability_original_status": "SURVIVED",
            "prior_mutant_line_miss_receipts": [
                {
                    "test_method": "testShallow",
                    "mutant_line": 42,
                    "covered_target_lines": [35, 36, 37],
                    "candidate_code_excerpt": (
                        "@Test public void testShallow() { "
                        "assertEquals(8, target.call(input)); }"
                    ),
                    "rejected_setup_fingerprint": "abc123def456",
                    "rejected_setup_reason": "exact_mutant_line_not_reached",
                    "forbid_exact_candidate_repetition": True,
                }
            ],
        },
    }

    evidence = TATGEngineAdapter._mutation_objective_evidence_map(
        {"mutation_objectives": [objective]}
    )
    section = TATGEngineAdapter._render_mutation_objective_context_section(
        [objective]
    )
    verifier_prompt = TATGEngineAdapter._mutation_semantic_prompt(
        class_name="Target",
        method_name="call",
        target_descriptor="(I)I",
        source_code="\n".join(
            ["public int call(int input) {"] * 41
            + ["return input + 1;"]
            + ["}"]
        ),
        existing_test=(
            "@Test public void testShallow() { "
            "assertEquals(8, new Target().call(7)); }"
        ),
        mutation_objectives=[objective],
    )

    assert evidence["M1"]["status"] == "NO_COVERAGE"
    assert evidence["M1"]["original_status"] == "SURVIVED"
    assert "candidate_role=mutation_reachability" in section
    assert "exact_line_retry=true" in section
    assert "covered_target_lines=35,36,37" in section
    assert "forbidden_exact_setup_fingerprint=abc123def456" in section
    assert "retry_exclusion: do not return the same setup" in section
    assert "do not spend this retry only changing the assertion" in section
    assert '"status":"NO_COVERAGE"' in verifier_prompt
    assert '"original_pit_status":"SURVIVED"' in verifier_prompt
    assert '"mutation_line_reachability_retry":true' in verifier_prompt


