def test_truncate_section_preserves_complete_high_priority_evidence_blocks(monkeypatch):
    monkeypatch.delenv("TATG_SECTION_TRUNCATE_SHOWN_CHARS", raising=False)
    mutation_text = (
        "[Mutation Objective Context]\n"
        + "- M1 [MutationAssertion] required_candidate: candidate_role=mutation_oracle; status=SURVIVED; line=42\n"
        + ("  source: `return value;`\n  required_oracle: assert exact observable output\n" * 150)
    )
    salvage_text = (
        "[Coverage-Positive Failed Candidates To Salvage]\n"
        + "- test=testTarget; failure=target_positive_setup_blocker; candidate_target_coverage=line_covered=8\n"
        + ("  failed_test: target.call();\n  failure_message: source-visible setup failed\n" * 150)
    )

    compacted_mutation = TATGEngineAdapter._truncate_section_text(mutation_text, 5000)
    compacted_salvage = TATGEngineAdapter._truncate_section_text(salvage_text, 5000)

    assert "[section truncated:" not in compacted_mutation
    assert "[section truncated:" not in compacted_salvage
    assert "candidate_role=mutation_oracle" in compacted_mutation
    assert "source-visible setup failed" in compacted_salvage


