def test_mutation_patch_recovers_unique_source_bound_objective_id():
    raw = json.dumps({
        "new_tests": [{
            "test_name": "testBoundary",
            "candidate_role": "mutation_oracle",
            "test_code_lines": [
                "@Test",
                "public void testBoundary() {",
                "    // M2 boundary mutant",
                "    assertEquals(\"exact\", target());",
                "}",
            ],
        }],
    })

    _, metadata = TATGEngineAdapter._extract_patch_from_json_output(
        raw,
        target_call_names=["target"],
        require_observable_check=True,
        required_mutation_objective_ids={"M1", "M2"},
        return_metadata=True,
    )

    assert metadata["test_objective_map"]["testBoundary"] == "M2"


def test_mutation_patch_rejects_ambiguous_missing_objective_id():
    raw = json.dumps({
        "new_tests": [{
            "test_name": "testBoundary",
            "candidate_role": "mutation_oracle",
            "test_code_lines": [
                "@Test",
                "public void testBoundary() {",
                "    assertEquals(\"exact\", target());",
                "}",
            ],
        }],
    })

    with pytest.raises(TATGEngineAdapter.PatchExtractionError) as exc_info:
        TATGEngineAdapter._extract_patch_from_json_output(
            raw,
            target_call_names=["target"],
            require_observable_check=True,
            required_mutation_objective_ids={"M1", "M2"},
        )

    assert exc_info.value.skip_counts["mutation_objective_id_missing"] == 1


