def test_mutation_source_context_keeps_complete_conditional_opposite_arm():
    source = """class Subject {
    int target(boolean enabled) {
        if (enabled) {
            int a = 1;
            int b = 2;
            int c = 3;
            int d = 4;
            int e = 5;
            int f = 6;
            int g = 7;
            int h = 8;
            return a + b + c + d + e + f + g + h;
        } else {
            int opposite = 91;
            return opposite;
        }
    }
}
"""

