def test_no_coverage_mutation_source_context_includes_bounded_direct_caller():
    source = """class Example {
    void caller(Token token) {
        if (token.isObject()) {
            consume(token);
            target(token);
        }
    }

    private void target(Token token) {
        Token next = token.next();
        if (!next.isField()) {
            fail(next);
        }
    }
}"""

    rendered = TATGEngineAdapter._render_mutation_source_context(
        source,
        "target",
        {
            "mutation_objectives": [
                {"id": "M1", "facts": {"line": 12, "status": "NO_COVERAGE"}}
            ]
        },
    )

    assert "Direct source call-site context for NO_COVERAGE reachability:" in rendered
    assert ">> L5:             target(token);" in rendered
    assert "if (token.isObject())" in rendered


def test_no_coverage_mutation_source_context_includes_predecessor_exit_corridor():
    source = "\n".join(
        [
            "class NumberParser {",
            "  Number target(String input) {",
            "    Number first = parseFirst(input);",
            "    if (first.isUsable()) {",
            "      return first;",
            "    }",
            "    audit(input);",
            "    normalize(input);",
            "    validate(input);",
            "    Number second = parseSecond(input);",
            "    if (second.isUsable()) {",
            "      return second;",
            "    }",
            "    return fallback(input);",
            "  }",
            "}",
        ]
    )

    rendered = TATGEngineAdapter._render_mutation_source_context(
        source,
        "target",
        {
            "mutation_objectives": [
                {"id": "M1", "facts": {"line": 11, "status": "NO_COVERAGE"}}
            ]
        },
    )

