def test_remove_unavailable_source_builder_chain_segments_preserves_allowed_calls():
    source = """
class Agent {
    public static Builder builder() { return new Builder(); }
    public static class Builder {
        public Builder name(String name) { return this; }
        public Builder memory(Memory memory) { return this; }
        public Builder model(Model model) { return this; }
        public Builder toolkit(Toolkit toolkit) { return this; }
        public Agent build() { return new Agent(); }
    }
}
""".strip()
    code = """
Agent agent = Agent.builder()
        .agentId("missing")
        .name("ok")
        .memory(memory)
        .model(model)
        .toolkit(toolkit)
        .build();
agent.doCall(messages);
""".strip()

    cleaned, removed = TATGEngineAdapter._remove_unavailable_source_builder_chain_segments(
        code,
        source_code=source,
        class_name="Agent",
    )

    assert ".agentId(" not in cleaned
    assert ".name(\"ok\")" in cleaned
    assert ".memory(memory)" in cleaned
    assert ".model(model)" in cleaned
    assert ".toolkit(toolkit)" in cleaned
    assert ".build()" in cleaned
    assert "agent.doCall(messages)" in cleaned
    assert removed == ["Agent.Builder.agentId"]


