def test_source_call_state_plan_distinguishes_argument_field_and_derived_null_guards():
    adapter = TATGEngineAdapter()
    section = adapter._render_source_call_state_plan(
        source_code="""
class Helper {
    private Dependency dependency;
    void install(Dependency value) { dependency = value; }
    Result target(String input) {
        if (input == null) { return null; }
        if (dependency == null) { throw new IllegalStateException(); }
        Result result = dependency.resolve(input);
        if (result == null) { return Result.empty(); }
        return result;
    }
}
""".strip(),
        method_name="target",
        type_shapes={
            "Dependency": SimpleNamespace(
                methods=[SimpleNamespace(name="resolve", return_type="Result", params=[("String", "input")])]
            )
        },
    )

    assert "guard `input == null` is a branch axis for target argument `input`" in section
    assert "`input`=null enters the terminal arm" in section
    assert "choose the outcome required by the active missed branch" in section
    assert "guard `dependency == null` is a branch axis for receiver field `dependency`" in section
    assert "source-proven writer effect(s)" in section
    assert "`void install(Dependency value) {` with `dependency = value`" in section
    assert "guard `result == null` is a branch axis for derived value `result`" in section
    assert "valid_baseline_state_requirements" not in section
    assert "fabricated receiver setter" in section


def test_source_call_state_plan_requires_receiver_returns_used_by_helpers():
    adapter = TATGEngineAdapter()
    section = adapter._render_source_call_state_plan(
        source_code="""
class Helper {
    static Spec build(Request request, Config config, String queue) {
        Spec spec = new Spec();
        double ratio = ratioForQueue(config, queue);
        long memory = parseMemory(spec.getMemory());
        return spec;
    }
    private static double ratioForQueue(Config config, String queue) {
        return config.getQueues().stream().filter(q -> q.name().equals(queue)).findFirst().isPresent() ? 2.0 : 1.0;
    }
    private static long parseMemory(String memoryText) {
        return Long.parseLong(memoryText.substring(0, memoryText.length() - 1));
    }
}
""".strip(),
        method_name="build",
        type_shapes={
            "Config": SimpleNamespace(methods=[SimpleNamespace(name="getQueues", return_type="List<Queue>", params=[])]),
            "Spec": SimpleNamespace(methods=[SimpleNamespace(name="getMemory", return_type="String", params=[])]),
        },
    )

    assert "source_required_receiver_return_baselines" in section
    assert "`config.getQueues()`" in section
    assert "source immediately calls `.stream(...)`" in section
    assert "`spec.getMemory()`" in section
    assert "helper `parseMemory(...)`" in section
    assert "observed local-result dependency `spec.getMemory()`" in section
    assert "do not call this chain on unrelated collaborators" in section


