def test_state_entry_writer_selection_is_field_fair_and_effect_diverse():
    adapter = TATGEngineAdapter()
    rows = adapter._state_entry_methods_for_guard_fields(
        """
class Cursor {
    private Token token;
    private boolean enabled;
    public void clearToken() { token = null; }
    public void resetToken() { token = null; }
    public void loadToken() { token = new Token(); }
    public void enable() { enabled = true; }
    public void disable() { enabled = false; }
    public Object target() {
        if (token != null && enabled) { return token; }
        return null;
    }
}
""".strip(),
        guard_texts=["token != null", "enabled"],
        target_method="target",
        class_name="Cursor",
        limit=4,
    )

    assert [row["field"] for row in rows[:2]] == ["token", "enabled"]
    token_rows = [row for row in rows if row["field"] == "token"]
    enabled_rows = [row for row in rows if row["field"] == "enabled"]
    assert [row["effect_variant"] for row in token_rows] == ["non_null", "null"]
    assert [row["effect_variant"] for row in enabled_rows] == ["true", "false"]
    assert token_rows[0]["method"] == "loadToken"
    assert enabled_rows[0]["method"] == "enable"


