def test_state_writer_projection_analysis_is_not_injected_into_prompt():
    adapter = TATGEngineAdapter()
    source = """
class SlotMap<K, V> {
    private int size;
    private K key1;
    private K key2;
    private V value1;
    private V value2;

    public void put(K key, V value) {
        switch (size) {
            case 0:
                key1 = key;
                value1 = value;
                size = 1;
                break;
            case 1:
                key2 = key;
                value2 = value;
                size = 2;
                break;
            default:
                break;
        }
    }

    public V remove(K key) {
        if (key == null && key2 == null) {
            return value2;
        }
        return null;
    }
}
""".strip()
    rows = adapter._state_writer_argument_projection_rows(
        source,
        guard_texts=["key == null && key2 == null"],
        target_method="remove",
        class_name="SlotMap",
    )
    section = adapter._render_source_call_state_plan(
        source_code=source,
        method_name="remove",
        class_name="SlotMap",
        type_shapes={},
    )

    assert rows
    assert any("required_writer_argument=pass `key` as null" in row for row in rows)
    assert "source_visible_state_writer_argument_projections:" not in section
    assert "required_writer_argument=" not in section


