def test_source_call_state_plan_does_not_expand_sibling_entry_arms():
    adapter = TATGEngineAdapter()
    section = adapter._render_source_call_state_plan(
        source_code="""
class Router {
    void dispatch(Base value) {
        switch (value.kind()) {
        case SPECIAL:
            hidden((Special) value);
            break;
        case OTHER:
            sibling((Other) value);
            break;
        default:
            break;
        }
    }
    private void hidden(Special value) {
        value.required().size();
    }
    private void sibling(Other value) {
        value.unrelated().stream();
    }
}
""".strip(),
        method_name="hidden",
        class_name="Router",
        type_shapes={},
        entry_points=[
            {
                "method": "dispatch",
                "path": ["dispatch", "hidden"],
            },
        ],
    )

    assert "value.required()" in section
    assert "value.unrelated()" not in section
    assert "sibling" not in section


