def test_find_public_entry_points_keeps_overloaded_transitive_caller_and_ignores_comment_noise():
    source = """
    class Example {
        class View {
            public void remove() {
                // if (looksLikeMethod) { should not become a call graph node
                clearView();
            }
        }
        public Object remove(Object key) {
            return removeEntry(key);
        }
        Object removeEntry(Object entry) {
            hidden(entry);
            return entry;
        }
        private void hidden(Object entry) {
            if (entry == null) {
                throw new IllegalArgumentException();
            }
        }
    }
    """
    entries = TATGEngineAdapter()._find_public_entry_points("hidden", source)

    assert any(entry["path"] == ["remove", "removeEntry", "hidden"] for entry in entries)
    assert not any("if" in entry["path"] for entry in entries)


def test_find_public_entry_points_resolves_same_arity_overloads_from_argument_types():
    source = """
    class Formatter {
        public void print(Object value, Appendable out, boolean first) {
            if (value instanceof Reader) {
                print((Reader) value, out, first);
                return;
            }
            print(value, value.toString(), out, first);
        }
        public void printRecord(Appendable out, Object... values) {
            print(values[0], out, true);
        }
        private void print(
                Object value,
                CharSequence text,
                Appendable out,
                boolean first) {
            printWithQuotes(value, text, out, first);
        }
        private void print(Reader reader, Appendable out, boolean first) {
            printWithQuotes(reader, out);
        }
        private void printWithQuotes(
                Object value,
                CharSequence text,
                Appendable out,
                boolean first) {}
        private void printWithQuotes(Reader reader, Appendable out) {}
    }
    """

    entries = TATGEngineAdapter()._find_public_entry_points(
        "printWithQuotes",
        source,
        target_descriptor="(Ljava/io/Reader;Ljava/lang/Appendable;)V",
    )

    assert entries
    assert entries[0]["method"] == "print"
    assert entries[0]["path"] == ["print", "print", "printWithQuotes"]
    assert "Object value, Appendable out, boolean first" in entries[0]["signature"]
    assert any(
        entry["method"] == "printRecord"
        and entry["path"] == ["printRecord", "print", "print", "printWithQuotes"]
        for entry in entries
    )
    assert not any(
        entry["method"] == "printRecord"
        and entry["path"] == ["printRecord", "print", "printWithQuotes"]
        for entry in entries
    )


