def test_generation_prompt_section_order_frontloads_actionable_context():
    sections = [
        "Source code under test:\nclass Noise {}",
        "[CALLABLE SURFACE — ground truth, only these symbols exist]\nClass C:",
        "Dependency context for the class under test:\ndependency constructor",
        "[Generation Control Receipt]\n- target=C.m",
        "[Required Executable Path Objective]\n- build valid baseline",
        "Strict type contracts (must follow exactly):\n- Type: exact",
        "[Static Entry Path Plan]\npublic entry -> private target",
        "[Prompt Module Guide]\n- obey receipt",
        "[Type-Guided Execution Recipes]\n- build receiver",
        "[Source-Derived Visible State Sequence]\n- call open(); call target();",
        "[Source-Derived Target State/Call Plan]\n- state fact",
        "[Current Round Test Objectives]\nO1 [TokenPathMatrix] source=coverage_obligation; goal=cover deep frontier",
        "[Delegated Callback Outcome Matrix]\n- callback outcome rows",
        "Requirements:\n1) compile",
    ]

    ordered = TATGEngineAdapter._order_generation_prompt_sections(sections)
    joined = "\n\n---\n\n".join(ordered)

    assert joined.index("[Generation Control Receipt]") < joined.index("[Prompt Module Guide]")
    assert joined.index("[Prompt Module Guide]") < joined.index("[Static Entry Path Plan]")
    assert joined.index("[Prompt Module Guide]") < joined.index("[Required Executable Path Objective]")
    assert joined.index("[Required Executable Path Objective]") < joined.index("[Static Entry Path Plan]")
    assert joined.index("[Source-Derived Target State/Call Plan]") < joined.index("[Static Entry Path Plan]")
    assert joined.index("[Static Entry Path Plan]") < joined.index("[Current Round Test Objectives]")
    assert joined.index("[Source-Derived Target State/Call Plan]") < joined.index("[Current Round Test Objectives]")
    assert joined.index("[Source-Derived Visible State Sequence]") < joined.index("[Current Round Test Objectives]")
    assert joined.index("[Delegated Callback Outcome Matrix]") < joined.index("[Current Round Test Objectives]")
    assert joined.index("[Delegated Callback Outcome Matrix]") < joined.index("Strict type contracts")
    assert joined.index("Strict type contracts") < joined.index("Dependency context for the class under test:")
    assert joined.index("Dependency context for the class under test:") < joined.index("[Type-Guided Execution Recipes]")
    assert joined.index("[Type-Guided Execution Recipes]") < joined.index("[CALLABLE SURFACE")
    assert joined.index("[CALLABLE SURFACE") < joined.index("Source code under test:")
    assert joined.index("Source code under test:") < joined.index("Requirements:")


