def test_coverage_quality_hints_warn_when_deep_mocks_cannot_update_receiver_context():
    hints = TATGEngineAdapter()._render_coverage_quality_hints(
        source_code="""
class DelegatingCursor {
    private Object _currToken;
    private Context _headContext;
    private Context _exposedContext;
    private Underlying delegate;
    public Object nextValue() {
        if (_currToken != null && _exposedContext == null) {
            if (!_headContext.isStartHandled()) { return null; }
        }
        Object t = delegate.next();
        if (t != null) {
            _headContext = _headContext.createChild(t);
            return t;
        }
        Context ctxt = _exposedContext;
        if (ctxt != null) {
            return ctxt.nextTokenToRead();
        }
        return null;
    }
}
""".strip(),
        class_name="DelegatingCursor",
        method_name="nextValue",
    )

    assert "[Delegated State Realism]" in hints
    assert "receiver update its own context naturally" in hints
    assert "Mockito/deep mocks only for focused failure injection" in hints


def test_coverage_quality_hints_include_delegated_callback_outcome_matrix():
    hints = TATGEngineAdapter()._render_coverage_quality_hints(
        source_code="""
class DelegatingCursor {
    private Strategy strategy;
    private Delegate delegate;
    public Object nextValue() {
        Object f = strategy.checkValue(delegate);
        if (f == Strategy.INCLUDE_ALL) {
            return delegate.current();
        }
        if (f == null) {
            delegate.skipChildren();
            return null;
        }
        f = strategy.includeProperty(delegate.getName());
        if (f != null) {
            return delegate.current();
        }
        return null;
    }
}
""".strip(),
        class_name="DelegatingCursor",
        method_name="nextValue",
    )

    assert "[Delegated Callback Outcome Matrix]" in hints
    assert "callback=`strategy.checkValue(...)`" in hints
    assert "f == Strategy.INCLUDE_ALL" in hints
    assert "f == null" in hints
    assert "callback=`strategy.includeProperty(...)`" in hints
    assert "Partitions come from the exact source comparisons" in hints


def test_delegated_callback_matrix_renders_selector_config_and_continuation_axes(monkeypatch):
    monkeypatch.setenv("TATG_RENDER_DETAILED_CALLBACK_PROTOCOL", "1")
    section = TATGEngineAdapter._render_delegated_callback_outcome_matrix(
        source_code="""
class Cursor {
    private Filter filter;
    private Delegate delegate;
    boolean _includePath;
    Object nextValue(int id) {
        Object f;
        switch (id) {
        case ID_START_ARRAY:
            f = filter.filterStartArray();
            if (f == null) {
                delegate.skipChildren();
                break;
            }
            if (_includePath) {
                return nextBuffered();
            }
            break;
        case ID_FIELD_NAME:
            f = filter.includeProperty(delegate.getName());
            if (f != INCLUDE_ALL) {
                f = f.includeValue(delegate);
            }
        }
        return null;
    }
}
""".strip(),
        method_name="nextValue",
    )

    assert "selector=case ID_START_ARRAY" in section
    assert "callback=`filter.filterStartArray(...)`" in section
    assert "branches=f == null" in section
    assert "config=_includePath" in section
    assert "continuation=collaborator-effect-then-control-transfer" in section
    assert "callback=`filter.includeProperty(...)`" in section


