def test_generation_feedback_orders_active_objectives_before_satisfied_summary():
    section = TATGEngineAdapter._render_generation_coverage_feedback_section(
        {
            "method_name": "target",
            "generation_iteration": 2,
            "line_coverage": 0.4,
            "line_covered": 4,
            "line_total": 10,
            "line_missed": 6,
            "branch_coverage": 0.25,
            "branch_covered": 1,
            "branch_total": 4,
            "branch_missed": 3,
            "coverage_obligations": [
                {
                    "id": "O1",
                    "category": "GuardOutcome",
                    "scenario": "cover missing null guard",
                    "program_fact": "if (value == null)",
                    "required_setup": ["arrange value == null through public input"],
                    "target_call": "call target(value)",
                    "oracle": ["assert null-specific return"],
                    "missed_source_lines": [
                        {
                            "line": 12,
                            "code": "return fallback;",
                            "branch_gap": "uncovered line",
                        }
                    ],
                    "satisfied": False,
                    "reason": "anchor_gaps_still_open",
                    "anchor_count": 1,
                    "closed_anchor_gap_count": 0,
                    "remaining_anchor_gap_count": 1,
                },
                {
                    "id": "O2",
                    "category": "GuardOutcome",
                    "scenario": "already covered default guard",
                    "program_fact": "if (value != null)",
                    "satisfied": True,
                    "reason": "all_anchor_gaps_closed",
                    "anchor_count": 1,
                    "closed_anchor_gap_count": 1,
                    "remaining_anchor_gap_count": 0,
                    "anti_duplication_key": "GuardOutcome:value != null",
                },
            ],
        },
        fallback_method_name="target",
    )

    assert "[Active Uncovered Objectives]" in section
    assert "[Satisfied Objectives Summary]" in section
    assert section.index("[Active Uncovered Objectives]") < section.index("[Current Round Test Objectives]")
    assert section.index("[Current Round Test Objectives]") < section.index("[Satisfied Objectives Summary]")
    assert "L12: return fallback;" in section
    assert "O2 [GuardOutcome]" in section
    assert "anti_duplication_key=GuardOutcome:value != null" in section


