def test_generation_feedback_compacts_state_recipe_without_repeating_long_hints(monkeypatch):
    monkeypatch.setenv("TATG_RENDER_COMPACT_STATE_RECIPE", "1")
    section = TATGEngineAdapter._render_generation_coverage_feedback_section(
        {
            "method_name": "nextToken",
            "coverage_obligations": [
                {
                    "id": "O2",
                    "category": "StateSequence",
                    "scenario": "cover continuation after skipped callback outcome",
                    "program_fact": "loop continues after callback exclusion",
                    "target_call": "call nextToken repeatedly",
                    "missed_source_lines": [
                        {
                            "line": 503,
                            "code": "t = _nextTokenWithBuffering(_headContext);",
                            "public_state_search_hints": [
                                "`_headContext`: verbose constructor/factory/state transition hint that should not be repeated when a compact state recipe exists",
                            ],
                            "state_dependency_plan": {
                                "target_state": [
                                    "_headContext: prepared nested context",
                                    "_itemFilter: custom callback filter",
                                ],
                                "state_entry_sequence_candidates": [
                                    "ordered callback sequence: use multiple input items/siblings so an earlier callback outcome excludes/skips and a later callback outcome includes/customizes; invoke the public target call sequence long enough to cross the internal loop/continuation",
                                ],
                                "callback_outcome_partition": [
                                    "includeProperty: null / include-all-equivalent / non-null custom",
                                    "ordered outcomes: first null-or-false, later include-all-or-custom",
                                ],
                            },
                        }
                    ],
                }
            ],
        },
        fallback_method_name="nextToken",
    )

    assert "state_recipe: ordered-callback: exclude/skip earlier input, include/custom later sibling" in section
    assert "state-facts: _headContext, _itemFilter" in section
    assert "oracle: exact returned token/value/state" in section
    assert "verbose constructor/factory/state transition hint" not in section


