def test_generation_coverage_feedback_section_renders_generalized_search_guidance():
    section_no_repair = TATGEngineAdapter._render_generation_coverage_feedback_section(
        {
            "method_name": "target",
            "generation_iteration": 2,
            "line_coverage": 0.2,
            "line_covered": 2,
            "line_total": 10,
            "line_missed": 8,
            "branch_coverage": 0.1,
            "branch_covered": 1,
            "branch_total": 10,
            "branch_missed": 9,
            "missed_source_lines": [
                {"line": 42, "code": "if (cursor.nextToken() == null) { return null; }"}
            ],
            "coverage_obligations": [
                {"id": "O1", "category": "StatefulCursor", "scenario": "cover cursor transition"}
            ],
        }
    )
    # Repair mode should NOT appear without measured_directional_feedback (iter2).
    assert "[Generalized Input-Family Search]" in section_no_repair
    assert "search operators, not fixed enumerations" in section_no_repair
    assert "state axis" in section_no_repair
    assert "cursor axis" not in section_no_repair
    assert "[Metamorphic Oracle Templates]" in section_no_repair
    assert "round-trip oracle" in section_no_repair
    assert "[Coverage-Repair Mode]" not in section_no_repair

    section_with_repair = TATGEngineAdapter._render_generation_coverage_feedback_section(
        {
            "method_name": "target",
            "generation_iteration": 3,
            "line_coverage": 0.2,
            "line_covered": 2,
            "line_total": 10,
            "line_missed": 8,
            "branch_coverage": 0.1,
            "branch_covered": 1,
            "branch_total": 10,
            "branch_missed": 9,
            "missed_source_lines": [
                {"line": 42, "code": "if (cursor.nextToken() == null) { return null; }"}
            ],
            "coverage_obligations": [
                {"id": "O1", "category": "StatefulCursor", "scenario": "cover cursor transition"}
            ],
            "measured_directional_feedback": {"next_required_obligation_ids": ["O1"]},
        }
    )
    # Repair mode SHOULD appear when measured_directional_feedback exists (iter3+).
    assert "[Coverage-Repair Mode]" in section_with_repair
    assert "mutate exactly one arrange axis" in section_with_repair


