def test_static_entry_path_plan_is_compacted_for_large_context(monkeypatch):
    monkeypatch.delenv("TATG_STATIC_ENTRY_PATH_MAX_CHARS", raising=False)
    long_ctx = "\n".join(
        [
            "# Target",
            "target: com.acme.Target.method()",
            *(
                f"Path {i}: public entry -> helper -> target\n  step {i}a\n  step {i}b\n  step {i}c"
                for i in range(1, 40)
            ),
            "x" * 20000,
        ]
    )

    compacted = TATGEngineAdapter._compact_static_entry_path_plan(
        long_ctx,
        method_is_private=False,
    )

    assert "target: com.acme.Target.method()" in compacted
    assert "Path 1:" in compacted
    assert "Path 5:" not in compacted
    assert "[Static Entry Path Plan truncated:" in compacted
    assert len(compacted) < len(long_ctx)


