def test_prompt_log_marks_current_objectives_and_section_truncation():
    request = SimpleNamespace(
        log_prompts=True,
        log_prompts_limit=20,
        prompt_logs=[],
        live_run_id="run123",
        prompt_iteration=2,
    )

    TATGEngineAdapter._record_prompt_log(
        request,
        phase="generate",
        label="Target::method",
        system_prompt="system",
        user_prompt="[Current Round Test Objectives]\n- I1\n\n[section truncated: original_chars=5000, shown_chars=1000]",
        attempt=1,
    )

    entry = request.prompt_logs[0]
    assert entry["unified_objective_present"] is True
    assert entry["section_truncated"] is True
    assert entry["section_truncation_markers"] == 1
    assert entry["top_level_truncated"] is False
    assert entry["live_run_id"] == "run123"
