def test_generation_control_receipt_frontloads_schema_and_source_construction_choices():
    receipt = TATGEngineAdapter._render_generation_control_receipt(
        target_desc="Writer.writeString",
        method_name="writeString",
        patch_mode=True,
        suggested_tests=3,
        required_obligation_ids={"O2", "O1"},
        target_overload_ids={"writeString#String"},
        symbol_grounding=(
            "[Classpath Symbol Grounding]\n"
            "[Visible Type Construction APIs]\n"
            "- SerializableString:\n"
            "  - SerializedString(String value)\n"
            "  - related CharSequence implementation StringBuilder: StringBuilder()\n"
            "Name-related concrete/value candidates from source/classpath symbols:\n"
            "- SerializedString => com.acme.SerializedString\n"
            "- OtherValue => com.acme.OtherValue\n"
            "Known visible symbols:\n"
        ),
        target_receipt="[Target Execution Receipt]\n- Construct receiver before calling target.\n",
        execution_capsules_section="[Execution Capsule Skeleton]\n- target_state=ready\n",
        target_param_type_names=["SerializableString"],
    )

    assert receipt.startswith("[Generation Control Receipt]")
    assert "line/branch coverage toward 100%" in receipt
    assert "mutation score" not in receipt
    assert "output_format=JSON only" in receipt
    assert '"new_tests"' in receipt
    assert "required_coverage_obligation_ids=O1, O2" in receipt
    assert "allowed_target_overload_ids=writeString#String" in receipt
    assert "source_visible_construction_choices" in receipt
    assert "related CharSequence implementation StringBuilder" in receipt
    assert "SerializedString => com.acme.SerializedString" not in receipt
    assert receipt.index("output_format=JSON only") < receipt.index("source_visible_construction_choices")


