def test_source_checked_exception_stubbing_misuses_detects_undeclared_checked_exception(tmp_path: Path):
    src = tmp_path / "src/main/java/com/acme/AgentExecutor.java"
    src.parent.mkdir(parents=True)
    src.write_text(
        """
package com.acme;
public interface AgentExecutor {
  void execute(RequestContext context, AgentEmitter emitter) throws A2AError;
}
class RequestContext {}
class AgentEmitter {}
class A2AError extends RuntimeException {}
""",
        encoding="utf-8",
    )
    code = """
import com.acme.AgentExecutor;
import java.util.concurrent.TimeoutException;
AgentExecutor executor = Mockito.mock(AgentExecutor.class);
Mockito.doThrow(new TimeoutException("slow")).when(executor).execute(Mockito.any(), Mockito.any());
"""

    assert TATGEngineAdapter._source_checked_exception_stubbing_misuses_in_code(
        code,
        tmp_path,
        symbol_index={"AgentExecutor": ["com.acme.AgentExecutor"]},
    ) == ["AgentExecutor.execute:TimeoutException:checked-exception-not-declared"]


def test_rewrite_checked_exception_stubs_to_runtime_for_source_declared_mismatch(tmp_path: Path):
    src = tmp_path / "src/main/java/com/acme/AgentExecutor.java"
    src.parent.mkdir(parents=True)
    src.write_text(
        """
package com.acme;
public interface AgentExecutor {
  void execute(RequestContext context, AgentEmitter emitter) throws A2AError;
}
class RequestContext {}
class AgentEmitter {}
class A2AError extends RuntimeException {}
""",
        encoding="utf-8",
    )
    code = """
import com.acme.AgentExecutor;
import java.util.concurrent.InterruptedException;
AgentExecutor executor = Mockito.mock(AgentExecutor.class);
Mockito.doThrow(new InterruptedException("stop")).when(executor).execute(Mockito.any(), Mockito.any());
"""

    rewritten, rewrites = TATGEngineAdapter._rewrite_source_checked_exception_stubs_to_runtime(
        code,
        tmp_path,
        symbol_index={"AgentExecutor": ["com.acme.AgentExecutor"]},
    )

    assert rewrites == ["AgentExecutor.execute:InterruptedException:checked-exception-not-declared"]
    assert "new RuntimeException(\"source-declared unchecked failure\")" in rewritten
    assert "new InterruptedException" not in rewritten


