def test_mutation_feedback_prompt_separates_reachability_and_assertion_targets():
    section = TATGEngineAdapter._render_generation_coverage_feedback_section({
        "method_name": "parse",
        "generation_iteration": 2,
        "line_coverage": 0.80,
        "test_objectives": [
            {
                "id": "M1",
                "kind": "MutationReachability",
                "source": "mutation_feedback",
                "facts": {
                    "status": "NO_COVERAGE",
                    "line": 10,
                    "mutator": "NegateConditionalsMutator",
                    "source_line": "if (c >= 'a' && c <= 'f') {",
                    "description": "reach mutant line",
                },
                "target_call": "invoke parse with a character that reaches line 10",
                "promotion_criteria": ["candidate reaches the mutant line"],
            }
        ],
        "surviving_mutants": [
            {
                "status": "NO_COVERAGE",
                "line": 10,
                "mutator_short": "NegateConditionalsMutator",
                "description": "negated conditional",
                "source_line": "if (c >= 'a' && c <= 'f') {",
                "kill_hint": "Add an input that reaches line 10.",
                "oracle_strategy": ["After reaching line 10, assert exact branch-specific behavior."],
            },
            {
                "status": "SURVIVED",
                "line": 20,
                "difficulty": "easy",
                "mutator_short": "PrimitiveReturnsMutator",
                "description": "replaced int return with 0",
                "source_line": "return value;",
                "kill_hint": "Assert the exact value.",
                "oracle_strategy": ["Use input whose real primitive result differs from zero; assert the exact value."],
            },
        ],
        "mutation_score_gap": {
            "mutation_survived": 4,
            "mutation_no_coverage": 2,
        },
    })

    assert "Reachability targets (1 NO_COVERAGE" in section
    assert "Assertion targets (1 SURVIVED easy" in section
    assert "M1 [MutationReachability] source=mutation_feedback" in section
    assert "facts.mutation: status=NO_COVERAGE; line=10; mutator=NegateConditionalsMutator" in section
    assert "if (c >= 'a' && c <= 'f')" in section
    assert "Mutation oracle rule" in section
    assert 'candidate_role="mutation_reachability"' in section
    assert 'candidate_role="mutation_oracle"' in section
    assert "required_candidate: candidate_role=mutation_reachability" in section
    assert "required_candidate: candidate_role=mutation_oracle" in section
    assert "required_oracle: After reaching line 10" in section


