def test_visible_api_contracts_prioritize_source_import_tokens(tmp_path: Path):
    for name in [f"AType{i}" for i in range(25)]:
        path = tmp_path / "com/acme" / f"{name}.java"
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(
            f"package com.acme;\npublic class {name} {{ public {name}() {{}} }}\n",
            encoding="utf-8",
        )
    text_block = tmp_path / "com/acme/TextBlock.java"
    text_block.write_text(
        """
package com.acme;
public final class TextBlock {
    private TextBlock(String text) {}
    public static Builder builder() { return new Builder(); }
    public static class Builder {
        public Builder text(String text) { return this; }
        public TextBlock build() { return new TextBlock(""); }
    }
}
""".strip(),
        encoding="utf-8",
    )
    grounded = [(f"AType{i}", f"com.acme.AType{i}") for i in range(25)]
    grounded.append(("TextBlock", "com.acme.TextBlock"))

    section = TATGEngineAdapter._render_visible_api_contracts_section(
        project_root=tmp_path,
        grounded_symbols=grounded,
        priority_tokens={"TextBlock"},
    )

    assert "- TextBlock:" in section
    assert "static Builder builder()" in section
    assert "Builder text(String text)" in section
    assert "TextBlock build()" in section
    assert section.find("- TextBlock:") < section.find("- AType0:")


