def test_coverage_feedback_keeps_outer_identity_during_multi_pass_compaction(monkeypatch):
    monkeypatch.delenv("TATG_PROMPT_TARGET_CHARS", raising=False)
    recent = "\n".join(
        (
            f"- test=testFailure{i}; type=compile; message=exact diagnostic {i}\n"
            f"  candidate_excerpt: target.method(value{i});\n"
            f"  source_visible_alternative: target.method(validValue{i});"
        )
        for i in range(40)
    )
    coverage = (
        "[Coverage Feedback For This Generation Round]\n"
        + ("low-value measured detail\n" * 500)
        + "[Recent Validation Failures]\n"
        + recent
        + "\n[Measured Directional Feedback]\n"
        + "Still-open O-ids: O1, O2\n"
        + "[Coverage-Repair Mode]\n"
        + "- preserve the compiling scaffold and change one arrange axis\n"
        + "- keep the exact target call and assert observable behavior\n"
    )
    prompt = "\n\n---\n\n".join(
        [
            "[Generation Control Receipt]\n- target=Target.method\n- output_format=JSON only",
            coverage,
            "[CALLABLE SURFACE]\n" + ("public void method(Value value)\n" * 500),
            "Source code under test:\n" + ("if (value != null) { target.method(value); }\n" * 500),
        ]
    )

    compacted = TATGEngineAdapter._compact_user_prompt_to_budget(prompt)
    coverage_sections = [
        section
        for section in compacted.split("\n\n---\n\n")
        if "[Recent Validation Failures]" in section
    ]

    assert coverage_sections
    assert coverage_sections[0].startswith("[Coverage Feedback For This Generation Round]")
    assert "[section truncated:" not in TATGEngineAdapter._extract_bracket_section(
        coverage_sections[0],
        "[Recent Validation Failures]",
    )
    assert "[section truncated:" not in TATGEngineAdapter._extract_bracket_section(
        coverage_sections[0],
        "[Coverage-Repair Mode]",
    )
    assert TATGEngineAdapter._high_priority_mid_field_clip(compacted) is False


def test_pre_target_precondition_guard_is_legacy_opt_in(monkeypatch):
    code = """
@Test
public void testBad() throws Exception {
    WriterLike gen = new WriterLike();
    gen.writeStartObject();
    gen.writeString("x");
}
""".strip()
    feedback = {
        "measured_directional_feedback": {
            "recent_validation_failures": [
                {
                    "message": "No element/attribute name specified when trying to output element",
                    "pre_target_failure": {
                        "statement": "gen.writeStartObject();",
                        "before_target": True,
                    },
                },
                {
                    "message": "No element/attribute name specified when trying to output element",
                    "pre_target_failure": {
                        "statement": "gen.writeStartObject();",
                        "before_target": True,
                    },
                },
            ]
        }
    }

    assert not TATGEngineAdapter._pre_target_precondition_violations_from_feedback(
        code,
        feedback,
        target_method="writeString",
    )

    monkeypatch.setenv("TATG_ENABLE_LEGACY_NAME_HEURISTICS", "1")
    violations = TATGEngineAdapter._pre_target_precondition_violations_from_feedback(
        code,
        feedback,
        target_method="writeString",
    )

    assert not violations


