def test_related_concrete_symbol_candidates_exposes_source_backed_value_type():
    noisy_symbols = {
        f"Seed{i}Context": [f"com.acme.core.Seed{i}Context"]
        for i in range(25)
    }
    noisy_symbols.update({
        f"Concrete{i}Context": [f"com.acme.core.impl.Concrete{i}Context"]
        for i in range(25)
    })
    noisy_symbols.update(
        {
            "SerializableString": ["com.acme.core.SerializableString"],
            "SerializedString": ["com.acme.core.io.SerializedString"],
            "OtherString": ["org.other.OtherString"],
        }
    )
    candidates = TATGEngineAdapter._related_concrete_symbol_candidates(
        {"SerializableString", *[f"Seed{i}Context" for i in range(25)]},
        noisy_symbols,
        source_imports={"SerializableString": "com.acme.core.SerializableString"},
        source_package="com.acme.core",
    )

    assert "SerializedString" in candidates
    assert "OtherString" not in candidates


