def test_validation_and_oracle_objectives_render_in_feedback_section():
    section = TATGEngineAdapter._render_generation_coverage_feedback_section(
        {
            "method_name": "target",
            "generation_iteration": 2,
            "line_missed": 1,
            "branch_missed": 1,
            "test_objectives": [
                {
                    "id": "V1",
                    "kind": "ValidationRepair",
                    "source": "validation_failure_feedback",
                    "facts": {"scenario": "repair testBadSetup: missing-required-initialization", "category": "missing-required-initialization"},
                    "required_setup": ["Initialize collaborator before target call."],
                    "promotion_criteria": ["candidate compiles, passes validation, and reaches useful target behavior"],
                },
                {
                    "id": "Q1",
                    "kind": "OracleStrengthening",
                    "source": "oracle_quality_feedback",
                    "facts": {"scenario": "upgrade weak existing tests with concrete oracles", "weak_test_names": ["testSmoke"]},
                    "oracle": ["assert exact return value"],
                    "promotion_criteria": ["candidate keeps passing and improves oracle strength"],
                },
            ],
            "validation_failure_feedback": [{
                "category": "state-sequence-or-oracle-mismatch",
                "test_method": "testBadSetup",
                "coverage_obligation_id": "O5",
                "input_family": "cursor:field-name",
                "repair_axis_hint": "state-sequence-before-oracle",
                "expected_value": "VALUE_STRING",
                "actual_value": "null",
                "candidate_target_coverage": {
                    "has_target_coverage": True,
                    "line_covered": 20,
                    "branch_covered": 4,
                },
                "similar_failure_count": 2,
                "similar_failed_tests": ["testBadSetup", "testBadSetupVariant"],
            }],
            "oracle_quality": {"total": 2, "level0": 1, "level1": 1, "level2": 0, "weak_tests": [{"name": "testSmoke"}]},
        }
    )

    assert "V1 [ValidationRepair] source=validation_failure_feedback" in section
    assert "Q1 [OracleStrengthening] source=oracle_quality_feedback" in section
    assert "required_setup: Initialize collaborator before target call." in section
    assert "[Previous Validation Failure Feedback]" in section
    assert "repeated_failure_cluster: count=2; tests=testBadSetup, testBadSetupVariant" in section
    assert "failed_axis: objective=O5; input_family=cursor:field-name; repair_axis=state-sequence-before-oracle" in section
    assert "observed_mismatch: expected=VALUE_STRING actual=null" in section
    assert "failed_candidate_coverage: has_target_coverage=True; line_covered=20; branch_covered=4" in section
    assert "[Oracle Quality Feedback]" in section


