def test_initial_generation_objective_frontloads_source_derived_state_entry():
    source = """
    public class Cursor {
      private int _index;
      private String _currToken;
      public String nextToken() {
        if (_index == 0) { _currToken = "START"; }
        if (_index > 1) { return null; }
        _index++;
        return _currToken;
      }
      public String nextTextValue() {
        return nextToken();
      }
    }
    """

    section = TATGEngineAdapter._render_initial_generation_objectives_section(
        method_name="nextToken",
        class_name="Cursor",
        method_access="public",
        source_code=source,
    )

    assert "source-derived receiver-field dataflow" in section
    assert "target-owned-state-transition" in section
    assert "target-first-state-entry" in section
    assert "repeated-target-invocation" in section
    assert "execute the exact target `nextToken(...)` as the ACT" in section
    assert "nextTextValue(...)` may be used" not in section
    assert "nextTextValue->" not in section


def test_initial_generation_objective_does_not_add_state_entry_without_source_signal():
    source = """
    public class Calculator {
      public int add(int a, int b) {
        return a + b;
      }
      public int subtract(int a, int b) {
        return a - b;
      }
    }
    """

    section = TATGEngineAdapter._render_initial_generation_objectives_section(
        method_name="add",
        class_name="Calculator",
        method_access="public",
        source_code=source,
    )

    assert "source-derived state-entry signal" not in section
    assert "target-owned-state-transition" not in section
    assert "do not substitute them for the target ACT" not in section


def test_initial_generation_objective_does_not_treat_local_index_branches_as_state_entry():
    source = """
    public class NumberLike {
      public Number createNumber(String str) {
        int index = str.indexOf('.');
        if (index < 0) {
          if (str.startsWith("0x")) {
            return Integer.valueOf(str.substring(2), 16);
          }
          return Integer.valueOf(str);
        }
        if (index == 0) {
          return Double.valueOf(str);
        }
        return Float.valueOf(str);
      }
    }
    """

    section = TATGEngineAdapter._render_initial_generation_objectives_section(
        method_name="createNumber",
        class_name="NumberLike",
        method_access="public",
        source_code=source,
    )

    assert "source-derived target-owned state-entry" not in section
    assert "target-owned-state-transition" not in section


