    result = adapter.generate_test_for_target(request, target, tmp_path, "mvn test")

    assert result["status"] == "success"
    assert "testO1PositiveBranch" in result["generated_code"]
    assert result["tatg_partial_required_obligation_acceptance"] is True
    assert result["tatg_missing_required_obligation_ids"] == ["O2"]
    assert result["tatg_bound_required_obligation_ids"] == ["O1"]


