def test_private_helper_entry_precondition_sketch_uses_source_local_caller():
    source = """
package io.acme;
class Scanner {
    Token next(Token token) throws java.io.IOException {
        int c = reader.read();
        if (isQuoted(c)) {
            return parseQuoted(token);
        }
        return token;
    }
    private Token parseQuoted(Token token) throws java.io.IOException {
        int c = reader.read();
        if (isEscape(c)) { token.text.append((char)c); }
        return token;
    }
}
""".strip()

    sketches = TATGEngineAdapter._source_private_helper_entry_precondition_sketches(
        source_code=source,
        target_method="parseQuoted",
        method_access="private",
    )

    assert sketches
    sketch = sketches[0]
    assert sketch["kind"] == "helper_entry_precondition"
    assert "next(...)" in " ".join(sketch["source_evidence"])
    assert "parseQuoted(...)" in " ".join(sketch["source_evidence"])
    arrange = " ".join(sketch["required_arrange"])
    assert "caller-established precondition" in arrange
    assert "opening character already consumed" in arrange
    assert "coverage_obligation_id" not in json.dumps(sketch)


def test_private_helper_entry_precondition_sketch_skips_private_non_protocol_caller():
    source = """
class Encoder {
    public String encode(String value) {
        return handleA(value, 0);
    }
    private String handleA(String value, int index) {
        if (index == 0) {
            return handleB(value, index + 1);
        }
        return value;
    }
    private String handleB(String value, int index) {
        if (value.startsWith("x")) {
            return value.substring(index);
        }
        return value;
    }
}
""".strip()

    sketches = TATGEngineAdapter._source_private_helper_entry_precondition_sketches(
        source_code=source,
        target_method="handleB",
        method_access="private",
    )

    assert sketches == []


