def test_executable_candidate_recipe_prioritizes_executable_relation_rows():
    sketch = SimpleNamespace(
        sketch_id="SK1",
        kind="receiver_state_input_projection",
        candidate_role_hint="state_transition",
        source_evidence=["receiver_state: pendingIds", "caller_projection: providedResults"],
        required_arrange=[
            "construct receiver/setup so `pendingIds` is non-empty",
            "pass `msgs` values whose stream projection produces one chosen row relation",
            "do not cover every relation in one test",
            "receiver-state setup: populate memory.getMessages",
            "receiver-state setup: make assistant role",
            "receiver-state setup: make hasContentBlocks(ToolUseBlock.class)",
            "caller projection details: include `ToolResultBlock` rows in `msgs`",
            "executable relation recipe: matching row = create receiver-side `ToolUseBlock` with one same public id value, create caller-side `ToolResultBlock` with that same value, then call target",
            "executable relation recipe: missing/no-result row = keep receiver-side `ToolUseBlock` pending/non-empty but pass input whose projection has no `ToolResultBlock`, then assert the documented exception or terminal outcome",
        ],
        target_call="call doCall(msgs) and block returned Mono",
        oracle_observation=["assert observable result or exact exception"],
    )

    section = TATGEngineAdapter._render_executable_candidate_recipe_section(
        frontier_sketches=[sketch],
    )

    assert "executable relation recipe: matching row" in section
    assert "receiver-side `ToolUseBlock`" in section
    assert "caller-side `ToolResultBlock`" in section
    assert "receiver-state seed rows and caller-parameter rows separate" in section
    assert "do not pass only the receiver seed collection as the target argument" in section
    assert "caller projection details: include `ToolResultBlock` rows" in section
    assert "missing/no-result row" not in section
    assert "do not use Mockito invocation-count verification as the only oracle" in section


