def test_frontier_recipe_and_retry_do_not_midclip_relation_facts():
    long_relation = (
        "executable relation recipe: matching row = create receiver-side pending state "
        "with one stable public id value, create caller-side projected input row with that "
        "same value, arrange every required source-visible collaborator return, call the "
        "target entry path, consume the lazy result, and assert exact observable output"
    )
    sketch = {
        "sketch_id": "SK1",
        "kind": "receiver_state_input_projection",
        "candidate_role_hint": "state_transition",
        "source_evidence": [
            "receiver_state: pending ids are derived from receiver memory/state collection",
            "caller_projection: provided rows are derived from target input stream projection",
        ],
        "required_arrange": [
            "receiver-state setup: build receiver state with one pending id",
            "caller projection details: build one matching caller row from public builders/factories",
            long_relation,
        ],
        "target_call": "call target(input) and consume returned lazy result",
        "oracle_observation": ["assert exact result or exact documented exception"],
        "confidence": 0.88,
        "upgrade_gate": "sandbox target-positive coverage",
    }

    sketch_section = TATGEngineAdapter._render_frontier_candidate_sketches_section([sketch])
    recipe_section = TATGEngineAdapter._render_executable_candidate_recipe_section(
        frontier_sketches=[sketch],
        construction_repair_map_section=(
            "[Source-Derived Construction Repair Map]\n"
            "- C1 type=Payload; source_proven_replacement=Payload.builder().value(...).build()"
        ),
        collaborator_callable_map_section=(
            "[Source-Derived Collaborator Callable Map]\n"
            "- K1 type=Model; source_visible_methods=stream, getModelName"
        ),
    )
    retry = TATGEngineAdapter._frontier_short_retry_prompt(
        frontier_sketch_section=sketch_section,
        target_method="target",
        executable_candidate_recipe_section=recipe_section,
        collaborator_callable_map_section=(
            "[Source-Derived Collaborator Callable Map]\n"
            "- K1 type=Model; source_visible_methods=stream, getModelName"
        ),
    )

    combined = "\n\n".join([sketch_section, recipe_section, retry])
    assert "[more]" not in combined
    assert "priority objective item tail omitted" not in combined
    assert "executable relation recipe: matching row" in combined
    assert "assert exact result or exact documented exception" in combined
    assert TATGEngineAdapter._high_priority_mid_field_clip(combined) is False


