def test_short_json_retry_prompt_replaces_long_prompt_and_keeps_recipe():
    overload_contracts = TATGEngineAdapter._method_overload_contracts(
        """
public class DefaultRequestHandler {
    public Result onMessageSend(
            MessageSendParams params,
            ServerCallContext context) {
        return null;
    }
    public Result onMessageSend(MessageSendParams params) {
        return null;
    }
}
""",
        "onMessageSend",
    )
    target_overload_id = "onMessageSend#MessageSendParams-ServerCallContext"
    retry = TATGEngineAdapter._json_patch_short_retry_prompt(
        previous_error="json_patch_rejected; invalid_reason=json_instead_of_java",
        coverage_feedback_section=(
            "[Coverage Feedback For This Generation Round]\n"
            "- O7 [GuardOutcome]; missed source line L42; "
            "target the false outcome with an exact observable result"
        ),
        deep_frontier_first_candidate_section="[Deep Frontier First Candidate]\n- candidate_role=valid_baseline; target_call=onMessageSend(...); terminal_consumer=.block()",
        executable_baseline_schema_section="[Executable Baseline Schema]\n- schema_id=EB1; baseline_skeleton_id=B1",
        executable_candidate_recipe_section="[Executable Candidate Recipe]\n- R1; source_skeleton=B1; candidate_role=valid_baseline",
        construction_repair_map_section="[Source-Derived Construction Repair Map]\n- C1 type=Request; source_proven_replacement=Request.builder().build()",
        collaborator_callable_map_section="[Source-Derived Collaborator Callable Map]\n- K1 type=Executor; source_visible_methods=execute",
        target_overload_ids={target_overload_id},
        target_descriptor="(LMessageSendParams;LServerCallContext;)LResult;",
        overload_contracts=overload_contracts,
        target_method="onMessageSend",
        target_class="DefaultRequestHandler",
        lazy_terminal_markers=[".block(", "StepVerifier.create("],
        suggested_tests=8,
    )
    effective = TATGEngineAdapter._inject_generation_retry_note(
        "[Generation Control Receipt]\nlong\n\n---\n\nSource code under test:\n" + "x" * 20000,
        retry,
    )

    assert effective.startswith("[Short JSON Retry Prompt]")
    assert "Source code under test:" not in effective
    assert "Return exactly 2 new_tests item" in effective
    assert ".block(" in effective
    assert "DefaultRequestHandler" in effective
