def test_mutation_short_json_retry_retains_only_m_id_context_and_green_setup():
    original = "\n\n".join([
        "[Generation Control Receipt]\n- mutation_extra_mode=true",
        (
            "[Mutation Objective Context]\n"
            "- M7 [MutationReachability] required_candidate: "
            "candidate_role=mutation_reachability; status=NO_COVERAGE; "
            "line=42; mutator=negate-conditional\n"
            "  source: `if (ready) {`\n"
            "  source_visible_observable_effect: "
            "kind=conditional_specific_exception; effect=throw new "
            "IllegalStateException();"
        ),
        (
            "[Source-Visible Mutation Entry Paths]\n"
            "- preferred_direct_constructor: `new Subject(...)`; "
            "path=Subject -> hiddenTarget"
        ),
        (
            "[Existing Green Exact-Call Setup Examples]\n"
            "@Test\npublic void green() {\n"
            "    Subject value = new Subject(validInput);\n"
            "    assertEquals(1, value.result());\n}"
        ),
        "[Current Round Test Objectives]\n- O1 structural row",
        "Source code under test:\n" + "x" * 20000,
    ])
    retry = TATGEngineAdapter._json_patch_short_retry_prompt(
        previous_error="invalid JSON shape",
        target_method="hiddenTarget",
        target_class="Subject",
        entry_method_names=["Subject"],
        mutation_feedback_only=True,
        mutation_objective_status_by_id={"M7": "NO_COVERAGE"},
        suggested_tests=1,
    )

    effective = TATGEngineAdapter._inject_generation_retry_note(
        original,
        retry,
    )

    assert effective.startswith("[Short JSON Retry Prompt]")
    assert "M7 [MutationReachability]" in effective
    assert "line=42" in effective
    assert "conditional_specific_exception" in effective
    assert "new Subject(validInput)" in effective
    assert "preferred_direct_constructor" in effective
    assert "[Current Round Test Objectives]" not in effective
    assert "Source code under test:" not in effective
    assert effective.rfind("[Strict Output Schema]") > effective.find(
        "[Existing Green Exact-Call Setup Examples]"
    )


