def test_target_call_arity_mismatch_uses_source_overload_contract():
    contracts = TATGEngineAdapter._method_overload_contracts(
        """
public class Handler {
    public void start(String uri, String local, String qName, Attributes atts) {
    }
}
""",
        "start",
    )
    wrong = """
@Test
public void testWrong() {
    Handler handler = new Handler();
    handler.start("root", new Attribute[0], Namespace.NO_NAMESPACE);
    assertTrue(true);
}
"""
    valid = """
@Test
public void testValid() {
    Handler handler = new Handler();
    handler.start("", "root", "root", new AttributesImpl());
    assertTrue(true);
}
"""

    mismatches = TATGEngineAdapter._target_call_arity_mismatches(
        wrong,
        method_name="start",
        overload_contracts=contracts,
    )

    assert mismatches[0]["expected_arity"] == 4
    assert mismatches[0]["observed_arities"] == [3]
    assert TATGEngineAdapter._target_call_arity_mismatches(
        valid,
        method_name="start",
        overload_contracts=contracts,
    ) == []


