def test_deterministic_semantic_replay_requires_executable_producer_call():
    incomplete = {
        "sketch_id": "SK1",
        "semantic_replay_required": True,
        "existing_green_protected_setup_actions": [
            "Codec codec = new Codec();",
            "byte[] input = new byte[] { 1 };",
            "int inPos = 0;",
            "int inAvail = input.length;",
            "Context context = new Context();",
        ],
        "required_arrange": [
            "codec.decode(input, inPos, inAvail, context);",
        ],
        "semantic_exact_entry_call": (
            "codec.decode(input, inPos, -1, context);"
        ),
        "oracle_observation": ["assertEquals(1, context.modulus);"],
    }
    assert TATGEngineAdapter._deterministic_semantic_replay_patch(
        [incomplete]
    ) == ""

    closed = dict(incomplete)
    closed["existing_green_protected_setup_actions"] = [
        *incomplete["existing_green_protected_setup_actions"],
        "codec.decode(input, inPos, inAvail, context);",
    ]
    raw = TATGEngineAdapter._deterministic_semantic_replay_patch([closed])
    code = "\n".join(json.loads(raw)["new_tests"][0]["test_code_lines"])
    assert code.index("inAvail, context") < code.index("-1, context")


