def test_semantic_replay_focused_frontier_requires_sk_without_prompt_conflict():
    sketches = [{
        "sketch_id": "SK1",
        "kind": "semantic_replay_receiver_field",
        "semantic_replay_required": True,
        "source_evidence": ["source line 12: if (state.ready())"],
        "required_arrange": ["reuse compile-proven scaffold GS1"],
        "target_call": "subject.target(input)",
        "oracle_observation": ["assertEquals(1, result)"],
        "existing_green_protected_setup_actions": [
            "Subject subject = createSubject();",
        ],
    }]

    ordinary = TATGEngineAdapter._render_frontier_candidate_sketches_section(
        sketches,
        feedback_round=True,
    )
    focused = TATGEngineAdapter._render_frontier_candidate_sketches_section(
        sketches,
        feedback_round=True,
        require_semantic_replay_objective_id=True,
    )
    mixed = TATGEngineAdapter._render_frontier_candidate_sketches_section(
        sketches,
        feedback_round=False,
        require_semantic_replay_objective_id=True,
        exclusive_semantic_replay_contract=False,
    )

    assert "Advisory only" in ordinary
    assert "optional objective_id" in ordinary
    assert "Advisory only" not in focused
    assert "optional objective_id" not in focused
    assert "every returned test must select exactly one listed SK-id" in focused
    assert "required objective_id must equal this sketch id" in focused
    assert "Replay binding contract" in mixed
    assert "separate structural objectives keep their own objective id" in mixed
    assert "every returned test must select" not in mixed


def test_semantic_replay_candidate_must_preserve_selected_green_scaffold_order():
    sketches = [{
        "sketch_id": "SK1",
        "semantic_replay_required": True,
        "existing_green_protected_setup_actions": [
            "Dependency dependency = dependency();",
            "Subject subject = new Subject(dependency);",
            "dependency.start();",
        ],
    }]
    metadata = {"test_objective_map": {"testDeep": "SK1"}}
    passing = """
@Test
public void testDeep() throws Exception {
    Dependency dependency = dependency();
    Subject subject = new Subject(dependency);
    dependency.start();
    subject.advance();
    assertEquals(1, subject.target());
}
"""
    reordered = """
@Test
public void testDeep() throws Exception {
    Dependency dependency = dependency();
    dependency.start();
    Subject subject = new Subject(dependency);
    assertEquals(1, subject.target());
}
"""

    assert (
        TATGEngineAdapter._semantic_replay_scaffold_sequence_violation(
            passing,
            metadata,
            sketches,
        )
        == ""
    )
    violation = (
        TATGEngineAdapter._semantic_replay_scaffold_sequence_violation(
            reordered,
            metadata,
            sketches,
        )
    )
    assert "did not preserve compile-proven scaffold step_" in violation
    assert "in order" in violation


