def test_source_consistent_causal_replay_rejects_inserted_receiver_call():
    sketches = [{
        "sketch_id": "SK1",
        "semantic_replay_required": True,
        "semantic_exact_setup_sequence": True,
        "semantic_required_setup_actions": [
            'JsonReader reader = new JsonReader(new StringReader("/*x*/"));',
            "reader.setLenient(true);",
        ],
        "semantic_exact_entry_call": "reader.doPeek()",
    }]
    metadata = {"test_objective_map": {"testDeep": "SK1"}}
    exact = """
@Test
public void testDeep() throws Exception {
    JsonReader reader = new JsonReader(new StringReader("/*x*/"));
    reader.setLenient(true);
    int result = reader.doPeek();
    assertEquals(15, result);
}
"""
    polluted = exact.replace(
        "int result = reader.doPeek();",
        "reader.beginArray();\n    int result = reader.doPeek();",
    )

    assert TATGEngineAdapter._semantic_replay_scaffold_sequence_violation(
        exact, metadata, sketches
    ) == ""
    violation = TATGEngineAdapter._semantic_replay_scaffold_sequence_violation(
        polluted, metadata, sketches
    )
    assert "inserted receiver call `reader.beginArray(...)`" in violation


