def test_replay_proven_rows_from_feedback_render_as_short_retry_sketches():
    sketches = TATGEngineAdapter._replay_proven_row_sketches_from_feedback({
        "replay_proven_rows": [
            {
                "row_id": "R_numeric",
                "proof_status": "proven_passing",
                "input_json": '{ "count": [ { "numeric": [ ">", 1, "<=", 5 ] } ] }',
                "entry_call": "JsonRuleCompiler.compile(validJson)",
                "expected_oracle": "compiled result accepts the numeric row",
                "entry_return_contract": "`JsonRuleCompiler.compile(validJson)` returns `List<Map<String,List<Patterns>>>`; assign to this exact source-visible type or use `var`",
                "source_evidence": ["literal/operator `numeric` branch in target source"],
                "expected_branch_family": "numeric_range",
                "candidate_target_coverage": {
                    "line_coverage": 0.42,
                    "line_covered": 45,
                    "branch_coverage": 0.31,
                    "branch_covered": 12,
                    "closes_baseline_gap": True,
                },
            },
            {
                "row_id": "R_prefix",
                "proof_status": "not_proven",
                "input_json": '{ "source": [ { "prefix": "aws." } ] }',
                "entry_call": "JsonRuleCompiler.compile(validJson)",
                "expected_oracle": "accepted",
            },
        ]
    })

    assert len(sketches) == 1
    sketch = sketches[0]
    assert sketch["kind"] == "replay_proven_json_row"
    assert sketch["sketch_id"] == "SK_ROW_R_numeric"
    assert sketch["proof_status"] == "proven_passing"
    assert sketch["proof_target_value"] == "coverage_gain"
    assert TATGEngineAdapter._frontier_short_retry_enabled(sketches)
    rendered = TATGEngineAdapter._render_frontier_candidate_sketches_section(sketches)
    assert "kind=replay_proven_json_row" in rendered
    assert "proof_target_value=coverage_gain" in rendered
    assert "entry_return_contract" in rendered
    assert "List<Map<String,List<Patterns>>>" in rendered
    assert "candidate_target_coverage" in rendered
    assert "JsonRuleCompiler.compile(validJson)" in rendered
    assert "coverage_obligation_id must stay empty" in rendered


