def test_frontier_short_retry_merge_preserves_prior_candidates_and_metadata():
    prior = "@Test\npublic void testO3() {}\n"
    retry = "@Test\npublic void testSketch() {}\n"
    merged_code = TATGEngineAdapter._merge_json_patch_fragments(prior, retry)
    merged_meta = TATGEngineAdapter._merge_json_patch_metadata(
        {
            "test_obligation_map": {"testO3": "O3"},
            "test_candidate_role_map": {"testO3": "branch_axis"},
            "source_builder_constructor_rewrites": ["C1"],
        },
        {
            "test_objective_map": {"testSketch": "SK_ENTRY_PRECONDITION_1"},
            "test_candidate_role_map": {"testSketch": "entry_path"},
            "source_builder_constructor_rewrites": ["C1", "C2"],
        },
    )

    assert "testO3" in merged_code
    assert "testSketch" in merged_code
    assert merged_meta["test_obligation_map"]["testO3"] == "O3"
    assert merged_meta["test_objective_map"]["testSketch"] == "SK_ENTRY_PRECONDITION_1"
    assert merged_meta["test_candidate_role_map"] == {
        "testO3": "branch_axis",
        "testSketch": "entry_path",
    }
    assert merged_meta["source_builder_constructor_rewrites"] == ["C1", "C2"]


