def test_source_derived_construction_repair_map_renders_unavailable_method_blocker(tmp_path: Path):
    response = tmp_path / "io/acme/ChatResponse.java"
    response.parent.mkdir(parents=True)
    response.write_text(
        """
package io.acme;
public class ChatResponse {
    public java.util.List<String> getContent() { return java.util.List.of(); }
    public String getFinishReason() { return "stop"; }
    public static Builder builder() { return new Builder(); }
    public static class Builder {
        public Builder content(java.util.List<String> content) { return this; }
        public ChatResponse build() { return new ChatResponse(); }
    }
}
""".strip(),
        encoding="utf-8",
    )
    symbol_index = {"ChatResponse": ["io.acme.ChatResponse"]}
    feedback = {
        "streaming_validation_failed_details": [
            {
                "stdout_tail": """
[ERROR] cannot find symbol
[ERROR]   symbol:   method getChoice(int)
[ERROR]   location: variable chatResponse of type io.acme.ChatResponse
""",
            }
        ]
    }

    section = TATGEngineAdapter._render_source_derived_construction_repair_map_section(
        project_root=tmp_path,
        coverage_feedback=feedback,
        symbol_index=symbol_index,
    )

    assert "blocked_unavailable_method=getChoice(int)" in section
    assert "source_proven_methods=builder, getContent, getFinishReason" in section
    assert "do not invent accessors" in section


