def test_generation_control_receipt_does_not_promote_unrelated_visible_constructors_to_required_inputs():
    symbol_grounding = """
[Visible Type Construction APIs]
- RotationOrder:
  - enum constants XYZ, XZY, YXZ, YZX, ZXY, ZXZ
- CardanEulerSingularityException:
  - CardanEulerSingularityException(boolean isCardan)
- DummyLocalizable:
  - DummyLocalizable(String source)
- ExceptionContext:
  - ExceptionContext(Throwable throwable)
""".strip()

    receipt = TATGEngineAdapter._render_generation_control_receipt(
        target_desc="Rotation.getAngles",
        method_name="getAngles",
        patch_mode=True,
        suggested_tests=2,
        symbol_grounding=symbol_grounding,
        source_code="""
class Rotation {
    public double[] getAngles(RotationOrder order)
            throws CardanEulerSingularityException {
        return new double[3];
    }
}
""".strip(),
        class_name="Rotation",
        method_access="public",
        target_param_type_names=["RotationOrder"],
    )

    start = receipt.find("- source_required_public_input_baseline:")
    if start < 0:
        required_input_section = ""
    else:
        tail = receipt[start:].splitlines()
        kept = [tail[0]]
        for line in tail[1:]:
            if line.startswith("- ") and not line.startswith("  -"):
                break
            kept.append(line)
        required_input_section = "\n".join(kept)

    assert "CardanEulerSingularityException" not in required_input_section
    assert "DummyLocalizable" not in required_input_section
    assert "ExceptionContext" not in required_input_section


def test_private_target_required_inputs_use_only_primary_verified_entry_signature():
    symbol_grounding = """
[Visible Type Construction APIs]
- InternalState:
  - InternalState(String hiddenValue)
- Request:
  - Request(String publicValue)
- UnrelatedRequest:
  - UnrelatedRequest(String unrelatedValue)
""".strip()
    source = """
class Handler {
    public void run(Request request) { hidden(new InternalState(request.value())); }
    public void debug(UnrelatedRequest request) { hidden(new InternalState(request.value())); }
    private void hidden(InternalState state) { }
}
""".strip()

    receipt = TATGEngineAdapter._render_generation_control_receipt(
        target_desc="Handler.hidden",
        method_name="hidden",
        patch_mode=True,
        suggested_tests=2,
        symbol_grounding=symbol_grounding,
        source_code=source,
        class_name="Handler",
        method_access="private",
        target_param_type_names=["InternalState"],
        entry_points=[
            {
                "method": "run",
                "access": "public",
                "path": ["run", "hidden"],
                "signature_path": [
                    "public void run(Request request) {",
                    "private void hidden(InternalState state) {",
                ],
            },
            {
                "method": "debug",
                "access": "public",
                "path": ["debug", "hidden"],
                "signature_path": [
                    "public void debug(UnrelatedRequest request) {",
                    "private void hidden(InternalState state) {",
                ],
            },
        ],
    )

    start = receipt.find("- source_required_public_input_baseline:")
    assert start >= 0
    tail = receipt[start:].splitlines()
    kept = [tail[0]]
    for line in tail[1:]:
        if line.startswith("- ") and not line.startswith("  -"):
            break
        kept.append(line)
    required_input_section = "\n".join(kept)

    assert "Request: set required constructor/builder inputs publicValue" in required_input_section
    assert "InternalState:" not in required_input_section
    assert "UnrelatedRequest:" not in required_input_section


