def test_source_method_signature_scan_is_bounded_for_large_multiline_generic_source():
    from time import perf_counter

    filler = "\n".join(
        f"  private String field{i} = \"value{i}\";" for i in range(2500)
    )
    source = f"""
package com.acme;
class Handler {{
{filler}
  protected static Map<String, Object> validate(
      final List<? extends Payload> payloads,
      Context[] contexts
  ) throws ValidationException {{
    return Map.of();
  }}
  void caller() {{
    validate(List.of(), new Context[0]);
  }}
}}
""".strip()

    started = perf_counter()
    signatures = TATGEngineAdapter._source_method_signature_texts(source, "validate")
    names = TATGEngineAdapter._source_method_param_type_names(source, "validate")
    elapsed = perf_counter() - started

    assert len(signatures) == 1
    assert "Map<String, Object> validate(" in signatures[0]
    assert names == ["Payload", "Context"]
    assert elapsed < 1.0


