def test_rewrite_null_target_calls_for_single_param_overload():
    code = """
import org.junit.Test;

@Test
public void testWriteStringNull() throws Exception {
    generator.writeString(null);
}
"""
    overloads = [
        {
            "overload_id": "writeString#String",
            "param_types": ["String"],
        },
        {
            "overload_id": "writeString#SerializableString",
            "param_types": ["SerializableString"],
        },
    ]

    rewritten = TATGEngineAdapter._rewrite_null_target_calls_for_overload(
        code,
        method_name="writeString",
        overload_contracts=overloads,
        test_overload_map={"testWriteStringNull": "writeString#String"},
    )

    assert "writeString((String) null)" in rewritten


def test_extract_patch_normalizes_signature_style_overload_id():
    raw = json.dumps(
        {
            "new_tests": [
                {
                    "overload_id": "writeString(String text)",
                    "test_name": "testWriteStringString",
                    "test_code_lines": [
                        "@Test",
                        "public void testWriteStringString() throws Exception {",
                        "  generator.writeString(\"x\");",
                        "  assertTrue(true);",
                        "}",
                    ],
                    "new_imports_lines": ["import org.junit.Test;"],
                }
            ]
        }
    )

    patch, metadata = TATGEngineAdapter._extract_patch_from_json_output(
        raw,
        overload_contract_ids={"writeString#String", "writeString#SerializableString"},
        return_metadata=True,
    )

    assert "testWriteStringString" in patch
    assert metadata["test_overload_map"]["testWriteStringString"] == "writeString#String"


def test_extract_patch_normalizes_duplicate_noargs_method_name_overload_id():
    raw = json.dumps(
        {
            "new_tests": [
                {
                    "overload_id": "next",
                    "test_name": "testNext",
                    "test_code_lines": [
                        "@Test",
                        "public void testNext() throws Exception {",
                        "  assertNotNull(walker.next());",
                        "}",
                    ],
                    "new_imports_lines": ["import org.junit.Test;"],
                }
            ]
        }
    )

    patch, metadata = TATGEngineAdapter._extract_patch_from_json_output(
        raw,
        overload_contract_ids={"next#noargs", "next#noargs_2"},
        target_overload_ids={"next#noargs", "next#noargs_2"},
        target_call_names=["next"],
        return_metadata=True,
    )

    assert "testNext" in patch
    assert metadata["test_overload_map"]["testNext"] == "next#noargs"


def test_extract_patch_does_not_normalize_method_name_across_real_overloads():
    raw = json.dumps(
        {
            "new_tests": [
                {
                    "overload_id": "target",
                    "test_name": "testTarget",
                    "test_code_lines": [
                        "@Test",
                        "public void testTarget() throws Exception {",
                        "  target(\"x\");",
                        "}",
                    ],
                    "new_imports_lines": ["import org.junit.Test;"],
                }
            ]
        }
    )

    with pytest.raises(TATGEngineAdapter.PatchExtractionError) as exc_info:
        TATGEngineAdapter._extract_patch_from_json_output(
            raw,
            overload_contract_ids={"target#String", "target#int"},
            target_overload_ids={"target#String"},
            target_call_names=["target"],
        )
    assert "unknown overload_id" in str(exc_info.value)


