def test_coverage_guided_generation_retries_source_backed_forbidden_call(monkeypatch, tmp_path: Path):
    adapter = TATGEngineAdapter()
    source_file = tmp_path / "src/main/java/com/acme/Foo.java"
    source_file.parent.mkdir(parents=True, exist_ok=True)
    source_file.write_text(
        "package com.acme;\npublic class Foo { public int parse(int x) { return x > 0 ? 1 : 0; } }\n",
        encoding="utf-8",
    )
    calls = {"count": 0, "retry_prompt": ""}

    def fake_chat_completion(**kwargs):
        calls["count"] += 1
        if calls["count"] == 1:
            return {
                "content": (
                    '{"new_tests":[{"overload_id":"parse#int","coverage_obligation_id":"O1",'
                    '"test_behavior":"O1 unavailable helper route","test_name":"testO1BadRoute",'
                    '"test_code_lines":["@Test","public void testO1BadRoute() {",'
                    '"    Foo foo = Helper.missingFactory();","    assertEquals(1, foo.parse(1));","}"],'
                    '"new_imports_lines":["import org.junit.Test;","import static org.junit.Assert.*;"]}]}'
                ),
                "usage": {},
            }
        calls["retry_prompt"] = kwargs["user_prompt"]
        return {
            "content": (
                '{"new_tests":[{"overload_id":"parse#int","coverage_obligation_id":"O1",'
                '"test_behavior":"O1 direct constructor route","test_name":"testO1GoodRoute",'
                '"test_code_lines":["@Test","public void testO1GoodRoute() {",'
                '"    Foo foo = new Foo();","    assertEquals(1, foo.parse(1));","}"],'
                '"new_imports_lines":["import org.junit.Test;","import static org.junit.Assert.*;"]}]}'
            ),
            "usage": {},
        }

    monkeypatch.setattr("tatg.engines.tatg_adapter.chat_completion_with_usage", fake_chat_completion)
    monkeypatch.setattr("tatg.engines.tatg_adapter.build_static_analysis_context", lambda **kwargs: "")
    monkeypatch.setattr(
        "tatg.engines.tatg_adapter.build_type_aware_context",
        lambda *args, **kwargs: SimpleNamespace(
            type_shapes={}, mock_scaffold=None, autowired_deps=[], branch_hints=[], execution_recipes=[]
        ),
    )

    target = Target(scope=Scope.METHOD, source_file=source_file, class_name="Foo", method_name="parse")
    request = GenerationRequest(
        backend="tatg",
        scope=Scope.METHOD,
        project_root=tmp_path,
        target_file=source_file,
        class_name="Foo",
        method_name="parse",
        model="test-model",
        api_base="http://example.invalid/v1",
        api_key_env="OPENAI_API_KEY",
        test_command="mvn test",
        coverage_report_path="",
        coverage_type="jacoco",
        prompt_extra_text="",
        prompt_extra_file=None,
        prompt_insert=PromptInsertPosition.AFTER_USER,
        static_analysis_json=None,
        pass_specs=[],
        dry_run=False,
        max_iterations=2,
        cat_engine_root=tmp_path,
        method_engine_root=tmp_path,
        junit_family="junit4",
    )
    request.generation_coverage_feedback_by_label = {
        target.label: {
            "method_name": "parse",
            "generation_iteration": 3,
            "coverage_obligations": [{"id": "O1", "scenario": "cover positive branch"}],
            "measured_directional_feedback": {
                "next_required_obligation_ids": ["O1"],
                "open_obligation_ids": ["O1"],
                "source_backed_compile_blockers": {
                    "missing_known_type_methods": [
                        {"owner": "Helper", "method": "missingFactory", "known_methods": ["validFactory"]}
                    ]
                },
            },
        }
    }

    result = adapter.generate_test_for_target(request, target, tmp_path, "mvn test")

    assert result["status"] == "success"
    assert calls["count"] == 2
    assert "Helper.missingFactory" in calls["retry_prompt"]
    assert "testO1GoodRoute" in result["generated_code"]
    assert "missingFactory" not in result["generated_code"]


