def test_private_reflection_validator_requires_method_accessible_and_invoke():
    valid_code = """
@Test
public void testHidden() throws Exception {
    Foo foo = new Foo();
    Method method = Foo.class.getDeclaredMethod("hidden", int.class);
    method.setAccessible(true);
    assertEquals(2, method.invoke(foo, 1));
}
"""
    smoke_code = """
@Test
public void testSmoke() {
    Foo foo = new Foo();
    assertNotNull(foo);
}
"""

    assert TATGEngineAdapter._test_code_uses_private_reflection(valid_code, "hidden")
    assert not TATGEngineAdapter._test_code_uses_private_reflection(smoke_code, "hidden")


