def test_mutation_survived_setup_prefix_comes_only_from_named_green_test():
    existing = """
class SubjectTest {
    @Test
    public void testPitGreenBoundary() {
        Subject subject = new Subject(7);
        Object actual = subject.target();
        assertNotNull(actual);
    }

    @Test
    public void testUnrelated() {
        Subject subject = new Subject(99);
        assertEquals(99, subject.value());
    }
}
"""
    feedback = {
        "mutation_objectives": [{
            "id": "M1",
            "facts": {
                "status": "SURVIVED",
                "description": "replaced return value with null",
                "pit_covering_tests": [
                    "testPitGreenBoundary(example.SubjectTest)"
                ],
            },
        }]
    }

    prefixes = TATGEngineAdapter._mutation_survived_green_setup_prefixes(
        existing,
        feedback,
        target_method="target",
        target_descriptor="()Ljava/lang/Object;",
    )

    assert set(prefixes) == {"M1"}
    assert "newSubject(7)" in prefixes["M1"][0]
    assert "subject.target()" in prefixes["M1"][0]
    assert "assertTrue" not in prefixes["M1"][0]
    assert "newSubject(99)" not in prefixes["M1"][0]


def test_mutation_seed_propagation_witness_rejects_mutant_equivalent_null_oracle():
    feedback = {
        "mutation_objectives": [{
            "id": "M1",
            "facts": {
                "status": "SURVIVED",
                "description": "replaced return value with null",
            },
        }]
    }
    separating = """
        JsonToken result = delegate.nextToken();
        assertEquals(JsonToken.START_OBJECT, result);
    """
    equivalent = """
        JsonToken result = delegate.nextToken();
        assertNull(result);
    """

    assert TATGEngineAdapter._mutation_seed_propagation_witness(
        separating,
        feedback,
        target_method="nextToken",
    ) == 1
    assert TATGEngineAdapter._mutation_seed_propagation_witness(
        equivalent,
        feedback,
        target_method="nextToken",
    ) == -1


def test_mutation_existing_context_prefers_propagation_witness_green_seed():
    existing = """
class ParserTest {
    @Test
    public void testCoveredButNull() {
        Parser parser = parserFor("excluded");
        JsonToken result = parser.nextToken();
        assertNull(result);
    }

    @Test
    public void testCoveredAndSeparating() {
        Parser parser = parserFor("included");
        JsonToken result = parser.nextToken();
        assertEquals(JsonToken.VALUE_STRING, result);
    }
}
"""
    feedback = {
        "mutation_objectives": [{
            "id": "M1",
            "facts": {
                "status": "SURVIVED",
                "description": "replaced return value with null",
                "pit_covering_tests": [
                    "testCoveredButNull(example.ParserTest)",
                    "testCoveredAndSeparating(example.ParserTest)",
                ],
            },
        }]
    }

    rendered = TATGEngineAdapter()._render_existing_test_context(
        existing,
        "nextToken",
        mutation_feedback_only=True,
        mutation_feedback=feedback,
    )

    assert "testCoveredAndSeparating" in rendered
    assert "public void testCoveredButNull" not in rendered
    assert "public void testCoveredAndSeparating" in rendered
    assert "value different from the mutant replacement" in rendered


