def test_sootup_entry_parser_preserves_visibility_and_full_path(monkeypatch, tmp_path):
    source_file = tmp_path / "Example.java"
    source_file.write_text("class Example { private void target() {} }", encoding="utf-8")
    ctx_text = """
[Static analysis: sootup-callgraph for example.Example.target]
[Reachable Entry Paths]
Path:
  example.Example#helper(): void (default)
  example.Example#target(): void (private)
---
Path:
  example.Example#entry(): void (public)
  example.Example#helper(): void (default)
  example.Example#target(): void (private)
---
"""
    monkeypatch.setattr(
        "tatg.engines.tatg_adapter.build_static_analysis_context",
        lambda **_: ctx_text,
    )
    request = SimpleNamespace(cat_engine_root=tmp_path)
    target = SimpleNamespace(source_file=source_file, method_name="target")

    entry_points = TATGEngineAdapter()._sootup_entry_points(
        request,
        target,
        "class Example { public void entry() { helper(); } void helper() { target(); } private void target() {} }",
    )

    assert {
        "method": "entry",
        "path": ["entry", "helper", "target"],
        "source": "sootup",
        "access": "public",
    } in entry_points
    assert {
        "method": "helper",
        "path": ["helper", "target"],
        "source": "sootup",
        "access": "package-private",
    } in entry_points


def test_descriptor_target_overload_ids_and_rejects_sibling_overload():
    source_code = """
class RulerLike {
    public static boolean matches(final String event, final String rule) { return matches(null, null); }
    private static boolean matches(final JsonNode val, final Patterns pattern) { return false; }
}
class JsonNode {}
class Patterns {}
""".strip()
    contracts = TATGEngineAdapter._method_overload_contracts(source_code, "matches")
    target_ids = TATGEngineAdapter._target_overload_ids_from_descriptor(
        contracts,
        "(Lexample/JsonNode;Lexample/Patterns;)Z",
    )

    assert target_ids == {"matches#JsonNode-Patterns"}

    sibling_payload = '{"new_tests":[{"overload_id":"matches#String-String","test_name":"testPublicWrapper","test_behavior":"wrapper","input_family":"presence:valid","oracle_type":"partition oracle","repair_axis":"presence axis","test_code":"@Test\\npublic void testPublicWrapper() { assertTrue(matches(\\\"{}\\\", \\\"{}\\\")); }","new_imports_code":""}]}'
    try:
        TATGEngineAdapter._extract_patch_from_json_output(
            sibling_payload,
            overload_contract_ids={"matches#String-String", "matches#JsonNode-Patterns"},
            target_overload_ids=target_ids,
        )
    except ValueError as exc:
        assert "sibling overload" in str(exc)
    else:
        raise AssertionError("expected sibling overload payload to be rejected")


