def test_auto_link_imports_rewrites_accessor_property_nested_type_alias(tmp_path: Path, monkeypatch):
    adapter = TATGEngineAdapter()
    TATGEngineAdapter._SYMBOL_INDEX_CACHE.clear()
    monkeypatch.setenv("TATG_DEPENDENCY_SYMBOL_INDEX", "0")

    dto_dir = tmp_path / "src/main/java/com/acme/dto"
