def test_symbol_grounding_renders_one_hop_accessor_construction_api(tmp_path: Path, monkeypatch):
    project = tmp_path / "proj"
    dto = project / "src/main/java/com/acme/dto"
    dto.mkdir(parents=True)
    (dto / "ToolCall.java").write_text(
        """
package com.acme.dto;
public class ToolCall {
    private Function function;
    public ToolCall() {}
    public Function getFunction() { return function; }
    public void setFunction(Function function) { this.function = function; }
}
""".strip(),
        encoding="utf-8",
    )
    (dto / "Function.java").write_text(
        """
package com.acme.dto;
public class Function {
    public Function() {}
    public Function(String name, String arguments) {}
    public String getName() { return ""; }
    public void setName(String name) {}
    public String getArguments() { return ""; }
    public void setArguments(String arguments) {}
    public static Function of(String name, String arguments) { return new Function(name, arguments); }
}
""".strip(),
        encoding="utf-8",
    )
    source = """
package com.acme;
import com.acme.dto.ToolCall;
class Parser {
    void parse(java.util.List<ToolCall> calls) {
        for (ToolCall toolCall : calls) {
            String arguments = toolCall.getFunction().getArguments();
        }
    }
}
""".strip()

    adapter = TATGEngineAdapter()
    TATGEngineAdapter._SYMBOL_INDEX_CACHE.clear()
    monkeypatch.setenv("TATG_DEPENDENCY_SYMBOL_INDEX", "0")
    monkeypatch.setenv("TATG_MEMORY_DIR", str(tmp_path / "memory"))

    section = adapter._render_symbol_grounding_section(
        project_root=project,
        source_code=source,
    )

    assert "ToolCall => com.acme.dto.ToolCall" in section
    assert "Function => com.acme.dto.Function" in section
    assert "[Visible Type Construction APIs]" in section
    assert "Function getFunction()" in section
    assert "setFunction(Function function)" in section
    assert "Function(String name, String arguments)" in section
    assert "static Function of(String name, String arguments)" in section


def test_rewrites_junit_boolean_assertions_to_avoid_boolean_supplier_overload():
    code = """
import static org.junit.jupiter.api.Assertions.*;
class SampleTest {
  void testIt() {
    assertTrue(result instanceof java.util.Map);
    assertFalse(values.containsAll(java.util.Arrays.asList("a", "b")), "unexpected values");
    Assertions.assertTrue(items.contains("x"), "has x");
  }
}
""".strip()

    rewritten = TATGEngineAdapter._rewrite_junit_boolean_assertions_for_functionless_classpath(code)

    assert "assertTrue(" not in rewritten
    assert "assertFalse(" not in rewritten
    assert "assertEquals(true, result instanceof java.util.Map);" in rewritten
    assert 'assertEquals(false, values.containsAll(java.util.Arrays.asList("a", "b")), "unexpected values");' in rewritten
    assert 'Assertions.assertEquals(true, items.contains("x"), "has x");' in rewritten


def test_rewrites_junit4_boolean_assertion_message_first():
    code = """
import static org.junit.Assert.*;
class SampleTest {
  void testIt() {
    assertFalse(output.contains("x"), "unexpected output");
  }
}
""".strip()

    rewritten = TATGEngineAdapter._rewrite_junit_boolean_assertions_for_functionless_classpath(code)

    assert 'assertEquals("unexpected output", false, output.contains("x"));' in rewritten


def test_rewrites_valid_junit4_boolean_assertion_without_reversing_arguments():
    code = """
import static org.junit.Assert.*;
class SampleTest {
  void testIt() {
    assertTrue("Result should be Float", result instanceof Float);
    assertFalse("Expected non-empty values", values.isEmpty());
  }
}
""".strip()

    rewritten = TATGEngineAdapter._rewrite_junit_boolean_assertions_for_functionless_classpath(code)

    assert 'assertEquals("Result should be Float", true, result instanceof Float);' in rewritten
    assert 'assertEquals("Expected non-empty values", false, values.isEmpty());' in rewritten
    assert 'assertEquals(result instanceof Float, true, "Result should be Float")' not in rewritten


def test_rewrites_junit4_boolean_assert_equals_message_last():
    code = """
import static org.junit.Assert.*;
class SampleTest {
  void testIt() {
    assertEquals(result.contains("x"), true, "expected x");
    assertEquals(false, values.isEmpty(), "expected values");
  }
}
""".strip()

    rewritten = TATGEngineAdapter._rewrite_junit_boolean_assertions_for_functionless_classpath(code)

    assert 'assertEquals("expected x", true, result.contains("x"));' in rewritten
    assert 'assertEquals("expected values", false, values.isEmpty());' in rewritten
    assert 'assertEquals(result.contains("x"), true, "expected x")' not in rewritten


