def test_reflective_target_detector_requires_invoke():
    comment_only = """
@Test
public void testCommentOnly() {
    // Foo.class.getDeclaredMethod("doCall", java.util.List.class);
    assertNotNull(new Foo());
}
"""
    lookup_only = """
@Test
public void testLookupOnly() throws Exception {
    java.lang.reflect.Method method = Foo.class.getDeclaredMethod("doCall", java.util.List.class);
    method.setAccessible(true);
    assertNotNull(method);
}
"""

    assert not TATGEngineAdapter._test_code_calls_any_method(comment_only, ["doCall"])
    assert not TATGEngineAdapter._test_code_calls_any_method(lookup_only, ["doCall"])


