def test_mutation_patch_rejection_reason_classifies_schema_and_oracle_failures():
    assert TATGEngineAdapter._mutation_patch_rejection_reason(
        extraction_error="Invalid JSON response: Expecting value",
        mutation_feedback_active=True,
    ) == "mutation_schema_format_error"
    assert TATGEngineAdapter._mutation_patch_rejection_reason(
        extraction_error="JSON response contained test_code entries, but none asserted observable behavior",
        skip_counts={"without_observable_check": 1},
        mutation_feedback_active=True,
    ) == "weak_oracle_rejected"
    assert TATGEngineAdapter._mutation_patch_rejection_reason(
        extraction_error="Mutation candidate omitted the exact target/entry method call",
        skip_counts={"mutation_candidate_missing_target_call": 1},
        mutation_feedback_active=True,
    ) == "mutation_candidate_missing_target_call"
    assert TATGEngineAdapter._mutation_patch_rejection_reason(
        extraction_error="JSON response must contain non-empty new_tests array",
        mutation_feedback_active=True,
    ) == "mutation_test_extraction_empty"


def test_mutation_objective_renders_only_distinguishing_boundary_rows():
    section = TATGEngineAdapter._render_mutation_objective_context_section([{
        "id": "M1",
        "kind": "MutationAssertion",
        "facts": {
            "status": "SURVIVED",
            "line": 10,
            "source_line": "if (size > 16) {",
            "source_backed_mutation_constraints": [{
                "kind": "numeric_predicate_boundary",
                "rows": [
                    {"constraint": "size = 15", "predicate_result": False},
                    {"constraint": "size = 16", "predicate_result": False},
                    {"constraint": "size = 17", "predicate_result": True},
                ],
                "mutant_distinguishing_rows": [{
                    "constraint": "size = 16",
                    "predicate_result": False,
                }],
                "pit_operator_transition": {
                    "original_operator": ">",
                    "mutant_operator": ">=",
                    "distinguishing_relation": "left_operand == right_operand",
                    "distinguishing_relation_is_necessary": True,
                    "proof_status": "pit_mutator_semantics",
                },
            }],
        },
    }])

    assert "source_derived_mutant_distinguishing_input: size = 16" in section
    assert "exact_pit_operator_transition: original `>` -> mutant `>=`" in section
    assert "equality relation is required to infect this boundary mutant" in section
    assert "size = 15" not in section
    assert "size = 17" not in section
    assert "cannot kill this mutant" in section


