def test_source_entry_guard_predicates_use_source_shape_not_state_names():
    source = """
class Machine {
  private Orbit orbit;

  public void launch() {
    if (inspectOrbit() != Orbit.PRIMED) {
      throw new IllegalStateException();
    }
    resolve();
  }

  private Orbit inspectOrbit() {
    return orbit;
  }

  private void resolve() {
  }
}
""".strip()
    body = """
    if (inspectOrbit() != Orbit.PRIMED) {
      throw new IllegalStateException();
    }
    resolve();
""".strip()

    predicates = TATGEngineAdapter._source_entry_guard_predicates(
        source_code=source,
        body=body,
        path_call_names={"resolve"},
    )

    assert predicates == ["inspectOrbit() != Orbit.PRIMED"]


