def test_auto_link_imports_wildcard_core_does_not_mask_util_dependency(tmp_path: Path, monkeypatch):
    adapter = TATGEngineAdapter()
    TATGEngineAdapter._SYMBOL_INDEX_CACHE.clear()

    dep_jar = tmp_path / "jackson-core-test.jar"
    with zipfile.ZipFile(dep_jar, "w") as jar:
        jar.writestr("com/fasterxml/jackson/core/ObjectCodec.class", b"")
        jar.writestr("com/fasterxml/jackson/core/util/BufferRecycler.class", b"")

    monkeypatch.setattr(
        "tatg.engines.tatg_adapter.build_classpath_for_project",
        lambda *args, **kwargs: str(dep_jar),
    )

    generated = """
package com.fasterxml.jackson.dataformat.xml.deser;

import com.fasterxml.jackson.core.*;

public class FromXmlParserTest {
    public void t() {
        ObjectCodec codec = null;
        BufferRecycler recycler = new BufferRecycler();
    }
}
""".strip()

    rewritten, added = adapter._auto_link_imports(
        generated,
        project_root=tmp_path,
        source_code="package com.fasterxml.jackson.dataformat.xml.deser; public class FromXmlParser {}",
        type_shapes={},
    )

    assert "import com.fasterxml.jackson.core.*;" in rewritten
    assert "import com.fasterxml.jackson.core.ObjectCodec;" not in rewritten
    assert "import com.fasterxml.jackson.core.util.BufferRecycler;" in rewritten
    assert added == ["com.fasterxml.jackson.core.util.BufferRecycler"]


def test_auto_link_imports_prunes_unresolvable_project_import(tmp_path: Path):
    adapter = TATGEngineAdapter()

    real = tmp_path / "src/main/java/com/macro/mall/model/OmsOrderSetting.java"
    real.parent.mkdir(parents=True, exist_ok=True)
    real.write_text(
        "package com.macro.mall.model; public class OmsOrderSetting {}",
        encoding="utf-8",
    )

    generated = """
package com.macro.mall.portal.service.impl;

import com.macro.mall.portal.domain.OmsOrderSetting;

class ImportPruneTest {
    void t() {
        OmsOrderSetting s = new OmsOrderSetting();
    }
}
""".strip()

    source_code = """
package com.macro.mall.portal.service.impl;

import com.macro.mall.model.OmsOrderSetting;

public class OmsPortalOrderServiceImpl {}
""".strip()

    rewritten, added = adapter._auto_link_imports(
        generated,
        project_root=tmp_path,
        source_code=source_code,
        type_shapes={},
    )

    assert "import com.macro.mall.portal.domain.OmsOrderSetting;" not in rewritten
    assert "import com.macro.mall.model.OmsOrderSetting;" in rewritten
    assert "com.macro.mall.model.OmsOrderSetting" in added


