def test_render_symbol_grounding_includes_two_hop_value_object_shapes(tmp_path: Path, monkeypatch):
    adapter = TATGEngineAdapter()
    TATGEngineAdapter._SYMBOL_INDEX_CACHE.clear()
    monkeypatch.setenv("TATG_DEPENDENCY_SYMBOL_INDEX", "0")

    model_dir = tmp_path / "src/main/java/com/acme/model"
    service_dir = tmp_path / "src/main/java/com/acme/service"
    model_dir.mkdir(parents=True)
    service_dir.mkdir(parents=True)
    (model_dir / "Task.java").write_text(
        "package com.acme.model; public class Task { public Task(TaskStatus status) {} }\n",
        encoding="utf-8",
    )
    (model_dir / "TaskStatus.java").write_text(
        "package com.acme.model; public record TaskStatus(TaskState state) {}\n",
        encoding="utf-8",
    )
    (model_dir / "TaskState.java").write_text(
        "package com.acme.model; public enum TaskState { TASK_STATE_WORKING }\n",
        encoding="utf-8",
    )
    source_code = """
package com.acme.service;
import com.acme.model.Task;
public class Handler {
    private Task task;
}
""".strip()
    shapes = {
        "Task": SimpleNamespace(
            methods=[
                SimpleNamespace(name="status", return_type="Task", params=[("TaskStatus", "status")]),
            ],
            constructors=[],
        ),
        "TaskStatus": SimpleNamespace(
            methods=[],
            constructors=[
                SimpleNamespace(params=[("TaskState", "state")]),
            ],
        ),
    }

    text = adapter._render_symbol_grounding_section(
        project_root=tmp_path,
        source_code=source_code,
        type_shapes=shapes,
    )

    assert "Task => com.acme.model.Task" in text
    assert "TaskStatus => com.acme.model.TaskStatus" in text
    assert "TaskState => com.acme.model.TaskState" in text
    assert "- TaskStatus:" in text
    assert "TaskStatus(TaskState state)" in text
    assert "related TaskStatus: TaskStatus(TaskState state)" in text
    assert "builder()" not in text


