def test_prompt_compaction_preserves_visible_type_related_implementations(monkeypatch):
    monkeypatch.setenv("TATG_PROMPT_TARGET_CHARS", "16000")
    symbol_section = "\n".join([
        "[Classpath Symbol Grounding]",
        "Use exact symbols.",
        "[Visible Type Construction APIs]",
        "- MessageSendParams:",
        "  - MessageSendParams(Message message)",
        "- Message:",
        "  - Message(Role role, List<Part<?>> parts)",
        "  - related Part implementation DataPart: DataPart(Object data)",
        *[f"  - filler{i}: value" for i in range(300)],
    ])
    prompt = "\n\n---\n\n".join([
        "[Generation Control Receipt]\n- target=Handler::handle\n- goal=coverage",
        symbol_section,
        "Source code under test:\n" + "\n".join(f"line {i}" for i in range(2000)),
        "Requirements:\n" + "\n".join(f"{i}) requirement" for i in range(300)),
    ])

    compacted = TATGEngineAdapter._compact_user_prompt_to_budget(prompt)

    assert "related Part implementation DataPart" in compacted


