def test_render_construction_recipes_prefers_project_observed_construction(tmp_path: Path):
    adapter = TATGEngineAdapter()

    target = tmp_path / "src/main/java/com/acme/Parser.java"
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text("package com.acme; public class Parser {}", encoding="utf-8")

    factory = tmp_path / "src/main/java/com/acme/ParserFactory.java"
    factory.write_text(
        """
package com.acme;

public class ParserFactory {
    /*
     * A deliberately long comment before the factory keeps source offsets
     * honest; compact comment stripping used to attach create(...) to the
     * preceding method signature.
     */
    public String formatName() {
        return "parser";
    }

    public Parser create(String input) {
        return new Parser();
    }
}
""".strip(),
        encoding="utf-8",
    )

    text = adapter._render_construction_recipes_section(
        source_file=target,
        project_root=tmp_path,
        class_name="Parser",
    )

    assert "[Observed Construction Recipes]" in text
    assert "ParserFactory.java" in text
    assert "(source-proven public factory)" in text
    assert "exact_signature=public Parser create(String input)" in text
    assert "preferred_call_shape=new ParserFactory().create(...)" in text
    assert "do not copy its internal `new Parser(...)` statement" in text
    assert "return new Parser();" not in text
    assert "construction truth" in text
    assert "prefer calling that public factory/owner API" in text
    assert "Avoid direct construction" in text


def test_java_source_mask_preserves_offsets_and_newlines():
    source = (
        'class Factory {\n'
        '  /* comment { with fakeMethod() */\n'
        '  String label = "literal with } and //";\n'
        "  char marker = '}';\n"
        '  // line comment with {\n'
        '  public Target create() { return new Target(); }\n'
        '}\n'
    )

    masked = TATGEngineAdapter._strip_java_comments_and_strings(source)

    assert len(masked) == len(source)
    assert [
        idx for idx, char in enumerate(masked) if char == "\n"
    ] == [
        idx for idx, char in enumerate(source) if char == "\n"
    ]
    method_offset = source.index("public Target create")
    assert masked.index("public Target create") == method_offset
    assert masked.index("new Target") == source.index("new Target")


