def test_target_call_contract_retry_note_is_compact_and_specific():
        error = TATGEngineAdapter.PatchExtractionError(
            "JSON response contained test_code entries, but none invoked the target",
            skip_counts={"without_target_call": 3},
            rejected_entries=[{
                "reason": "without_target_call",
                "method": "testSmoke",
                "calls": ["builder", "build", "generate"],
                "excerpt": "@Test public void testSmoke() { mockModel.generate(xs, opts); }",
            }],
        )

        note = TATGEngineAdapter._target_call_contract_retry_note(
            error=error,
            target_method="doCall",
            required_call_names=["doCall"],
            required_obligation_ids={"O1", "O2"},
        )

        assert "[TARGET-CALL CONTRACT CORRECTION]" in note
        assert "invoke `doCall` directly" in note
        assert "construction-only" in note
        assert "coverage_obligation_id" in note
        assert "O1, O2" in note
        assert "testSmoke" in note
        assert "generate" in note
        assert len(note) < 1900


