def test_categorize_methods_handles_afterall_not_classified_as_after():
    text = """
    @AfterAll
    static void cleanupAll() { release(); }

    @Test
    void scenario() { /* ... */ }
    """.strip()

    setup, tests, teardown = TATGEngineAdapter._categorize_methods(text)

    assert len(setup) == 0
    assert len(tests) == 1
    assert len(teardown) == 1
    assert "@AfterAll" in teardown[0]
    # Crucially: AfterAll must NOT leak into the @Test bucket via a substring
    # match on "@After".
    assert "@AfterAll" not in tests[0]


