def test_duplicate_test_rename_keeps_all_candidate_metadata_aligned():
    existing = """
package com.example;

import org.junit.Test;

public class DemoTest {
    @Test
    public void testSK1BranchDelta() {
    }
}
"""
    patch = """
import org.junit.Test;

@Test
public void testSK1BranchDelta() {
    assertEquals(1, subject.target());
}
"""
    rename_map = TATGEngineAdapter._duplicate_test_method_rename_map(
        existing,
        patch,
    )
    metadata = TATGEngineAdapter._rename_patch_metadata_test_methods(
        {
            "test_overload_map": {"testSK1BranchDelta": "target#noargs"},
            "test_objective_map": {"testSK1BranchDelta": "SK1"},
            "test_candidate_role_map": {
                "testSK1BranchDelta": "role:state_transition"
            },
            "test_baseline_skeleton_map": {"testSK1BranchDelta": "B1"},
            "test_skeleton_fact_ids_map": {
                "testSK1BranchDelta": ["F1", "F2"]
            },
            "test_input_family_map": {"testSK1BranchDelta": "empty_array"},
            "test_oracle_type_map": {"testSK1BranchDelta": "exact_value"},
            "test_repair_axis_map": {"testSK1BranchDelta": "state_delta"},
            "test_unbound_obligation_methods": ["testSK1BranchDelta"],
        },
        rename_map,
    )

    assert rename_map == {
        "testSK1BranchDelta": "testSK1BranchDelta__regen2"
    }
    renamed = "testSK1BranchDelta__regen2"
    assert metadata["test_objective_map"] == {renamed: "SK1"}
    assert metadata["test_candidate_role_map"] == {
        renamed: "role:state_transition"
    }
    assert metadata["test_overload_map"] == {renamed: "target#noargs"}
    assert metadata["test_baseline_skeleton_map"] == {renamed: "B1"}
    assert metadata["test_skeleton_fact_ids_map"] == {
        renamed: ["F1", "F2"]
    }
    assert metadata["test_input_family_map"] == {renamed: "empty_array"}
    assert metadata["test_oracle_type_map"] == {renamed: "exact_value"}
    assert metadata["test_repair_axis_map"] == {renamed: "state_delta"}
    assert metadata["test_unbound_obligation_methods"] == [renamed]
    assert metadata["test_method_rename_map"] == rename_map


