# ---------------------------------------------------------------------------
# Regression: _find_matching_brace must handle Java text blocks (Bug 5)
# ---------------------------------------------------------------------------

def test_find_matching_brace_skips_text_block_braces():
    """Braces inside Java 15+ text blocks must not affect depth counting."""
    source = (
        'void m() {\n'
        '    String s = """\n'
        '        { not a real brace }\n'
        '        """;\n'
        '    int x = 1;\n'
        '}'
    )
    open_pos = source.index('{')
    end = TATGEngineAdapter._find_matching_brace(source, open_pos)
    assert end == len(source)


def test_find_matching_brace_skips_regular_string_braces():
    """Braces inside regular string literals must not affect depth counting."""
    source = 'void m() { String s = "a{b}c"; }'
    open_pos = source.index('{')
    end = TATGEngineAdapter._find_matching_brace(source, open_pos)
    assert end == len(source)


