# Rec A: _merge_test_patch_into_file — tiered fallback
# ---------------------------------------------------------------------------

def test_merge_patch_simple_append_fallback_used_when_import_rewrite_would_corrupt():
    """When the full merge would corrupt the class structure, the simple-append
    fallback inserts the new methods before the last brace without touching imports."""
    existing = (
        "package com.example;\n"
        "import org.junit.Test;\n"
        "public class FooTest {\n"
        "    @Test\n"
        "    public void existingTest() { assertEquals(1, 1); }\n"
        "}\n"
    )
    # A patch that contains a class wrapper (full class, not patch mode) whose
    # import block is deliberately empty — simulating a case where the merger
    # might trip up on import ordering.
    patch = (
        "import org.junit.Test;\n"
        "@Test\n"
        "public void newTest() { assertNotNull(\"x\"); }\n"
    )
    merged = TATGEngineAdapter._merge_test_patch_into_file(existing, patch)
    # Must preserve existing test
    assert "existingTest" in merged
    # Must include the new test
    assert "newTest" in merged
    # Must be valid Java class structure
    assert merged.count("{") == merged.count("}")


