def test_mutation_oracle_accepts_enforced_exception_or_normal_path_assertion():
    expected_exception = """
        try {
            target(input);
            org.junit.Assert.fail("expected exception");
        } catch (IllegalArgumentException exc) {
            org.junit.Assert.assertEquals("expected", exc.getMessage());
        }
    """
    exact_normal_path = """
        try {
            org.junit.Assert.assertEquals(3, target(input));
        } catch (IllegalArgumentException exc) {
            org.junit.Assert.assertEquals("expected", exc.getMessage());
        }
    """

    assert TATGEngineAdapter._test_code_has_mutation_adequate_oracle(
        expected_exception
    )
    assert TATGEngineAdapter._test_code_has_mutation_adequate_oracle(
        exact_normal_path
    )


