# --- _strip_code_fences thinking-block removal ---

class TestStripThinkingBlocks:
    """_strip_code_fences should remove <think>...</think> blocks from reasoning models."""

    def _strip(self, text: str) -> str:
        from tatg.engines.tatg_adapter import TATGEngineAdapter
        return TATGEngineAdapter._strip_code_fences(text)

    def test_removes_think_block_before_json(self):
        raw = "<think>Let me reason about this...</think>\n{\"new_tests\": []}"
        result = self._strip(raw)
        assert "<think>" not in result
        assert result.startswith("{")

    def test_removes_multiline_think_block(self):
        raw = "<think>\nline1\nline2\n</think>\npublic class Foo {}"
        result = self._strip(raw)
        assert "<think>" not in result
        assert "public class Foo {}" in result

    def test_preserves_content_without_think(self):
        raw = "public class FooTest {\n    @Test\n    public void test() {}\n}"
        result = self._strip(raw)
        assert result == raw

    def test_strips_fences_after_think_removal(self):
        raw = "<think>reasoning</think>\n```java\npublic class FooTest {}\n```"
        result = self._strip(raw)
        assert "<think>" not in result
        assert "```" not in result
        assert "public class FooTest {}" in result

    def test_removes_think_block_after_content(self):
        raw = "{\"new_tests\": []}\n<think>post-reasoning</think>"
        result = self._strip(raw)
        assert "<think>" not in result
        assert result.startswith("{")


class TestTryRecoverTruncatedNewTests:
    """_try_recover_truncated_new_tests should salvage complete entries from truncated JSON."""

    import json as _json

    def _recover(self, text: str, error_msg: str = "Unexpected end of data") -> "dict | None":
        import json
        try:
            json.loads(text)
            return None  # valid JSON needs no recovery
        except json.JSONDecodeError as exc:
            # Patch the string representation to contain the expected signal
            class _FakeExc(json.JSONDecodeError):
                pass
            fake = json.JSONDecodeError(error_msg, text, len(text) - 1)
            return TATGEngineAdapter._try_recover_truncated_new_tests(text, fake)

    def test_recovers_one_complete_entry_from_truncated_json(self):
        complete_entry = (
            '{"overload_id":"O1","test_behavior":"b","test_name":"t1",'
            '"test_code_lines":["@Test","public void t1(){}"],'
            '"new_imports_lines":[]}'
        )
        truncated = '{"new_tests": [' + complete_entry + ', {"overload_id":"O2","test_code_lines":["@Test","public void t2() {'
        import json
        result = TATGEngineAdapter._try_recover_truncated_new_tests(
            truncated, json.JSONDecodeError("Unexpected end of data", truncated, len(truncated) - 1)
        )
        assert result is not None
        assert len(result["new_tests"]) == 1
        assert result["new_tests"][0]["overload_id"] == "O1"

    def test_returns_none_for_non_truncation_error(self):
        import json
        bad = '{"new_tests": [{"bad": true}'
        result = TATGEngineAdapter._try_recover_truncated_new_tests(
            bad, json.JSONDecodeError("Expecting value", bad, 5)
        )
        assert result is None

    def test_returns_none_when_no_new_tests_key(self):
        import json
        text = '{"other": ["'
        result = TATGEngineAdapter._try_recover_truncated_new_tests(
            text, json.JSONDecodeError("Unexpected end of data", text, len(text) - 1)
        )
        assert result is None

    def test_recovers_multiple_complete_entries(self):
        import json
        e1 = '{"overload_id":"O1","test_code_lines":["@Test","public void t1(){}"],"new_imports_lines":[]}'
        e2 = '{"overload_id":"O2","test_code_lines":["@Test","public void t2(){}"],"new_imports_lines":[]}'
        truncated = '{"new_tests": [' + e1 + "," + e2 + ', {"overload_id":"O3","test_code_lines":["@Test","public void t3() {'
        result = TATGEngineAdapter._try_recover_truncated_new_tests(
            truncated, json.JSONDecodeError("Unexpected end of data", truncated, len(truncated) - 1)
        )
        assert result is not None
        assert len(result["new_tests"]) == 2

    def test_recovers_first_incomplete_entry_when_test_method_is_complete(self):
        import json
        truncated = (
            '{"new_tests": [{"overload_id":"O1","test_name":"testO1",'
            '"coverage_obligation_id":"O1",'
            '"test_code_lines":["@Test","public void testO1() {",'
            '"    int result = 1;","    assertEquals(1, result);","}"],'
            '"new_imports_lines":["import static org.junit.jupiter.api.Assertions.assertEquals;"],'
            '"unfinished":"'
        )
        result = TATGEngineAdapter._try_recover_truncated_new_tests(
            truncated, json.JSONDecodeError("Unexpected end of data", truncated, len(truncated) - 1)
        )
        assert result is not None
        assert len(result["new_tests"]) == 1
        assert result["new_tests"][0]["test_name"] == "testO1"
        assert result["new_tests"][0]["coverage_obligation_id"] == "O1"
        assert "assertEquals" in "\n".join(result["new_tests"][0]["test_code_lines"])

    def test_extract_patch_metadata_records_truncated_json_salvage(self):
        truncated = (
            '{"new_tests": [{"overload_id":"O1","test_name":"testO1",'
            '"coverage_obligation_id":"O1",'
            '"test_code_lines":["@Test","public void testO1() {",'
            '"    int result = 1;","    assertEquals(1, result);","}"],'
            '"new_imports_lines":["import static org.junit.jupiter.api.Assertions.assertEquals;"],'
            '"unfinished":"'
        )

        patch, metadata = TATGEngineAdapter._extract_patch_from_json_output(
            truncated,
            target_call_names=None,
            require_observable_check=True,
            return_metadata=True,
        )

        assert "public void testO1()" in patch
        assert metadata["salvaged_truncated_json_response"] is True
        assert metadata["salvaged_truncated_new_tests_count"] == 1

    def test_returns_none_when_first_incomplete_entry_has_no_balanced_test_method(self):
        import json
        truncated = '{"new_tests": [{"overload_id":"O1","test_code_lines":["@Test","public void t1() {","    assertEquals(1, 1);'
        result = TATGEngineAdapter._try_recover_truncated_new_tests(
            truncated, json.JSONDecodeError("Unexpected end of data", truncated, len(truncated) - 1)
        )
        assert result is None


class TestIsPackagePrivateInSource:
    """_is_package_private_in_source: detects package-private method declarations."""

    def _check(self, method_name, source):
        return TATGEngineAdapter._is_package_private_in_source(method_name, source)

    def test_package_private_method_detected(self):
        source = "class X {\n    String compute(int n) {\n        return String.valueOf(n);\n    }\n}"
        assert self._check("compute", source) is True

    def test_preanalysis_preserves_package_private_access_from_selected_block(self, monkeypatch, tmp_path: Path):
        source_file = tmp_path / "src/main/java/com/acme/X.java"
        source_file.parent.mkdir(parents=True)
        source = "package com.acme; class X { String compute(int n) { return String.valueOf(n); } }"
        source_file.write_text(source, encoding="utf-8")
        monkeypatch.setattr("tatg.engines.tatg_adapter.build_static_analysis_context", lambda **_kwargs: "")
        monkeypatch.setattr(
            "tatg.engines.tatg_adapter.build_type_aware_context",
            lambda *_args, **_kwargs: SimpleNamespace(
                type_shapes={},
                mock_scaffold=None,
                autowired_deps=[],
                branch_hints=[],
                execution_recipes=[],
            ),
        )
        request = SimpleNamespace(project_root=tmp_path)
        target = Target(scope=Scope.METHOD, source_file=source_file, class_name="X", method_name="compute")

        preanalysis = TATGEngineAdapter().build_preanalysis_context(request, target, source_file, source)

        assert preanalysis["method_is_package_private"] is True
        assert preanalysis["method_is_private"] is False
        assert preanalysis["method_is_protected"] is False

    def test_public_method_returns_false(self):
        source = "class X {\n    public String compute(int n) { return null; }\n}"
        assert self._check("compute", source) is False

    def test_private_method_returns_false(self):
        source = "class X {\n    private String compute(int n) { return null; }\n}"
        assert self._check("compute", source) is False

    def test_protected_method_returns_false(self):
        source = "class X {\n    protected String compute(int n) { return null; }\n}"
        assert self._check("compute", source) is False

    def test_call_site_without_declaration_returns_false(self):
        """A method called but not declared here is not package-private in this class."""
        source = "class X {\n    public void run() { helper(42); }\n}"
        assert self._check("helper", source) is False

    def test_missing_method_returns_false(self):
        source = "class X {\n    public void run() {}\n}"
        assert self._check("compute", source) is False


