# P1a: _sanitize_java_backticks
# ──────────────────────────────────────────────────────────────────────────────

class TestSanitizeJavaBackticks:
    def _san(self, code: str) -> str:
        return TATGEngineAdapter._sanitize_java_backticks(code)

    def test_no_backticks_unchanged(self):
        code = 'public void foo() { System.out.println("hello"); }'
        assert self._san(code) == code

    def test_backtick_in_line_comment_becomes_single_quote(self):
        code = "// use `value` here\nint x = 1;"
        result = self._san(code)
        assert "`" not in result
        assert "'" in result  # replaced with single quote
        assert "int x = 1;" in result

    def test_backtick_in_block_comment_becomes_single_quote(self):
        code = "/* use `value` for this */\nint x = 1;"
        result = self._san(code)
        assert "`" not in result
        assert "'" in result

    def test_backtick_in_string_literal_becomes_unicode_escape(self):
        code = 'String s = "has`backtick";'
        result = self._san(code)
        assert "`" not in result
        assert "\\u0060" in result

    def test_backtick_in_code_outside_literals_removed(self):
        code = "int x = `1`;"
        result = self._san(code)
        assert "`" not in result
        assert "1" in result

    def test_multiple_contexts(self):
        code = '// comment `x`\nString s = "val`ue";\nint z = `1`;'
        result = self._san(code)
        assert "`" not in result

    def test_escaped_backslash_before_quote_in_string_not_confused(self):
        code = r'String s = "path\\end`x";'
        result = self._san(code)
        assert "`" not in result

    def test_char_literal_backtick_unicode_escaped(self):
        # char literal with backtick inside should be treated as string context
        code = "char c = '`';"
        result = self._san(code)
        assert "`" not in result


