class TestDetectJunitFamily:
    def _detect(self, source: str) -> str:
        return TATGEngineAdapter._detect_junit_family(source)

    def test_junit5_detected_from_jupiter_import(self):
        src = "import org.junit.jupiter.api.Test;\npublic class FooTest {}"
        assert self._detect(src) == "junit5"

    def test_junit4_detected_from_test_import(self):
        src = "import org.junit.Test;\npublic class FooTest {}"
        assert self._detect(src) == "junit4"

    def test_junit4_detected_from_runner_import(self):
        src = "import org.junit.runner.RunWith;\npublic class FooTest {}"
        assert self._detect(src) == "junit4"

    def test_junit4_detected_from_runwith_annotation(self):
        src = "@RunWith(JUnit4.class)\npublic class FooTest {}"
        assert self._detect(src) == "junit4"

    def test_junit4_detected_from_before_import(self):
        src = "import org.junit.Before;\npublic class FooTest {}"
        assert self._detect(src) == "junit4"

    def test_unknown_for_empty_string(self):
        assert self._detect("") == "unknown"

    def test_unknown_for_whitespace_only(self):
        assert self._detect("   \n  ") == "unknown"

    def test_unknown_for_unrecognized_imports(self):
        src = "import com.example.MyTest;\npublic class FooTest {}"
        assert self._detect(src) == "unknown"

    def test_junit5_wins_over_junit4_when_both_present(self):
        src = "import org.junit.jupiter.api.Test;\nimport org.junit.Test;\npublic class FooTest {}"
        assert self._detect(src) == "junit5"


