class TestRepairJsonCommon:
    import json as _json

    def _repair(self, text: str) -> str:
        return TATGEngineAdapter._repair_json_common(text)

    def test_valid_json_unchanged(self):
        text = '{"key": "value", "arr": [1, 2, 3]}'
        assert self._repair(text) == text

    def test_trailing_comma_before_brace_removed(self):
        text = '{"key": "value",}'
        repaired = self._repair(text)
        import json
        parsed = json.loads(repaired)
        assert parsed["key"] == "value"

    def test_trailing_comma_before_bracket_removed(self):
        text = '{"arr": [1, 2, 3,]}'
        repaired = self._repair(text)
        import json
        parsed = json.loads(repaired)
        assert parsed["arr"] == [1, 2, 3]

    def test_line_comment_removed(self):
        text = '{\n"key": "val" // this is a comment\n}'
        repaired = self._repair(text)
        import json
        parsed = json.loads(repaired)
        assert parsed["key"] == "val"

    def test_comment_inside_string_not_removed(self):
        text = '{"code": "int x = a; // comment stays"}'
        repaired = self._repair(text)
        # The // is inside a string value so it should remain valid JSON
        import json
        parsed = json.loads(repaired)
        assert "// comment stays" in parsed["code"]

    def test_null_bytes_removed(self):
        text = '{"key": "val\x00ue"}'
        repaired = self._repair(text)
        assert "\x00" not in repaired

    def test_trailing_comma_and_comment_combined(self):
        text = '{\n"a": 1, // comment\n"b": 2,\n}'
        repaired = self._repair(text)
        import json
        parsed = json.loads(repaired)
        assert parsed["a"] == 1
        assert parsed["b"] == 2


