def test_generation_control_receipt_promotes_producer_terminal_execution_path():
    source_call_state_plan = """
[Source-Derived Target State/Call Plan]
collaborator_calls_seen_in_target:
- worker:Worker.execute(...); exact visible signatures: void execute(RequestContext, ResultEmitter); declared_return=void
"""
    symbol_grounding = """
Body-used helper types (exact signatures — do not invent methods):
  ResultEmitter:
    - ResultEmitter(RequestContext context)
    - String getTaskId()
    - void complete()
    - void fail(ErrorPayload error)
    - void addArtifact(List<Part<?>> parts)
    - void consumeAndBreakOnInterrupt(Object value)
"""
    receipt = TATGEngineAdapter._render_generation_control_receipt(
        target_desc="WorkerHost.run",
        method_name="run",
        patch_mode=True,
        suggested_tests=4,
        source_call_state_plan=source_call_state_plan,
        symbol_grounding=symbol_grounding,
    )
    assert "source_required_terminal_execution_path" in receipt
    assert "worker:Worker.execute" in receipt
    assert "ResultEmitter" in receipt
    assert "void complete()" in receipt
