# ---------------------------------------------------------------------------
# Round-batching orchestrator
#
# The helpers that size a round are unit-tested above.  These cover the
# orchestration itself, which is where the accumulation invariant lives: with
# ``defer_test_writes`` nothing is on disk between batches, so a batch that does
# not receive the previous batch's file content would silently overwrite it.
# ---------------------------------------------------------------------------


def _round_batching_request(tmp_path: Path) -> tuple[GenerationRequest, Target]:
    source_file = tmp_path / "Foo.java"
    source_file.write_text("public class Foo { int bar(int a) { return a; } }", encoding="utf-8")
    target = Target(
        scope=Scope.METHOD,
        source_file=source_file,
        class_name="Foo",
        method_name="bar",
    )
    request = GenerationRequest(
        backend="tatg",
        scope=Scope.METHOD,
        project_root=tmp_path,
        target_file=source_file,
        class_name="Foo",
        method_name="bar",
        model="test-model",
        api_base="http://example.invalid/v1",
        api_key_env="OPENAI_API_KEY",
        test_command="mvn test",
        coverage_report_path="",
        coverage_type="jacoco",
        prompt_extra_text="",
        prompt_extra_file=None,
        prompt_insert=PromptInsertPosition.AFTER_USER,
        static_analysis_json=None,
        pass_specs=[],
        dry_run=False,
        max_iterations=2,
        cat_engine_root=tmp_path,
        method_engine_root=tmp_path,
        junit_family="junit4",
    )
    # A wide measured gap so the round plans several batches.
    request.generation_coverage_feedback_by_label = {target.label: {"branch_missed": 60}}
    return request, target


def _give_sliceable_obligations(monkeypatch, count: int = 9) -> None:
    """Supply disjoint obligations, the only thing that differentiates batches."""

    monkeypatch.setattr(
        TATGEngineAdapter,
        "_required_obligation_ids_for_feedback",
        staticmethod(lambda feedback: {f"O{index}" for index in range(1, count + 1)}),
    )


def test_round_batching_threads_accumulated_file_between_batches(tmp_path, monkeypatch):
    """Batch N+1 must see the file produced by batch N.

    Writes are deferred, so nothing is on disk mid-round.  If the accumulated
    content were not threaded in memory the later batch would rebuild from the
    bare skeleton and its patch would drop every earlier test.
    """

    # Batching is a retired strategy and off by default; these tests cover
    # the machinery as an opt-in control arm, so they must ask for it.
    monkeypatch.setenv("TATG_ROUND_BATCHING", "1")
    request, target = _round_batching_request(tmp_path)
    _give_sliceable_obligations(monkeypatch)
    seeds: list[str | None] = []

    def fake_once(self, req, tgt, root, cmd, key_env, *, batch_index=0,
                  batch_obligation_slice=None, seed_file_content=None):
        seeds.append(seed_file_content)
        return {"status": "success", "final_code": f"file-after-batch-{batch_index}"}

    monkeypatch.setattr(TATGEngineAdapter, "_generate_test_for_target_once", fake_once)
    adapter = TATGEngineAdapter()
    result = adapter.generate_test_for_target(request, target, tmp_path, "mvn test")

    assert len(seeds) > 1, "a 60-branch gap should plan more than one batch"
    assert seeds[0] is None, "the first batch starts from the on-disk skeleton"
    # Every later batch receives the immediately preceding batch's file.
    for index in range(1, len(seeds)):
        assert seeds[index] == f"file-after-batch-{index - 1}"
    assert result["final_code"] == f"file-after-batch-{len(seeds) - 1}"
    assert result["tatg_round_batches_run"] == len(seeds)
    assert result["tatg_round_uncovered_branches"] == 60


def test_round_batching_stops_when_a_batch_adds_nothing(tmp_path, monkeypatch):
    """A batch that returns the same file as before ends the round.

    Without this the remaining batches would re-issue an identical request and
    spend the round's latency budget reproducing work already done.
    """

    # Batching is a retired strategy and off by default; these tests cover
    # the machinery as an opt-in control arm, so they must ask for it.
    monkeypatch.setenv("TATG_ROUND_BATCHING", "1")
    request, target = _round_batching_request(tmp_path)
    _give_sliceable_obligations(monkeypatch)
    calls: list[int] = []

    def fake_once(self, req, tgt, root, cmd, key_env, *, batch_index=0,
                  batch_obligation_slice=None, seed_file_content=None):
        calls.append(batch_index)
        return {"status": "success", "final_code": "unchanged"}

    monkeypatch.setattr(TATGEngineAdapter, "_generate_test_for_target_once", fake_once)
    result = TATGEngineAdapter().generate_test_for_target(request, target, tmp_path, "mvn test")

    assert calls == [0, 1], "batch 1 repeats batch 0's file, so the round stops there"
    assert result["tatg_round_batches_run"] == 2


