def test_round_batching_unions_obligation_ids_across_batches(tmp_path, monkeypatch):
    """Downstream feedback must see the whole round, not just its last slice.

    Each batch is told about one disjoint slice of the obligations, so the last
    batch's result alone under-reports what the round covered.
    """

    # Batching is a retired strategy and off by default; these tests cover
    # the machinery as an opt-in control arm, so they must ask for it.
    monkeypatch.setenv("TATG_ROUND_BATCHING", "1")
    request, target = _round_batching_request(tmp_path)

    def fake_once(self, req, tgt, root, cmd, key_env, *, batch_index=0,
                  batch_obligation_slice=None, seed_file_content=None):
        return {
            "status": "success",
            "final_code": f"code-{batch_index}",
            "tatg_bound_required_obligation_ids": [f"O{batch_index + 1}"],
            "tatg_generation_attempt_count": 1,
        }

    monkeypatch.setattr(TATGEngineAdapter, "_generate_test_for_target_once", fake_once)
    result = TATGEngineAdapter().generate_test_for_target(request, target, tmp_path, "mvn test")

    ran = result["tatg_round_batches_run"]
    assert result["tatg_bound_required_obligation_ids"] == [f"O{i + 1}" for i in range(ran)]
    # Per-batch counters are summed, not taken from the last batch alone.
    assert result["tatg_generation_attempt_count"] == ran


def test_round_batching_does_not_issue_undifferentiated_batches(tmp_path, monkeypatch):
    """A wide coverage gap alone must not multiply the LLM calls.

    Regression for a measured failure on Rotation.getAngles: a 49-branch gap
    with no sliceable obligations planned four batches, and because the
    coverage-feedback prompt template does not render the accumulated test
    file, all four rendered byte-identical prompts.  The round cost ~4x the
    latency and returned near-duplicates.  Batching must follow the disjoint
    work available, not the raw budget.
    """

    # Batching is a retired strategy and off by default; these tests cover
    # the machinery as an opt-in control arm, so they must ask for it.
    monkeypatch.setenv("TATG_ROUND_BATCHING", "1")
    request, target = _round_batching_request(tmp_path)
    # A wide gap, but nothing to slice: exactly the observed situation.
    request.generation_coverage_feedback_by_label = {target.label: {"branch_missed": 49}}
    monkeypatch.setattr(
        TATGEngineAdapter, "_required_obligation_ids_for_feedback",
        staticmethod(lambda feedback: set()),
    )
    calls: list[int] = []

    def fake_once(self, req, tgt, root, cmd, key_env, *, batch_index=0,
                  batch_obligation_slice=None, seed_file_content=None):
        calls.append(batch_index)
        return {"status": "success", "final_code": f"code-{batch_index}"}

    monkeypatch.setattr(TATGEngineAdapter, "_generate_test_for_target_once", fake_once)
    result = TATGEngineAdapter().generate_test_for_target(request, target, tmp_path, "mvn test")

    assert calls == [0], "no disjoint slices means exactly one call"
    assert result["tatg_round_batches_planned"] == 1


def test_round_batching_still_splits_real_disjoint_obligations(tmp_path, monkeypatch):
    """The guard must not disable batching where it genuinely applies."""

    # Batching is a retired strategy and off by default; these tests cover
    # the machinery as an opt-in control arm, so they must ask for it.
    monkeypatch.setenv("TATG_ROUND_BATCHING", "1")
    request, target = _round_batching_request(tmp_path)
    request.generation_coverage_feedback_by_label = {target.label: {"branch_missed": 60}}
    monkeypatch.setattr(
        TATGEngineAdapter, "_required_obligation_ids_for_feedback",
        staticmethod(lambda feedback: {f"O{i}" for i in range(1, 10)}),
    )
    slices: list[set[str] | None] = []

    def fake_once(self, req, tgt, root, cmd, key_env, *, batch_index=0,
                  batch_obligation_slice=None, seed_file_content=None):
        slices.append(batch_obligation_slice)
        return {"status": "success", "final_code": f"code-{batch_index}"}

    monkeypatch.setattr(TATGEngineAdapter, "_generate_test_for_target_once", fake_once)
    TATGEngineAdapter().generate_test_for_target(request, target, tmp_path, "mvn test")

    assert len(slices) > 1, "9 obligations over a 4-test response budget must split"
    # Every batch owns a distinct, non-empty slice.
    assert all(s for s in slices)
    seen: set[str] = set()
    for s in slices:
        assert not (seen & s), "slices must be disjoint"
        seen |= s


