# ---------------------------------------------------------------------------
# Focused semantic-replay feedback prompt
#
# This prompt replaces the entire broad-round user prompt.  Dropping the
# coverage-feedback section from it left the feedback round blind to the
# branches it had just failed to cover: measured at 6 150 prompt chars against
# round 1's 59 666, with coverage_feedback_present=False.
# ---------------------------------------------------------------------------


_FOCUS_FRONTIER = """[Source-Derived Frontier Candidate Sketches]
- SK1; source_sketch=SK1; reach the singularity guard
"""


def _focus_prompt(**overrides):
    kwargs = dict(
        frontier_sketch_section=_FOCUS_FRONTIER,
        target_descriptor="(Lorg/example/Order;)[D",
        target_method="getAngles",
    )
    kwargs.update(overrides)
    return TATGEngineAdapter._semantic_replay_focus_prompt(**kwargs)


def test_focus_prompt_omits_unmatched_broad_coverage_feedback():
    """A focused row must not inherit unrelated broad-round objectives."""

    section = (
        "[Coverage Feedback For This Generation Round]\n"
        "branch_missed=59 of 70\n"
        "uncovered: Rotation.java:1203 singularity guard\n"
    )
    prompt = _focus_prompt(coverage_feedback_section=section)

    assert "[Coverage Feedback For This Generation Round]" not in prompt
    assert "branch_missed=59 of 70" not in prompt
    assert "Rotation.java:1203" not in prompt
    assert "[Source-Derived Frontier Candidate Sketches]" in prompt


def test_focus_prompt_still_renders_without_coverage_feedback():
    """Absent feedback must not add an empty header or break the prompt."""

    prompt = _focus_prompt(coverage_feedback_section="")

    assert "[Coverage Feedback For This Generation Round]" not in prompt
    assert "[Strict Output Schema]" in prompt


def test_focus_prompt_drops_unmatched_large_coverage_feedback(monkeypatch):
    """A large broad section cannot leak into a focused replay call."""

    monkeypatch.setenv("TATG_FOCUS_PROMPT_MAX_COVERAGE_FEEDBACK_CHARS", "1000")
    section = (
        "[Coverage Feedback For This Generation Round]\n"
        + "\n".join(f"uncovered: Rotation.java:{line}" for line in range(2000))
    )
    prompt = _focus_prompt(coverage_feedback_section=section)

    assert "[Coverage Feedback For This Generation Round]" not in prompt
    assert len(prompt) < len(section), "an unbounded section defeats the focused call"


def test_focus_prompt_removes_competing_feedback_oids():
    """Focused SK generation must not carry broad O-id instructions."""

    section = (
        "[Coverage Feedback For This Generation Round]\n"
        "O3: cover the singularity guard\n"
    )
    prompt = _focus_prompt(coverage_feedback_section=section)

    assert "leave coverage_obligation_id empty" in prompt
    assert "O3:" not in prompt


def test_focus_prompt_coverage_feedback_can_be_disabled_for_a_control_arm(monkeypatch):
    """The pre-fix prompt must stay reproducible without editing code."""

    section = (
        "[Coverage Feedback For This Generation Round]\nbranch_missed=59 of 70\n"
    )
    monkeypatch.setenv("TATG_FOCUS_PROMPT_COVERAGE_FEEDBACK", "0")
    assert "[Coverage Feedback For This Generation Round]" not in _focus_prompt(
        coverage_feedback_section=section
    )
    monkeypatch.setenv("TATG_FOCUS_PROMPT_COVERAGE_FEEDBACK", "1")
    # Enabling the feature does not bypass the exact line-identity filter.
    assert "[Coverage Feedback For This Generation Round]" not in _focus_prompt(
        coverage_feedback_section=section
    )


def test_method_patch_json_test_budget_cap_is_configurable(monkeypatch):
    """The per-response cap is the binding ceiling on tests per target.

    At 4 per response over 2 generation rounds no target can exceed 8 tests,
    and the S1 baseline already sits at that ceiling.  The knob exists so the
    ceiling can be A/B'd rather than assumed; default stays 4.
    """

    monkeypatch.delenv("TATG_MAX_TESTS_PER_RESPONSE", raising=False)
    assert TATGEngineAdapter._method_patch_json_test_budget(16) == 4

    monkeypatch.setenv("TATG_MAX_TESTS_PER_RESPONSE", "6")
    assert TATGEngineAdapter._method_patch_json_test_budget(16) == 6
    # Still bounded by what was actually requested.
    assert TATGEngineAdapter._method_patch_json_test_budget(3) == 3

    # Out-of-range and junk values must not produce a degenerate budget.
    monkeypatch.setenv("TATG_MAX_TESTS_PER_RESPONSE", "999")
    assert TATGEngineAdapter._method_patch_json_test_budget(50) == 12
    monkeypatch.setenv("TATG_MAX_TESTS_PER_RESPONSE", "nonsense")
    assert TATGEngineAdapter._method_patch_json_test_budget(16) == 4


def test_branch_density_guidance_targets_scan_dispatch_methods(monkeypatch):
    """Density is a property of the test, not the method -- so it is improvable.

    Measured: branches per ACCEPTED test spans 1.5-19.0, median 3.29.
    Metaphone.metaphone reaches 9.60 while the near-identical
    DoubleMetaphone.doubleMetaphone gets 2.14.  Nothing in the prompt mentions
    density, so the model defaults to one-scenario-per-test and lands at ~3.
    """

    scan_dispatch = """
        public String encode(String txt) {
            for (int n = 0; n < txt.length(); n++) {
                switch (txt.charAt(n)) {
                    case 'A': out.append('1'); break;
                    case 'B': out.append('2'); break;
                }
            }
            return out.toString();
        }
    """
    plain = "public int add(int a, int b) { if (a > b) { return a; } return b; }"

    monkeypatch.delenv("TATG_BRANCH_DENSITY_GUIDANCE", raising=False)
    assert TATGEngineAdapter._branch_density_guidance_lines(scan_dispatch, "encode") == [], (
        "must be off by default"
    )

    monkeypatch.setenv("TATG_BRANCH_DENSITY_GUIDANCE", "1")
    lines = TATGEngineAdapter._branch_density_guidance_lines(scan_dispatch, "encode")
    assert lines and any("Branch density" in x for x in lines)
    # The assertion must not be allowed to weaken in exchange for density.
    assert any("exact observable outcome" in x for x in lines)

    # A method with independent parameter guards must NOT get this advice:
    # bundling its branches into one call would just produce an unfocused test.
    assert TATGEngineAdapter._branch_density_guidance_lines(plain, "add") == []
    assert TATGEngineAdapter._branch_density_guidance_lines("", "encode") == []
